// Recreates src (285 files): `node <this file> [destination]`, in the folder
// that receives them (the current folder by default). Existing files are kept unless `--force` is given.

import fs from 'node:fs';
import path from 'node:path';

const FILES = [
  ["src/async/index.ts", "// Async: waiting, cancellable with an abort signal.\n\nexport { sleep } from './sleep';\n"],
  ["src/async/sleep.spec.ts", "import { sleep } from './sleep';\n\ndescribe(sleep, () => {\n  beforeEach(() => {\n    vi.useFakeTimers();\n  });\n\n  afterEach(() => {\n    vi.useRealTimers();\n  });\n\n  it('resolves after the delay', async () => {\n    const onResolved = vi.fn<() => void>();\n    async function sleepThenNotify(): Promise<void> {\n      await sleep(100);\n      onResolved();\n    }\n    const promise = sleepThenNotify();\n    await vi.advanceTimersByTimeAsync(99);\n    expect(onResolved).not.toHaveBeenCalled();\n    await vi.advanceTimersByTimeAsync(1);\n    await promise;\n    expect(onResolved).toHaveBeenCalledOnce();\n  });\n\n  it('rejects when the signal is aborted, and clears the timer', async () => {\n    const controller = new AbortController();\n    const promise = sleep(100, controller.signal);\n    controller.abort();\n    await expect(promise).rejects.toThrow(expect.objectContaining({ name: 'AbortError' }));\n    expect(vi.getTimerCount()).toBe(0);\n  });\n\n  it('rejects at once when the signal is already aborted', async () => {\n    await expect(sleep(100, AbortSignal.abort(new Error('Stopped')))).rejects.toThrow('Stopped');\n    expect(vi.getTimerCount()).toBe(0);\n  });\n\n  it('wraps a non-error abort reason', async () => {\n    const controller = new AbortController();\n    const promise = sleep(100, controller.signal);\n    controller.abort('cancelled');\n    await expect(promise).rejects.toThrow('cancelled');\n  });\n\n  it('removes its abort listener once resolved', async () => {\n    const controller = new AbortController();\n    const removeListener = vi.spyOn(controller.signal, 'removeEventListener');\n    const promise = sleep(10, controller.signal);\n    await vi.advanceTimersByTimeAsync(10);\n    await promise;\n    expect(removeListener).toHaveBeenCalledOnce();\n  });\n});\n"],
  ["src/async/sleep.ts", "function abortReason(signal: AbortSignal): Error {\n  const reason: unknown = signal.reason;\n  return reason instanceof Error ? reason : new Error(String(reason));\n}\n\n/**\n * Waits for a delay, cancellable with an `AbortSignal` that clears the timer.\n *\n * @param ms - The delay in milliseconds. Defaults to `0`.\n * @param signal - The signal that cancels the wait.\n * @returns A promise resolved once the delay has elapsed.\n * @rejects {Error} With the signal's reason when `signal` is aborted.\n * @example\n * await sleep(100);\n * await sleep(1000, controller.signal); // rejects as soon as controller.abort() is called\n */\nexport async function sleep(ms = 0, signal?: AbortSignal): Promise<void> {\n  return new Promise<void>((resolve, reject) => {\n    if (signal?.aborted === true) {\n      reject(abortReason(signal));\n      return;\n    }\n    const timer = setTimeout(() => {\n      signal?.removeEventListener('abort', onAbort);\n      resolve();\n    }, ms);\n    function onAbort(this: AbortSignal): void {\n      clearTimeout(timer);\n      reject(abortReason(this));\n    }\n    signal?.addEventListener('abort', onAbort, { once: true });\n  });\n}\n"],
  ["src/color/get-contrasting-text-color.spec.ts", "import { getContrastingTextColor } from './get-contrasting-text-color';\n\ndescribe(getContrastingTextColor, () => {\n  it.for([\n    [{ r: 255, g: 255, b: 255 }, '#000000'],\n    [{ r: 255, g: 255, b: 0 }, '#000000'],\n    [{ r: 180, g: 180, b: 180 }, '#000000'],\n    [{ r: 0, g: 0, b: 0 }, '#ffffff'],\n    [{ r: 255, g: 0, b: 0 }, '#ffffff'],\n    [{ r: 0, g: 0, b: 255 }, '#ffffff'],\n    [{ r: 128, g: 128, b: 128 }, '#ffffff'],\n  ] as const)('writes on %j in %s', ([background, expected]) => {\n    expect(getContrastingTextColor(background)).toBe(expected);\n  });\n});\n"],
  ["src/color/get-contrasting-text-color.ts", "import type { Rgb } from './rgb';\n\nconst MAX_CHANNEL = 255;\nconst GAMMA = 2.4;\nconst RED_WEIGHT = 0.212_672_9;\nconst GREEN_WEIGHT = 0.715_152_2;\nconst BLUE_WEIGHT = 0.072_175;\nconst BLACK_THRESHOLD = 0.022;\nconst BLACK_CLAMP = 1.414;\nconst DARK_TEXT_BACKGROUND = 0.56;\nconst DARK_TEXT = 0.57;\nconst LIGHT_TEXT_BACKGROUND = 0.65;\nconst BLACK_LUMINANCE = BLACK_THRESHOLD ** BLACK_CLAMP;\n\nfunction getLuminance({ r, g, b }: Rgb): number {\n  const luminance =\n    RED_WEIGHT * (r / MAX_CHANNEL) ** GAMMA +\n    GREEN_WEIGHT * (g / MAX_CHANNEL) ** GAMMA +\n    BLUE_WEIGHT * (b / MAX_CHANNEL) ** GAMMA;\n  return luminance < BLACK_THRESHOLD ? luminance + (BLACK_THRESHOLD - luminance) ** BLACK_CLAMP : luminance;\n}\n\n/**\n * Picks the text color, pure black or pure white, that reads best on a background. Uses the APCA contrast\n * of WCAG 3, closer to perception than the WCAG 2 ratio: white wins on a saturated red, for instance.\n *\n * @param background - The background color, such as the result of `getSvgFillColor`.\n * @returns `'#000000'` or `'#ffffff'`.\n * @example\n * getContrastingTextColor({ r: 255, g: 255, b: 0 }); // '#000000'\n * getContrastingTextColor({ r: 255, g: 0, b: 0 }); // '#ffffff'\n * label.setAttribute('fill', getContrastingTextColor(getSvgFillColor(tank)));\n */\nexport function getContrastingTextColor(background: Rgb): '#000000' | '#ffffff' {\n  const luminance = getLuminance(background);\n  const blackTextContrast = luminance ** DARK_TEXT_BACKGROUND - BLACK_LUMINANCE ** DARK_TEXT;\n  const whiteTextContrast = 1 - luminance ** LIGHT_TEXT_BACKGROUND;\n  return blackTextContrast >= whiteTextContrast ? '#000000' : '#ffffff';\n}\n"],
  ["src/color/get-svg-fill-color.spec.ts", "import { getSvgFillColor } from './get-svg-fill-color';\n\ndescribe(getSvgFillColor, () => {\n  const element = {} as SVGGraphicsElement;\n\n  afterEach(() => {\n    vi.unstubAllGlobals();\n  });\n\n  it.for([\n    ['rgb(0, 128, 255)', { r: 0, g: 128, b: 255 }],\n    ['rgba(10, 20, 30, 0.5)', { r: 10, g: 20, b: 30 }],\n    ['rgb(10 20 30)', { r: 10, g: 20, b: 30 }],\n  ] as const)('reads %s', ([fill, expected]) => {\n    vi.stubGlobal('getComputedStyle', () => ({ fill }));\n    expect(getSvgFillColor(element)).toStrictEqual(expected);\n  });\n\n  it.for(['none', 'url(\"#gradient\")'])('throws a TypeError for %s', (fill) => {\n    vi.stubGlobal('getComputedStyle', () => ({ fill }));\n    expect(() => getSvgFillColor(element)).toThrow(TypeError);\n  });\n});\n"],
  ["src/color/get-svg-fill-color.ts", "import type { Rgb } from './rgb';\n\nconst RGB_PATTERN = /^rgba?\\((?<r>[\\d.]+)[,\\s]+(?<g>[\\d.]+)[,\\s]+(?<b>[\\d.]+)/v;\n\n/**\n * Reads the fill color of an SVG element as rendered, whatever sets it: attribute, class, inherited style.\n *\n * @param element - A rendered SVG element.\n * @returns The fill color.\n * @throws {TypeError} When the fill is not an sRGB color, such as `none` or a gradient.\n * @example\n * getSvgFillColor(tank); // { r: 0, g: 128, b: 255 }\n */\nexport function getSvgFillColor(element: SVGGraphicsElement): Rgb {\n  const { fill } = getComputedStyle(element);\n  const groups = RGB_PATTERN.exec(fill)?.groups;\n  if (!groups) {\n    throw new TypeError(`The fill is not an sRGB color: '${fill}'`);\n  }\n  return { r: Number(groups['r']), g: Number(groups['g']), b: Number(groups['b']) };\n}\n"],
  ["src/color/index.ts", "// Colors: the fill of an SVG element, and the black or white text that reads best on it.\n\nexport type { Rgb } from './rgb';\nexport { getSvgFillColor } from './get-svg-fill-color';\nexport { getContrastingTextColor } from './get-contrasting-text-color';\n"],
  ["src/color/rgb.ts", "/** An sRGB color, each channel from 0 to 255. */\nexport interface Rgb {\n  readonly r: number;\n  readonly g: number;\n  readonly b: number;\n}\n"],
  ["src/duration/index.ts", "// Durations: parsing a .NET TimeSpan into milliseconds.\n\nexport { parseTimeSpan } from './parse-time-span';\n"],
  ["src/duration/parse-time-span.spec.ts", "import { parseTimeSpan } from './parse-time-span';\n\ndescribe(parseTimeSpan, () => {\n  it.for([\n    ['1.02:03:04.5670000', 93_784_567],\n    ['00:00:30', 30_000],\n    ['-00:00:30', -30_000],\n    ['1:02:03:04.567', 93_784_567],\n    ['  12:00:00  ', 43_200_000],\n    ['00:00:00.0000001', 0.0001],\n    ['00:00:00.5', 500],\n    ['00:00:00,25', 250],\n    ['10675199.02:48:05.4775807', 922_337_203_685_477.6],\n  ] as const)('parses %j as %s ms', ([input, expected]) => {\n    expect(parseTimeSpan(input)).toBeCloseTo(expected, 4);\n  });\n\n  it.for(['', '30', '1:2:3', '00:00:00.12345678', 'a.00:00:00', '1.2.00:00:00'])(\n    'throws a TypeError for %j',\n    (input) => {\n      expect(() => parseTimeSpan(input)).toThrow(TypeError);\n    },\n  );\n});\n"],
  ["src/duration/parse-time-span.ts", "const MS_PER_SECOND = 1000;\nconst MS_PER_MINUTE = 60_000;\nconst MS_PER_HOUR = 3_600_000;\nconst MS_PER_DAY = 86_400_000;\nconst TICKS_PER_MS = 10_000;\nconst TICK_DIGITS = 7;\n\nconst TIME_SPAN_PATTERN =\n  /^(?<sign>-)?(?:(?<days>\\d+)[.:])?(?<hours>\\d{1,2}):(?<minutes>\\d{2}):(?<seconds>\\d{2})(?:[,.](?<fraction>\\d{1,7}))?$/v;\n\n/**\n * Parses a .NET `TimeSpan` into milliseconds: the constant format `c` (`1.02:03:04.5670000`, the JSON one)\n * or the general formats `g` / `G` (`1:02:03:04.567`). The 100 ns ticks become decimals of milliseconds.\n *\n * @param input - The `TimeSpan` text; surrounding spaces are ignored.\n * @returns The duration in milliseconds, negative for a negative `TimeSpan`.\n * @throws {TypeError} When the text is not a `TimeSpan`.\n * @example\n * parseTimeSpan('1.02:03:04.5670000'); // 93784567\n * parseTimeSpan('-00:00:30'); // -30000\n */\nexport function parseTimeSpan(input: string): number {\n  const groups = TIME_SPAN_PATTERN.exec(input.trim())?.groups;\n  if (!groups) {\n    throw new TypeError(`Invalid TimeSpan: '${input}'`);\n  }\n  const ticks = Number((groups['fraction'] ?? '').padEnd(TICK_DIGITS, '0'));\n  const milliseconds =\n    Number(groups['days'] ?? 0) * MS_PER_DAY +\n    Number(groups['hours']) * MS_PER_HOUR +\n    Number(groups['minutes']) * MS_PER_MINUTE +\n    Number(groups['seconds']) * MS_PER_SECOND +\n    ticks / TICKS_PER_MS;\n  return groups['sign'] === undefined ? milliseconds : -milliseconds;\n}\n"],
  ["src/enum/enum-literal.spec.ts", "import type { EnumLiteral } from './enum-literal';\n\nenum Status {\n  Idle = 'idle',\n  Running = 'running',\n}\n\nenum Level {\n  Low = 0,\n  High = 1,\n}\n\ndescribe('EnumLiteral', () => {\n  it('turns a string enum into its string literals', () => {\n    expectTypeOf<EnumLiteral<Status>>().toEqualTypeOf<'idle' | 'running'>();\n  });\n\n  it('turns a numeric enum into its number literals', () => {\n    expectTypeOf<EnumLiteral<Level>>().toEqualTypeOf<0 | 1>();\n  });\n});\n"],
  ["src/enum/enum-literal.ts", "/**\n * Turns an enum type into the union of its literal values, so plain literals are accepted where the enum is\n * expected: `'idle' | 'running'` for a string enum, `0 | 1` for a numeric one.\n *\n * @template E - The enum type, such as `Status` (not `typeof Status`).\n * @example\n * enum Status { Idle = 'idle', Running = 'running' }\n * type StatusValue = EnumLiteral<Status>; // 'idle' | 'running'\n */\nexport type EnumLiteral<E extends number | string> = E extends string\n  ? `${E}`\n  : `${E}` extends `${infer N extends number}`\n    ? N\n    : never;\n"],
  ["src/enum/enum-object.ts", "/** Any TypeScript enum, or a `const` object used as one. */\nexport type EnumObject = Readonly<Record<string, number | string>>;\n"],
  ["src/enum/get-enum-entries.spec.ts", "import { getEnumEntries } from './get-enum-entries';\n\nenum Direction {\n  Up = 0,\n  Down = 1,\n}\n\nenum Status {\n  Idle = 'idle',\n  Running = 'running',\n}\n\ndescribe(getEnumEntries, () => {\n  it('lists name and value pairs without the reverse mapping', () => {\n    expect(getEnumEntries(Direction)).toStrictEqual([\n      ['Up', 0],\n      ['Down', 1],\n    ]);\n    expect(getEnumEntries(Status)).toStrictEqual([\n      ['Idle', 'idle'],\n      ['Running', 'running'],\n    ]);\n  });\n});\n"],
  ["src/enum/get-enum-entries.ts", "import type { EnumObject } from './enum-object';\n\n/**\n * Lists the members of an enum as `[name, value]` pairs, without the reverse mapping of numeric enums.\n *\n * @template E - The type of the enum object.\n * @param enumObject - The enum to read, such as `Direction`.\n * @returns The `[name, value]` pairs, in declaration order.\n * @example\n * enum Direction { Up, Down }\n * getEnumEntries(Direction); // [['Up', 0], ['Down', 1]]\n */\nexport function getEnumEntries<E extends EnumObject>(enumObject: E): [key: keyof E & string, value: E[keyof E]][] {\n  const entries: [keyof E & string, E[keyof E]][] = [];\n  for (const [key, value] of Object.entries(enumObject)) {\n    if (String(Number(key)) !== key) {\n      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion -- A value of `E`, read from `E`.\n      entries.push([key, value as E[keyof E]]);\n    }\n  }\n  return entries;\n}\n"],
  ["src/enum/get-enum-key.spec.ts", "import { getEnumKey } from './get-enum-key';\n\nenum Status {\n  Idle = 'idle',\n  Running = 'running',\n}\n\nenum Level {\n  Low = 0,\n  High = 1,\n}\n\ndescribe(getEnumKey, () => {\n  it('names the value of a string or numeric enum', () => {\n    expect(getEnumKey(Status, 'running')).toBe('Running');\n    expect(getEnumKey(Level, 1)).toBe('High');\n  });\n\n  it('returns undefined for a value outside the enum', () => {\n    expect(getEnumKey(Status, 'stopped')).toBeUndefined();\n    expect(getEnumKey(Level, '1')).toBeUndefined();\n  });\n});\n"],
  ["src/enum/get-enum-key.ts", "import type { EnumObject } from './enum-object';\nimport { getEnumEntries } from './get-enum-entries';\n\n/**\n * Finds the member name of an enum value, string enums included: a readable name for a log or a\n * translation key.\n *\n * @template E - The type of the enum object.\n * @param enumObject - The enum, such as `Status`.\n * @param value - The value to name.\n * @returns The first member name with this value; `undefined` when none has it.\n * @example\n * enum Status { Idle = 'idle', Running = 'running' }\n * getEnumKey(Status, 'running'); // 'Running'\n */\nexport function getEnumKey<E extends EnumObject>(enumObject: E, value: unknown): (keyof E & string) | undefined {\n  return getEnumEntries(enumObject).find(([, member]) => member === value)?.[0];\n}\n"],
  ["src/enum/get-enum-keys.spec.ts", "import { getEnumKeys } from './get-enum-keys';\n\nenum Direction {\n  Up = 0,\n  Down = 1,\n}\n\nenum Status {\n  Idle = 'idle',\n}\n\ndescribe(getEnumKeys, () => {\n  it('lists the member names without the reverse mapping', () => {\n    expect(getEnumKeys(Direction)).toStrictEqual(['Up', 'Down']);\n    expect(getEnumKeys(Status)).toStrictEqual(['Idle']);\n  });\n});\n"],
  ["src/enum/get-enum-keys.ts", "import type { EnumObject } from './enum-object';\nimport { getEnumEntries } from './get-enum-entries';\n\n/**\n * Lists the member names of an enum, without the reverse mapping of numeric enums.\n *\n * @template E - The type of the enum object.\n * @param enumObject - The enum to read, such as `Direction`.\n * @returns The member names, in declaration order.\n * @example\n * enum Direction { Up, Down }\n * getEnumKeys(Direction); // ['Up', 'Down']\n */\nexport function getEnumKeys<E extends EnumObject>(enumObject: E): (keyof E & string)[] {\n  return getEnumEntries(enumObject).map(([key]) => key);\n}\n"],
  ["src/enum/get-enum-values.spec.ts", "import { getEnumValues } from './get-enum-values';\n\nenum Direction {\n  Up = 0,\n  Down = 1,\n}\n\nenum Status {\n  Idle = 'idle',\n  Running = 'running',\n}\n\nenum Sparse {\n  Low = 1,\n  High = 10,\n}\n\ndescribe(getEnumValues, () => {\n  it('lists the values of a numeric enum without the reverse mapping', () => {\n    expect(getEnumValues(Direction)).toStrictEqual([0, 1]);\n    expect(getEnumValues(Sparse)).toStrictEqual([1, 10]);\n  });\n\n  it('lists the values of a string enum', () => {\n    expect(getEnumValues(Status)).toStrictEqual(['idle', 'running']);\n  });\n\n  it('lists the values of a const object used as an enum', () => {\n    expect(getEnumValues({ small: 's', large: 'l' } as const)).toStrictEqual(['s', 'l']);\n  });\n});\n"],
  ["src/enum/get-enum-values.ts", "import type { EnumObject } from './enum-object';\nimport { getEnumEntries } from './get-enum-entries';\n\n/**\n * Lists the values of an enum, without the names of the reverse mapping of numeric enums.\n *\n * @template E - The type of the enum object.\n * @param enumObject - The enum to read, such as `Direction`.\n * @returns The values, in declaration order.\n * @example\n * enum Direction { Up, Down }\n * getEnumValues(Direction); // [0, 1]\n */\nexport function getEnumValues<E extends EnumObject>(enumObject: E): E[keyof E][] {\n  return getEnumEntries(enumObject).map(([, value]) => value);\n}\n"],
  ["src/enum/index.ts", "// Enums: listing members, checking and reading untyped values, literal types.\n\nexport type { EnumObject } from './enum-object';\nexport { getEnumValues } from './get-enum-values';\nexport { isEnumValue } from './is-enum-value';\nexport { toEnumValue } from './to-enum-value';\nexport { getEnumEntries } from './get-enum-entries';\nexport { getEnumKeys } from './get-enum-keys';\nexport { parseEnumValue } from './parse-enum-value';\nexport type { EnumLiteral } from './enum-literal';\nexport { getEnumKey } from './get-enum-key';\n"],
  ["src/enum/is-enum-value.spec.ts", "import { isEnumValue } from './is-enum-value';\n\nenum Direction {\n  Up = 0,\n  Down = 1,\n}\n\nenum Color {\n  Red = 'red',\n  Green = 'green',\n}\n\nenum Sparse {\n  Low = 1,\n  High = 10,\n}\n\ndescribe(isEnumValue, () => {\n  it('accepts the values of a numeric enum, not its names', () => {\n    expect(isEnumValue(Direction, 0)).toBe(true);\n    expect(isEnumValue(Direction, Direction.Down)).toBe(true);\n    expect(isEnumValue(Direction, 'Up')).toBe(false);\n    expect(isEnumValue(Direction, '0')).toBe(false);\n    expect(isEnumValue(Direction, 2)).toBe(false);\n  });\n\n  it('accepts the values of a string enum, not its keys', () => {\n    expect(isEnumValue(Color, 'red')).toBe(true);\n    expect(isEnumValue(Color, 'Red')).toBe(false);\n    expect(isEnumValue(Color, undefined)).toBe(false);\n  });\n\n  it('handles numeric enums with explicit values', () => {\n    expect(isEnumValue(Sparse, 10)).toBe(true);\n    expect(isEnumValue(Sparse, 'High')).toBe(false);\n    expect(isEnumValue(Sparse, 5)).toBe(false);\n  });\n\n  it('handles const objects used as enums', () => {\n    const status = { idle: 'idle', running: 'running' } as const;\n    expect(isEnumValue(status, 'running')).toBe(true);\n    expect(isEnumValue(status, 'stopped')).toBe(false);\n  });\n});\n"],
  ["src/enum/is-enum-value.ts", "import type { EnumObject } from './enum-object';\nimport { getEnumValues } from './get-enum-values';\n\nconst valuesByEnum = new WeakMap<object, ReadonlySet<unknown>>();\n\n/**\n * Checks whether a value is one of the values of an enum, in O(1): the values of each enum are read once.\n *\n * @template E - The type of the enum object.\n * @param enumObject - The enum to search, such as `Direction`.\n * @param value - The value to look for.\n * @returns `true` when the value is one of the enum's values.\n * @cached The values of each enum, in a `WeakMap`: nothing is kept once the enum is unused.\n * @example\n * enum Direction { Up, Down }\n * isEnumValue(Direction, 0); // true\n * isEnumValue(Direction, 'Up'); // false (a name, not a value)\n */\nexport function isEnumValue<E extends EnumObject>(enumObject: E, value: unknown): value is E[keyof E] {\n  let values = valuesByEnum.get(enumObject);\n  if (!values) {\n    values = new Set(getEnumValues(enumObject));\n    valuesByEnum.set(enumObject, values);\n  }\n  return values.has(value);\n}\n"],
  ["src/enum/parse-enum-value.spec.ts", "import { parseEnumValue } from './parse-enum-value';\n\nenum Level {\n  Low = 0,\n  High = 1,\n}\n\nenum Mode {\n  Day = 'day',\n  Night = 'night',\n}\n\ndescribe(parseEnumValue, () => {\n  it.for([\n    ['1', Level.High],\n    [1, Level.High],\n    ['0', Level.Low],\n  ] as const)('reads %j from a numeric enum as %s', ([input, expected]) => {\n    expect(parseEnumValue(Level, input)).toBe(expected);\n  });\n\n  it('reads string enums', () => {\n    expect(parseEnumValue(Mode, 'night')).toBe(Mode.Night);\n  });\n\n  it('accepts member names on request', () => {\n    expect(parseEnumValue(Level, 'High', true)).toBe(Level.High);\n    expect(parseEnumValue(Mode, 'Night', true)).toBe(Mode.Night);\n  });\n\n  it.for(['7', 'High'])('throws a TypeError for %j', (input) => {\n    expect(() => parseEnumValue(Level, input)).toThrow(TypeError);\n  });\n});\n"],
  ["src/enum/parse-enum-value.ts", "import type { EnumObject } from './enum-object';\nimport { getEnumEntries } from './get-enum-entries';\n\n/**\n * Reads an enum member from a text, such as a query parameter: `'1'` gives the member of value `1`. With\n * `isKeyAccepted`, a member name (`'High'`) works too.\n *\n * @template E - The type of the enum object.\n * @param enumObject - The enum, such as `Level`.\n * @param input - The value or the name to read.\n * @param isKeyAccepted - Whether a member name also identifies the member. Defaults to `false`.\n * @returns The member.\n * @throws {TypeError} When no member matches.\n * @example\n * enum Level { Low = 0, High = 1 }\n * parseEnumValue(Level, '1'); // Level.High\n * parseEnumValue(Level, 'High', true); // Level.High\n */\nexport function parseEnumValue<E extends EnumObject>(\n  enumObject: E,\n  input: number | string,\n  isKeyAccepted = false,\n): E[keyof E] {\n  const text = String(input);\n  const match = getEnumEntries(enumObject).find(\n    ([key, value]) => String(value) === text || (isKeyAccepted && key === text),\n  );\n  if (!match) {\n    throw new TypeError(`No enum member matches '${text}'`);\n  }\n  return match[1];\n}\n"],
  ["src/enum/to-enum-value.spec.ts", "import { toEnumValue } from './to-enum-value';\n\nenum Mode {\n  Day = 'day',\n  Night = 'night',\n}\n\nenum Level {\n  Low = 0,\n  High = 1,\n}\n\ndescribe(toEnumValue, () => {\n  it('keeps a member of the enum', () => {\n    expect(toEnumValue(Mode, 'night', Mode.Day)).toBe(Mode.Night);\n    expect(toEnumValue(Level, 1, Level.Low)).toBe(Level.High);\n  });\n\n  it.for(['dusk', undefined, null, 'Night', 0])('falls back for %j', (value) => {\n    expect(toEnumValue(Mode, value, Mode.Day)).toBe(Mode.Day);\n  });\n\n  it('does not accept the names of a numeric enum', () => {\n    expect(toEnumValue(Level, 'High', Level.Low)).toBe(Level.Low);\n  });\n});\n"],
  ["src/enum/to-enum-value.ts", "import type { EnumObject } from './enum-object';\nimport { isEnumValue } from './is-enum-value';\n\n/**\n * Returns a value typed as an enum member: the value itself when it belongs to the enum, the fallback\n * otherwise. For a stored setting that may be outdated.\n *\n * @template E - The type of the enum object.\n * @param enumObject - The enum, such as `Mode`.\n * @param value - The value to check.\n * @param fallback - The member returned when `value` does not belong to the enum.\n * @returns `value` narrowed to the enum, or `fallback`.\n * @example\n * enum Mode { Day = 'day', Night = 'night' }\n * toEnumValue(Mode, 'night', Mode.Day); // Mode.Night\n * toEnumValue(Mode, 'dusk', Mode.Day); // Mode.Day\n */\nexport function toEnumValue<E extends EnumObject>(enumObject: E, value: unknown, fallback: E[keyof E]): E[keyof E] {\n  return isEnumValue(enumObject, value) ? value : fallback;\n}\n"],
  ["src/format/format-decimal.spec.ts", "import { formatDecimal } from './format-decimal';\n\ndescribe(formatDecimal, () => {\n  it.for([\n    [2, 2, '2'],\n    [1.5, 3, '1.5'],\n    [0.0000001, 8, '0.0000001'],\n    [1.005, 2, '1.01'],\n    [-0.001, 2, '0'],\n    [-0, 2, '0'],\n    [-1.25, 1, '-1.3'],\n    [1_234_567.891, 2, '1234567.89'],\n    [1e21, 0, '1000000000000000000000'],\n    [Math.PI, 0, '3'],\n  ] as const)('formats %s with %s digits as %s', ([value, digits, expected]) => {\n    expect(formatDecimal(value, digits)).toBe(expected);\n  });\n\n  it.for([\n    [NaN, 'NaN'],\n    [Infinity, 'Infinity'],\n    [-Infinity, '-Infinity'],\n  ] as const)('formats %s as %s', ([value, expected]) => {\n    expect(formatDecimal(value, 2)).toBe(expected);\n  });\n\n  it('accepts the maxFractionDigits bounds', () => {\n    expect(formatDecimal(1.5, 0)).toBe('2');\n    expect(formatDecimal(1.5, 100)).toBe('1.5');\n  });\n\n  it('groups the thousands with a comma when asked', () => {\n    expect(formatDecimal(1_234_567.891, 2, true)).toBe('1,234,567.89');\n    expect(formatDecimal(1234.5, 2, false)).toBe('1234.5');\n  });\n\n  it('takes 3 decimals and no grouping', () => {\n    expect(formatDecimal(1234.5678)).toBe('1234.568');\n  });\n});\n"],
  ["src/format/format-decimal.ts", "const formatters = [new Map<number, Intl.NumberFormat>(), new Map<number, Intl.NumberFormat>()] as const;\n\n/**\n * Formats a number with `.` before the decimals, no trailing zeros, no scientific notation and no `-0`.\n * Rounds like ICU: `formatDecimal(1.005, 2)` is `'1.01'`, where `toFixed` gives `'1.00'`.\n *\n * @param value - The number to format; `NaN` and infinities give `String(value)`.\n * @param maxFractionDigits - The largest number of decimals. Defaults to `3`.\n * @param useGrouping - Whether to separate the thousands with `,`. Defaults to `false`.\n * @returns The formatted number.\n * @example\n * formatDecimal(Math.PI); // '3.142'\n * formatDecimal(2, 2); // '2'\n * formatDecimal(1234.5, 2, true); // '1,234.5'\n * formatDecimal(-0.001, 2); // '0'\n */\nexport function formatDecimal(value: number, maxFractionDigits = 3, useGrouping = false): string {\n  if (!Number.isFinite(value)) {\n    return String(value);\n  }\n  const cache = formatters[useGrouping ? 1 : 0];\n  let formatter = cache.get(maxFractionDigits);\n  if (!formatter) {\n    formatter = new Intl.NumberFormat('en-US', {\n      maximumFractionDigits: maxFractionDigits,\n      useGrouping,\n      signDisplay: 'negative',\n    });\n    cache.set(maxFractionDigits, formatter);\n  }\n  return formatter.format(value);\n}\n"],
  ["src/format/format-number.spec.ts", "import { formatNumber } from './format-number';\n\ndescribe(formatNumber, () => {\n  it.for([\n    [Math.PI, '1.0-2', '3.14'],\n    [5, '3.0-2', '005'],\n    [1234.5, '1.2-2', '1234.50'],\n    [1_234_567.891, '1.0-2', '1234567.89'],\n    [0.5, '1.0-0', '1'],\n    [-0.001, '1.0-2', '0'],\n    [1.2, '1.5-5', '1.20000'],\n  ] as const)('formats %s with %s as %s', ([value, digitsInfo, expected]) => {\n    expect(formatNumber(value, digitsInfo, 'en-US')).toBe(expected);\n  });\n\n  it('uses the separators and grouping of the locale when grouping', () => {\n    expect(formatNumber(1_234_567.891, '1.0-2', 'en-US', true)).toBe('1,234,567.89');\n    expect(formatNumber(1234.5, '1.2-2', 'fr-FR', true)).toBe('1\\u{202F}234,50');\n    expect(formatNumber(1234.5, '1.2-2', 'de-DE', true)).toBe('1.234,50');\n    expect(formatNumber(1234.5, '1.2-2', 'de-DE', false)).toBe('1234,50');\n  });\n\n  it('takes 1.0-3, en-US and no grouping', () => {\n    expect(formatNumber(1234.5678)).toBe('1234.568');\n  });\n\n  it('formats NaN and infinities like String()', () => {\n    expect(formatNumber(NaN, '1.0-2', 'en-US')).toBe('NaN');\n    expect(formatNumber(-Infinity, '1.0-2', 'en-US')).toBe('-Infinity');\n  });\n\n  it('returns the same output from the cached formatter', () => {\n    expect(formatNumber(1.5, '1.1-1', 'en-US')).toBe('1.5');\n    expect(formatNumber(2.25, '1.1-1', 'en-US')).toBe('2.3');\n  });\n\n  it.for(['', '1', '1-2', '.1-1', '2.', '1.5', 'a.0-2'])('throws a TypeError for digitsInfo %j', (digitsInfo) => {\n    expect(() => formatNumber(1, digitsInfo)).toThrow(TypeError);\n  });\n});\n"],
  ["src/format/format-number.ts", "const DIGITS_INFO_PATTERN = /^(?<minInteger>\\d+)\\.(?<minFraction>\\d+)-(?<maxFraction>\\d+)$/v;\n\nconst formatters = [\n  new Map<string, Map<string, Intl.NumberFormat>>(),\n  new Map<string, Map<string, Intl.NumberFormat>>(),\n] as const;\n\nfunction createFormatter(digitsInfo: string, locale: string, useGrouping: boolean): Intl.NumberFormat {\n  const groups = DIGITS_INFO_PATTERN.exec(digitsInfo)?.groups;\n  if (!groups) {\n    throw new TypeError(`digitsInfo must look like '1.0-3', got '${digitsInfo}'`);\n  }\n  return new Intl.NumberFormat(locale, {\n    minimumIntegerDigits: Number(groups['minInteger']),\n    minimumFractionDigits: Number(groups['minFraction']),\n    maximumFractionDigits: Number(groups['maxFraction']),\n    useGrouping,\n    signDisplay: 'negative',\n  });\n}\n\n/**\n * Formats a number like Angular's `DecimalPipe`: digits driven by `digitsInfo`, separators of a locale.\n * `NaN`, infinities and `-0` are handled like `formatDecimal`.\n *\n * @param value - The number to format.\n * @param digitsInfo - `'{minIntegerDigits}.{minFractionDigits}-{maxFractionDigits}'`, such as `'1.0-2'`.\n * Defaults to `'1.0-3'`.\n * @param locale - The BCP 47 locale, such as `'fr-FR'`. Defaults to `'en-US'`.\n * @param useGrouping - Whether to separate the thousands. Defaults to `false`.\n * @returns The formatted number.\n * @throws {TypeError} When `digitsInfo` does not look like `'1.0-3'`.\n * @example\n * formatNumber(1234.5678); // '1234.568'\n * formatNumber(5, '3.0-2'); // '005'\n * formatNumber(1234.5, '1.2-2', 'en-US', true); // '1,234.50'\n * formatNumber(1234.5, '1.2-2', 'de-DE', true); // '1.234,50'\n */\nexport function formatNumber(value: number, digitsInfo = '1.0-3', locale = 'en-US', useGrouping = false): string {\n  if (!Number.isFinite(value)) {\n    return String(value);\n  }\n  const cache = formatters[useGrouping ? 1 : 0];\n  let localeFormatters = cache.get(locale);\n  if (!localeFormatters) {\n    localeFormatters = new Map();\n    cache.set(locale, localeFormatters);\n  }\n  let formatter = localeFormatters.get(digitsInfo);\n  if (!formatter) {\n    formatter = createFormatter(digitsInfo, locale, useGrouping);\n    localeFormatters.set(digitsInfo, formatter);\n  }\n  return formatter.format(value);\n}\n"],
  ["src/format/index.ts", "// Formatting: numbers as display text.\n\nexport { formatDecimal } from './format-decimal';\nexport { formatNumber } from './format-number';\n"],
  ["src/guard/assert-never.spec.ts", "import { assertNever } from './assert-never';\n\ndescribe(assertNever, () => {\n  it('throws with a custom message', () => {\n    expect(() => assertNever('oops' as never, 'Unknown mode')).toThrow('Unknown mode');\n  });\n\n  it('throws \"Unexpected value\" for a null or undefined message', () => {\n    expect(() => assertNever(1 as never)).toThrow('Unexpected value');\n  });\n});\n"],
  ["src/guard/assert-never.ts", "/**\n * Marks a code path as unreachable: in the `default` of a `switch` over a union, TypeScript fails when a\n * member is not handled, and an unexpected value throws at run time.\n *\n * @param value - The value narrowed to `never`.\n * @param message - The message of the error. Defaults to `'Unexpected value'`.\n * @throws {Error} Always.\n * @example\n * switch (mode) {\n *   case 'day': return light;\n *   case 'night': return dark;\n *   default: return assertNever(mode);\n * }\n */\nexport function assertNever(value: never, message = 'Unexpected value'): never {\n  throw new Error(message);\n}\n"],
  ["src/guard/assert.spec.ts", "import { assert } from './assert';\n\nconst checkAssert: (condition: unknown, message: string) => void = assert;\n\ndescribe(assert, () => {\n  it.for([true, 1, 'text', {}, []])('passes for the truthy value %j', (condition) => {\n    expect(() => {\n      checkAssert(condition, 'Assertion failed');\n    }).not.toThrow();\n  });\n\n  it.for([false, 0, '', null, undefined, NaN])('throws for the falsy value %s', (condition) => {\n    expect(() => {\n      checkAssert(condition, 'Boom');\n    }).toThrow('Boom');\n  });\n\n  it('throws \"Assertion failed\" by default', () => {\n    expect(() => {\n      assert(false);\n    }).toThrow('Assertion failed');\n  });\n});\n"],
  ["src/guard/assert.ts", "/**\n * Throws when a condition is falsy, and narrows its type otherwise.\n *\n * @param condition - The value that must be truthy.\n * @param message - The message of the error. Defaults to `'Assertion failed'`.\n * @throws {Error} When `condition` is falsy.\n * @example\n * assert(user !== undefined, 'User not loaded');\n * user.name; // `user` is no longer `undefined`\n */\nexport function assert(condition: unknown, message = 'Assertion failed'): asserts condition {\n  const isTruthy = Boolean(condition);\n  if (!isTruthy) {\n    throw new Error(message);\n  }\n}\n"],
  ["src/guard/index.ts", "// Guards: type guards and assertions that narrow values (the enum guards are in `enum`).\n\nexport { assertNever } from './assert-never';\nexport { assert } from './assert';\nexport { isArrayOf } from './is-array-of';\nexport { isArray } from './is-array';\nexport { isBoolean } from './is-boolean';\nexport { isDefined } from './is-defined';\nexport { isFiniteNumber } from './is-finite-number';\nexport { isFunction } from './is-function';\nexport { isNotUndefined } from './is-not-undefined';\nexport { isNull } from './is-null';\nexport { isNullish } from './is-nullish';\nexport { isNumber } from './is-number';\nexport { isObject } from './is-object';\nexport { isRecord } from './is-record';\nexport { isString } from './is-string';\nexport { isUndefined } from './is-undefined';\nexport { isNonEmptyArray } from './is-non-empty-array';\n"],
  ["src/guard/is-array-of.spec.ts", "import { isArrayOf } from './is-array-of';\nimport { isNumber } from './is-number';\nimport { isString } from './is-string';\n\ndescribe(isArrayOf, () => {\n  it('checks every item', () => {\n    expect(isArrayOf([1, 2], isNumber)).toBe(true);\n    expect(isArrayOf([], isNumber)).toBe(true);\n    expect(isArrayOf([1, '2'], isNumber)).toBe(false);\n    expect(isArrayOf('12', isString)).toBe(false);\n  });\n});\n"],
  ["src/guard/is-array-of.ts", "/**\n * Checks whether a value is an array whose every item passes a type guard.\n *\n * @template T - Type of the items.\n * @param value - The value to check.\n * @param guard - The type guard applied to each item.\n * @returns `true` for an array of `T` (an empty array included).\n * @example\n * isArrayOf([1, 2], isNumber); // true\n * isArrayOf([1, '2'], isNumber); // false\n */\nexport function isArrayOf<T>(value: unknown, guard: (item: unknown) => item is T): value is T[] {\n  return Array.isArray(value) && value.every((item: unknown) => guard(item));\n}\n"],
  ["src/guard/is-array.spec.ts", "import { isArray } from './is-array';\n\ndescribe(isArray, () => {\n  it('accepts arrays only', () => {\n    expect(isArray([])).toBe(true);\n    expect(isArray({ length: 0 })).toBe(false);\n    expect(isArray('abc')).toBe(false);\n    expect(isArray(null)).toBe(false);\n  });\n});\n"],
  ["src/guard/is-array.ts", "/**\n * Checks whether a value is an array, whatever its items.\n *\n * @param value - The value to check.\n * @returns `true` for an array; `false` for array-likes such as strings or typed arrays.\n * @example\n * isArray([1, 2]); // true\n * isArray({ length: 0 }); // false\n */\nexport function isArray(value: unknown): value is unknown[] {\n  return Array.isArray(value);\n}\n"],
  ["src/guard/is-boolean.spec.ts", "import { isBoolean } from './is-boolean';\n\ndescribe(isBoolean, () => {\n  it('accepts booleans only', () => {\n    expect(isBoolean(false)).toBe(true);\n    expect(isBoolean(0)).toBe(false);\n    expect(isBoolean('true')).toBe(false);\n  });\n});\n"],
  ["src/guard/is-boolean.ts", "/**\n * Checks whether a value is a boolean.\n *\n * @param value - The value to check.\n * @returns `true` for `true` and `false` only (not for truthy or falsy values).\n * @example\n * isBoolean(false); // true\n * isBoolean(0); // false\n */\nexport function isBoolean(value: unknown): value is boolean {\n  return typeof value === 'boolean';\n}\n"],
  ["src/guard/is-defined.spec.ts", "import { isDefined } from './is-defined';\n\ndescribe(isDefined, () => {\n  it('excludes null and undefined', () => {\n    expect([0, '', false, null, undefined, NaN].filter(isDefined)).toStrictEqual([0, '', false, NaN]);\n  });\n});\n"],
  ["src/guard/is-defined.ts", "/**\n * Checks whether a value is neither `null` nor `undefined`: the opposite of `isNullish`. `isNotUndefined` lets\n * `null` through.\n *\n * @template T - The type of the value.\n * @param value - The value to check.\n * @returns `true` when the value is present, `0`, `''` and `false` included.\n * @example\n * [1, null, undefined].filter(isDefined); // [1], typed number[]\n */\nexport function isDefined<T>(value: T): value is NonNullable<T> {\n  // eslint-disable-next-line sonarjs/different-types-comparison -- `T` may include `undefined`.\n  return value !== null && value !== undefined;\n}\n"],
  ["src/guard/is-finite-number.spec.ts", "import { isFiniteNumber } from './is-finite-number';\n\ndescribe(isFiniteNumber, () => {\n  it.for([\n    [0, true],\n    [-1.5, true],\n    [Infinity, false],\n    [NaN, false],\n    ['1', false],\n  ] as const)('checks %s as %s', ([value, expected]) => {\n    expect(isFiniteNumber(value)).toBe(expected);\n  });\n});\n"],
  ["src/guard/is-finite-number.ts", "/**\n * Checks whether a value is a finite number: neither `NaN` nor an infinity.\n *\n * @param value - The value to check.\n * @returns `true` for a finite number (never for a numeric string).\n * @example\n * isFiniteNumber(1.5); // true\n * isFiniteNumber(Infinity); // false\n */\nexport function isFiniteNumber(value: unknown): value is number {\n  return Number.isFinite(value);\n}\n"],
  ["src/guard/is-function.spec.ts", "import { isFunction } from './is-function';\n\nclass Point {\n  public readonly x = 0;\n}\n\n// Plain function type: calls are not seen as conditions, so any value can be passed.\n\ndescribe(isFunction, () => {\n  it('accepts functions and classes', () => {\n    expect(isFunction(() => 0)).toBe(true);\n    expect(isFunction(Point)).toBe(true);\n    expect(isFunction({})).toBe(false);\n  });\n});\n"],
  ["src/guard/is-function.ts", "/**\n * Checks whether a value is callable: a function or a class.\n *\n * @param value - The value to check.\n * @returns `true` for any function.\n * @example\n * isFunction(() => 0); // true\n * isFunction({}); // false\n */\n// eslint-disable-next-line @typescript-eslint/no-unsafe-function-type -- The type every function is assignable to.\nexport function isFunction(value: unknown): value is Function {\n  return typeof value === 'function';\n}\n"],
  ["src/guard/is-non-empty-array.spec.ts", "import type { NonEmptyArray } from '../types';\nimport { isNonEmptyArray } from './is-non-empty-array';\n\ndescribe(isNonEmptyArray, () => {\n  it('checks the length', () => {\n    expect(isNonEmptyArray([0])).toBe(true);\n    expect(isNonEmptyArray([])).toBe(false);\n  });\n\n  it('types the first item as defined', () => {\n    expectTypeOf(isNonEmptyArray<number>).guards.toEqualTypeOf<NonEmptyArray<number>>();\n  });\n});\n"],
  ["src/guard/is-non-empty-array.ts", "import type { NonEmptyArray } from '../types';\n\n/**\n * Checks whether an array has an item, and narrows it so that its first item is defined.\n *\n * @template T - The type of the items.\n * @param items - The array to check.\n * @returns `true` when the array has an item.\n * @example\n * if (isNonEmptyArray(samples)) {\n *   const [first] = samples; // a sample, not `undefined`\n * }\n */\nexport function isNonEmptyArray<T>(items: readonly T[]): items is NonEmptyArray<T> {\n  return items.length > 0;\n}\n"],
  ["src/guard/is-not-undefined.spec.ts", "import { isNotUndefined } from './is-not-undefined';\n\ndescribe(isNotUndefined, () => {\n  it('excludes undefined only', () => {\n    expect([0, null, undefined].filter(isNotUndefined)).toStrictEqual([0, null]);\n  });\n});\n"],
  ["src/guard/is-not-undefined.ts", "/**\n * Checks whether a value is not `undefined`; `null` passes, unlike with `isDefined`.\n *\n * @template T - The type of the value.\n * @param value - The value to check.\n * @returns `true` for anything but `undefined`.\n * @example\n * [1, null, undefined].filter(isNotUndefined); // [1, null], typed (number | null)[]\n */\nexport function isNotUndefined<T>(value: T): value is Exclude<T, undefined> {\n  return value !== undefined;\n}\n"],
  ["src/guard/is-null.spec.ts", "import { isNull } from './is-null';\n\ndescribe(isNull, () => {\n  it.for([\n    [null, true],\n    [undefined, false],\n    [0, false],\n  ] as const)('checks %s as %s', ([value, expected]) => {\n    expect(isNull(value)).toBe(expected);\n  });\n});\n"],
  ["src/guard/is-null.ts", "/**\n * Checks whether a value is `null`; `undefined` does not pass.\n *\n * @param value - The value to check.\n * @returns `true` for `null` only.\n * @example\n * isNull(null); // true\n * isNull(undefined); // false\n */\nexport function isNull(value: unknown): value is null {\n  return value === null;\n}\n"],
  ["src/guard/is-nullish.spec.ts", "import { isNullish } from './is-nullish';\n\ndescribe(isNullish, () => {\n  it.for([\n    [null, true],\n    [undefined, true],\n    [0, false],\n    ['', false],\n    [false, false],\n  ] as const)('checks %s as %s', ([value, expected]) => {\n    expect(isNullish(value)).toBe(expected);\n  });\n});\n"],
  ["src/guard/is-nullish.ts", "/**\n * Checks whether a value is `null` or `undefined`: the opposite of `isDefined`.\n *\n * @param value - The value to check.\n * @returns `true` for `null` and `undefined`; `false` for `0`, `''` and `false`.\n * @example\n * isNullish(undefined); // true\n * isNullish(0); // false\n */\nexport function isNullish(value: unknown): value is null | undefined {\n  return value === null || value === undefined;\n}\n"],
  ["src/guard/is-number.spec.ts", "import { isNumber } from './is-number';\n\ndescribe(isNumber, () => {\n  it.for([\n    [0, true],\n    [-1.5, true],\n    [Infinity, true],\n    [NaN, false],\n    ['1', false],\n    [null, false],\n  ] as const)('checks %s as %s', ([value, expected]) => {\n    expect(isNumber(value)).toBe(expected);\n  });\n});\n"],
  ["src/guard/is-number.ts", "/**\n * Checks whether a value is a number other than `NaN`. Infinities pass: use `isFiniteNumber` to exclude them.\n *\n * @param value - The value to check.\n * @returns `true` for a number that is not `NaN`.\n * @example\n * isNumber(Infinity); // true\n * isNumber(NaN); // false\n */\nexport function isNumber(value: unknown): value is number {\n  return typeof value === 'number' && !Number.isNaN(value);\n}\n"],
  ["src/guard/is-object.spec.ts", "import { isObject } from './is-object';\n\nclass Point {\n  public readonly x = 0;\n}\n\n// Plain function type: calls are not seen as conditions, so any value can be passed.\n\ndescribe(isObject, () => {\n  it.for([\n    [{}, true],\n    [[], true],\n    [new Point(), true],\n    [new Date(0), true],\n    [null, false],\n    [undefined, false],\n    ['object', false],\n    [(): number => 0, false],\n  ] as const)('checks %j as %s', ([value, expected]) => {\n    expect(isObject(value)).toBe(expected);\n  });\n});\n"],
  ["src/guard/is-object.ts", "/**\n * Checks whether a value is a non-null object: plain object, array, class instance, date… `isRecord` accepts\n * plain objects only.\n *\n * @param value - The value to check.\n * @returns `true` for any non-null object; `false` for a function.\n * @example\n * isObject([]); // true\n * isObject(null); // false\n */\nexport function isObject(value: unknown): value is object {\n  return typeof value === 'object' && value !== null;\n}\n"],
  ["src/guard/is-record.spec.ts", "import { isRecord } from './is-record';\n\nclass Point {\n  public readonly x = 0;\n}\n\n// Plain function type: calls are not seen as conditions, so any value can be passed.\n\ndescribe(isRecord, () => {\n  it.for([\n    [{}, true],\n    [{ a: 1 }, true],\n    [Object.create(null), true],\n    [[], false],\n    [new Point(), false],\n    [new Map(), false],\n    [null, false],\n    [1, false],\n  ] as const)('checks %j as %s', ([value, expected]) => {\n    expect(isRecord(value)).toBe(expected);\n  });\n});\n"],
  ["src/guard/is-record.ts", "/**\n * Checks whether a value is a plain object: an object literal or `Object.create(null)`. Arrays, class\n * instances, dates and maps are excluded.\n *\n * @param value - The value to check.\n * @returns `true` for a plain object.\n * @example\n * isRecord({ a: 1 }); // true\n * isRecord([]); // false\n * isRecord(new Date()); // false\n */\nexport function isRecord(value: unknown): value is Record<string, unknown> {\n  if (typeof value !== 'object' || value === null) {\n    return false;\n  }\n  const prototype: unknown = Object.getPrototypeOf(value);\n  return prototype === Object.prototype || prototype === null;\n}\n"],
  ["src/guard/is-string.spec.ts", "import { isString } from './is-string';\n\ndescribe(isString, () => {\n  it('accepts strings only', () => {\n    expect(isString('')).toBe(true);\n    expect(isString(1)).toBe(false);\n  });\n});\n"],
  ["src/guard/is-string.ts", "/**\n * Checks whether a value is a string primitive.\n *\n * @param value - The value to check.\n * @returns `true` for a string, the empty string included.\n * @example\n * isString(''); // true\n * isString(1); // false\n */\nexport function isString(value: unknown): value is string {\n  return typeof value === 'string';\n}\n"],
  ["src/guard/is-undefined.spec.ts", "import { isUndefined } from './is-undefined';\n\ndescribe(isUndefined, () => {\n  it('accepts undefined only', () => {\n    expect(isUndefined(undefined)).toBe(true);\n    expect(isUndefined(null)).toBe(false);\n    expect(isUndefined(0)).toBe(false);\n  });\n});\n"],
  ["src/guard/is-undefined.ts", "/**\n * Checks whether a value is `undefined`; `null` does not pass.\n *\n * @param value - The value to check.\n * @returns `true` for `undefined` only.\n * @example\n * isUndefined(undefined); // true\n * isUndefined(null); // false\n */\nexport function isUndefined(value: unknown): value is undefined {\n  return value === undefined;\n}\n"],
  ["src/index.ts", "export * from './async';\nexport * from './color';\nexport * from './duration';\nexport * from './enum';\nexport * from './format';\nexport * from './guard';\nexport * from './math';\nexport * from './object';\nexport * from './path';\nexport * from './string';\nexport * from './svg-shape';\nexport * from './svg-transform';\nexport type * from './types';\n"],
  ["src/math/apply-hysteresis.spec.ts", "import { applyHysteresis } from './apply-hysteresis';\n\ndescribe(applyHysteresis, () => {\n  it.for([\n    [95, false, true],\n    [90, false, true],\n    [87, false, false],\n    [87, true, true],\n    [85, true, false],\n    [80, true, false],\n  ] as const)('turns %s with state %s into %s', ([value, isOn, expected]) => {\n    expect(applyHysteresis(value, isOn, 85, 90)).toBe(expected);\n  });\n\n  it('does not flicker around the high threshold', () => {\n    let isOn = false;\n    const states = [89, 91, 89, 88, 91, 86, 84].map((value) => {\n      isOn = applyHysteresis(value, isOn, 85, 90);\n      return isOn;\n    });\n    expect(states).toStrictEqual([false, true, true, true, true, true, false]);\n  });\n});\n"],
  ["src/math/apply-hysteresis.ts", "/**\n * Updates an on/off state with hysteresis: on at or above `highThreshold`, off at or below `lowThreshold`,\n * unchanged in between. A noisy value near a threshold no longer makes the state flicker.\n *\n * @param value - The latest value.\n * @param isOn - The current state.\n * @param lowThreshold - The value at or below which the state switches off.\n * @param highThreshold - The value at or above which the state switches on.\n * @returns The new state.\n * @example\n * isAlarmOn = applyHysteresis(temperature, isAlarmOn, 85, 90); // on at 90 °C, off under 85 °C\n */\nexport function applyHysteresis(value: number, isOn: boolean, lowThreshold: number, highThreshold: number): boolean {\n  return value >= highThreshold || (value > lowThreshold && isOn);\n}\n"],
  ["src/math/ceil-to-step.spec.ts", "import { ceilToStep } from './ceil-to-step';\n\ndescribe(ceilToStep, () => {\n  it.for([\n    [0.3, 0.1, 0.3],\n    [0.31, 0.1, 0.4],\n    [7, 5, 10],\n    [-7, 5, -5],\n    [0.7, 0.1, 0.7],\n  ] as const)('ceils %s to step %s as %s', ([value, step, expected]) => {\n    expect(ceilToStep(value, step)).toBe(expected);\n  });\n\n  it('does not return -0', () => {\n    expect(Object.is(ceilToStep(-0.4, 1), 0)).toBe(true);\n  });\n\n  it('takes the defaults', () => {\n    expect(ceilToStep(2.3)).toStrictEqual(ceilToStep(2.3, 1));\n  });\n});\n"],
  ["src/math/ceil-to-step.ts", "import { snapToStep } from './internal';\n\n/**\n * Rounds a number up to a multiple of a step, without float noise.\n *\n * @param value - The number to round up.\n * @param step - The step, a positive number. Defaults to `1`.\n * @returns The smallest multiple of `step` greater than or equal to `value`.\n * @example\n * ceilToStep(0.31, 0.1); // 0.4\n * ceilToStep(-7, 5); // -5\n */\nexport function ceilToStep(value: number, step = 1): number {\n  return snapToStep(value, step, Math.ceil);\n}\n"],
  ["src/math/clamp.spec.ts", "import { clamp } from './clamp';\n\ndescribe(clamp, () => {\n  it.for([\n    [5, 0, 10, 5],\n    [-5, 0, 10, 0],\n    [15, 0, 10, 10],\n    [-5, 10, 0, 0],\n  ] as const)('clamps %s into [%s, %s] as %s', ([value, min, max, expected]) => {\n    expect(clamp(value, min, max)).toBe(expected);\n  });\n\n  it('takes the defaults', () => {\n    expect(clamp(1.5)).toStrictEqual(clamp(1.5, 0, 1));\n  });\n});\n"],
  ["src/math/clamp.ts", "/**\n * Restricts a number to an interval.\n *\n * @param value - The number to restrict.\n * @param min - The lower bound. Defaults to `0`.\n * @param max - The upper bound. Defaults to `1`.\n * @returns `value` within the bounds, or the nearest bound.\n * @example\n * clamp(15, 0, 10); // 10\n * clamp(1.5); // 1\n */\nexport function clamp(value: number, min = 0, max = 1): number {\n  return Math.min(Math.max(value, min), max);\n}\n"],
  ["src/math/floor-to-step.spec.ts", "import { floorToStep } from './floor-to-step';\n\ndescribe(floorToStep, () => {\n  it.for([\n    [0.3, 0.1, 0.3],\n    [0.39, 0.1, 0.3],\n    [7, 5, 5],\n    [-7, 5, -10],\n    [0.7, 0.1, 0.7],\n  ] as const)('floors %s to step %s as %s', ([value, step, expected]) => {\n    expect(floorToStep(value, step)).toBe(expected);\n  });\n\n  it('takes the defaults', () => {\n    expect(floorToStep(2.7)).toStrictEqual(floorToStep(2.7, 1));\n  });\n});\n"],
  ["src/math/floor-to-step.ts", "import { snapToStep } from './internal';\n\n/**\n * Rounds a number down to a multiple of a step, without float noise.\n *\n * @param value - The number to round down.\n * @param step - The step, a positive number. Defaults to `1`.\n * @returns The largest multiple of `step` lower than or equal to `value`.\n * @example\n * floorToStep(0.39, 0.1); // 0.3\n * floorToStep(-7, 5); // -10\n */\nexport function floorToStep(value: number, step = 1): number {\n  return snapToStep(value, step, Math.floor);\n}\n"],
  ["src/math/has-significant-change.spec.ts", "import { hasSignificantChange } from './has-significant-change';\n\ndescribe(hasSignificantChange, () => {\n  it.for([\n    [10, 10.05, 0.1, false],\n    [10, 10.5, 0.1, true],\n    [1000, 1000.1, 0.1, true],\n    [10, 10.099, 0.1, false],\n    [10, 9.8, 0.1, true],\n    [10, 10, 0, true],\n    [NaN, 10, 0.1, true],\n    [10, NaN, 0.1, true],\n    [NaN, NaN, 0.1, false],\n  ] as const)('compares %s → %s with threshold %s: %s', ([previous, next, threshold, expected]) => {\n    expect(hasSignificantChange(previous, next, threshold)).toBe(expected);\n  });\n\n  it('takes the defaults', () => {\n    expect(hasSignificantChange(1, 1.000_001)).toStrictEqual(hasSignificantChange(1, 1.000_001, 0));\n  });\n});\n"],
  ["src/math/has-significant-change.ts", "/**\n * Checks whether a value moved enough since the displayed one to be worth a render (a deadband). A switch\n * between a number and `NaN` always counts.\n *\n * @param previous - The displayed value.\n * @param next - The new value.\n * @param threshold - The smallest change worth a render. Defaults to `0`.\n * @returns `true` when `|next - previous| >= threshold`.\n * @example\n * hasSignificantChange(10, 10.5, 0.1); // true\n * hasSignificantChange(10, 10.05, 0.1); // false\n */\nexport function hasSignificantChange(previous: number, next: number, threshold = 0): boolean {\n  return Math.abs(next - previous) >= threshold || Number.isNaN(previous) !== Number.isNaN(next);\n}\n"],
  ["src/math/index.ts", "// Math: clamping, interpolation, wrapping, rounding without float noise, smoothing.\n\nexport { ceilToStep } from './ceil-to-step';\nexport { clamp } from './clamp';\nexport { floorToStep } from './floor-to-step';\nexport { inverseLerp } from './inverse-lerp';\nexport { isBetween } from './is-between';\nexport { isNearlyEqual } from './is-nearly-equal';\nexport { lerp } from './lerp';\nexport { ratio } from './ratio';\nexport { remap } from './remap';\nexport { roundToFractionDigits } from './round-to-fraction-digits';\nexport { roundToStep } from './round-to-step';\nexport { smoothTowards } from './smooth-towards';\nexport { wrap } from './wrap';\nexport { moveTowards } from './move-towards';\nexport { applyHysteresis } from './apply-hysteresis';\nexport { interpolateTable } from './interpolate-table';\nexport { hasSignificantChange } from './has-significant-change';\nexport { roundToSignificantDigits } from './round-to-significant-digits';\n"],
  ["src/math/internal/index.ts", "// Helpers shared inside this theme, private to it: not re-exported by the theme index.\n\nexport { snapToStep } from './snap-to-step';\n"],
  ["src/math/internal/snap-to-step.ts", "import { roundToFractionDigits } from '../round-to-fraction-digits';\n\nconst TOLERANCE = 1e-9;\nconst DECIMAL_BASE = 10;\n\nfunction countDecimals(step: number): number {\n  let decimals = 0;\n  let scaled = step;\n  while (Math.abs(scaled - Math.round(scaled)) > TOLERANCE * scaled) {\n    scaled *= DECIMAL_BASE;\n    decimals += 1;\n  }\n  return decimals;\n}\n\nexport function snapToStep(value: number, step: number, snap: (quotient: number) => number): number {\n  let quotient = value / step;\n  const nearest = Math.round(quotient);\n  // 0.3 / 0.1 is 2.9999999999999996: snap it to 3 before flooring.\n  if (Math.abs(quotient - nearest) <= TOLERANCE * Math.max(1, Math.abs(quotient))) {\n    quotient = nearest;\n  }\n  return roundToFractionDigits(snap(quotient) * step, countDecimals(step));\n}\n"],
  ["src/math/interpolate-table.spec.ts", "import { interpolateTable } from './interpolate-table';\n\nconst TANK = [\n  [0, 0],\n  [10, 150],\n  [20, 380],\n  [30, 600],\n] as const;\n\ndescribe(interpolateTable, () => {\n  it.for([\n    [15, 265],\n    [10, 150],\n    [25, 490],\n    [0, 0],\n    [30, 600],\n    [-5, 0],\n    [40, 600],\n  ] as const)('reads %s as %s', ([x, expected]) => {\n    expect(interpolateTable(x, TANK)).toBe(expected);\n  });\n\n  it('reads a large table', () => {\n    const table = Array.from({ length: 1001 }, (_, index) => [index, index * 2] as const);\n    expect(interpolateTable(512.25, table)).toBe(1024.5);\n  });\n\n  it('handles a single point and duplicate inputs', () => {\n    expect(interpolateTable(5, [[1, 7]])).toBe(7);\n    expect(\n      interpolateTable(1.5, [\n        [1, 10],\n        [1, 20],\n        [2, 30],\n      ]),\n    ).toBe(25);\n  });\n\n  it('returns NaN for an empty table', () => {\n    expect(interpolateTable(1, [])).toBeNaN();\n  });\n});\n"],
  ["src/math/interpolate-table.ts", "/**\n * Reads a lookup table with linear interpolation between its points, such as a calibration curve or a tank\n * gauging table. Outside the table, the first or last output is held. Binary search: O(log n).\n *\n * @param x - The input to look up.\n * @param table - The points `[x, y]`, sorted by increasing `x`.\n * @returns The interpolated output; `NaN` for an empty table.\n * @example\n * const tank = [[0, 0], [10, 150], [20, 380]] as const;\n * interpolateTable(15, tank); // 265\n * interpolateTable(40, tank); // 380\n */\nexport function interpolateTable(x: number, table: readonly (readonly [x: number, y: number])[]): number {\n  const [first] = table;\n  const last = table.at(-1);\n  if (first === undefined || last === undefined) {\n    return NaN;\n  }\n  if (x <= first[0]) {\n    return first[1];\n  }\n  if (x >= last[0]) {\n    return last[1];\n  }\n  let low = first;\n  let high = last;\n  let lowIndex = 0;\n  let highIndex = table.length - 1;\n  while (highIndex - lowIndex > 1) {\n    const middleIndex = (lowIndex + highIndex) >>> 1;\n    /* v8 ignore next -- `?? high` only satisfies noUncheckedIndexedAccess. */\n    const middle = table[middleIndex] ?? high;\n    if (middle[0] <= x) {\n      low = middle;\n      lowIndex = middleIndex;\n    } else {\n      high = middle;\n      highIndex = middleIndex;\n    }\n  }\n  return low[1] + ((high[1] - low[1]) * (x - low[0])) / (high[0] - low[0]);\n}\n"],
  ["src/math/inverse-lerp.spec.ts", "import { inverseLerp } from './inverse-lerp';\n\ndescribe(inverseLerp, () => {\n  it.for([\n    [0, 10, 5, 0.5],\n    [10, 0, 5, 0.5],\n    [0, 10, 20, 2],\n    [5, 5, 5, 0],\n    [5, 5, 100, 0],\n  ] as const)('places %s → %s at %s as %s', ([start, end, value, expected]) => {\n    expect(inverseLerp(start, end, value)).toBe(expected);\n  });\n});\n"],
  ["src/math/inverse-lerp.ts", "/**\n * Computes where a value sits between two numbers: the inverse of `lerp`. Not clamped.\n *\n * @param start - The value mapped to 0.\n * @param end - The value mapped to 1.\n * @param value - The value to locate.\n * @returns The interpolation factor; `0` when `start === end`.\n * @example\n * inverseLerp(0, 10, 5); // 0.5\n * inverseLerp(10, 0, 2.5); // 0.75\n */\nexport function inverseLerp(start: number, end: number, value: number): number {\n  const span = end - start;\n  return span === 0 ? 0 : (value - start) / span;\n}\n"],
  ["src/math/is-between.spec.ts", "import { isBetween } from './is-between';\n\ndescribe(isBetween, () => {\n  it.for([\n    [5, 0, 10, true],\n    [0, 0, 10, true],\n    [10, 0, 10, true],\n    [11, 0, 10, false],\n  ] as const)('checks %s in [%s, %s] inclusively as %s', ([value, min, max, expected]) => {\n    expect(isBetween(value, min, max, true)).toBe(expected);\n  });\n\n  it('excludes the bounds when not inclusive', () => {\n    expect(isBetween(0, 0, 10, false)).toBe(false);\n    expect(isBetween(10, 0, 10, false)).toBe(false);\n    expect(isBetween(5, 0, 10, false)).toBe(true);\n  });\n});\n"],
  ["src/math/is-between.ts", "/**\n * Checks whether a number lies between two bounds.\n *\n * @param value - The number to check.\n * @param min - The lower bound.\n * @param max - The upper bound.\n * @param isInclusive - Whether the bounds themselves are between. Defaults to `true`.\n * @returns `true` when `value` lies within the bounds.\n * @example\n * isBetween(10, 0, 10); // true\n * isBetween(10, 0, 10, false); // false\n */\nexport function isBetween(value: number, min: number, max: number, isInclusive = true): boolean {\n  return isInclusive ? value >= min && value <= max : value > min && value < max;\n}\n"],
  ["src/math/is-nearly-equal.spec.ts", "import { isNearlyEqual } from './is-nearly-equal';\n\ndescribe(isNearlyEqual, () => {\n  it('absorbs float noise', () => {\n    expect(isNearlyEqual(0.1 + 0.2, 0.3, 1e-9)).toBe(true);\n    expect(isNearlyEqual(1e12 + 0.0001, 1e12, 1e-9)).toBe(true);\n    expect(isNearlyEqual(5, 5, 1e-9)).toBe(true);\n  });\n\n  it('detects real differences', () => {\n    expect(isNearlyEqual(0.1, 0.1001, 1e-9)).toBe(false);\n    expect(isNearlyEqual(1, 1.1, 0.01)).toBe(false);\n    expect(isNearlyEqual(1, 1.1, 0.1)).toBe(true);\n  });\n\n  it('takes the defaults', () => {\n    expect(isNearlyEqual(0.1 + 0.2, 0.3)).toStrictEqual(isNearlyEqual(0.1 + 0.2, 0.3, 1e-9));\n  });\n});\n"],
  ["src/math/is-nearly-equal.ts", "/**\n * Checks whether two numbers are equal within a tolerance, relative for large numbers and absolute near zero.\n *\n * @param a - The first number.\n * @param b - The second number.\n * @param epsilon - The tolerance, relative to the largest magnitude (at least 1). Defaults to `1e-9`.\n * @returns `true` when the numbers differ by no more than the tolerance.\n * @example\n * isNearlyEqual(0.1 + 0.2, 0.3); // true\n * isNearlyEqual(1, 1.1, 0.01); // false\n */\nexport function isNearlyEqual(a: number, b: number, epsilon = 1e-9): boolean {\n  return a === b || Math.abs(a - b) <= epsilon * Math.max(1, Math.abs(a), Math.abs(b));\n}\n"],
  ["src/math/lerp.spec.ts", "import { lerp } from './lerp';\n\ndescribe(lerp, () => {\n  it.for([\n    [0, 10, 0, 0],\n    [0, 10, 1, 10],\n    [0, 10, 0.5, 5],\n    [0, 10, 2, 20],\n    [10, 0, 0.25, 7.5],\n  ] as const)('interpolates %s → %s at %s as %s', ([start, end, t, expected]) => {\n    expect(lerp(start, end, t)).toBe(expected);\n  });\n\n  it('is exact at t = 1', () => {\n    expect(lerp(0.1, 0.7, 1)).toBe(0.7);\n  });\n});\n"],
  ["src/math/lerp.ts", "/**\n * Interpolates linearly between two numbers, exact at both ends and extrapolated outside [0, 1].\n *\n * @param start - The value at `t = 0`.\n * @param end - The value at `t = 1`.\n * @param t - The interpolation factor.\n * @returns The interpolated value.\n * @example\n * lerp(0, 10, 0.25); // 2.5\n * lerp(0, 10, 2); // 20\n */\nexport function lerp(start: number, end: number, t: number): number {\n  return start * (1 - t) + end * t;\n}\n"],
  ["src/math/move-towards.spec.ts", "import { moveTowards } from './move-towards';\n\ndescribe(moveTowards, () => {\n  it.for([\n    [0, 10, 5, 1000, 5],\n    [0, 10, 5, 500, 2.5],\n    [10, 0, 5, 1000, 5],\n    [9, 10, 5, 1000, 10],\n    [10, 10, 5, 1000, 10],\n    [0, 10, 0, 1000, 0],\n  ] as const)('moves from %s towards %s at %s/s over %s ms: %s', ([current, target, rate, deltaMs, expected]) => {\n    expect(moveTowards(current, target, rate, deltaMs)).toBe(expected);\n  });\n\n  it('gives the same result whatever the frame rate', () => {\n    let value = 0;\n    for (let frame = 0; frame < 10; frame++) {\n      value = moveTowards(value, 100, 20, 100);\n    }\n    expect(value).toBeCloseTo(moveTowards(0, 100, 20, 1000), 9);\n  });\n});\n"],
  ["src/math/move-towards.ts", "const MS_PER_SECOND = 1000;\n\n/**\n * Moves a value towards a target at a limited rate (a slew-rate limiter), whatever the frame rate: a needle\n * or a rudder that cannot jump.\n *\n * @param current - The current value.\n * @param target - The value to reach.\n * @param maxRatePerSecond - The largest change per second.\n * @param deltaMs - The time elapsed since the previous call, in milliseconds.\n * @returns The new value, never beyond `target`.\n * @example\n * moveTowards(0, 10, 5, 1000); // 5\n * moveTowards(8, 10, 5, 1000); // 10\n */\nexport function moveTowards(current: number, target: number, maxRatePerSecond: number, deltaMs: number): number {\n  const maxStep = (maxRatePerSecond * deltaMs) / MS_PER_SECOND;\n  const difference = target - current;\n  return Math.abs(difference) <= maxStep ? target : current + Math.sign(difference) * maxStep;\n}\n"],
  ["src/math/ratio.spec.ts", "import { ratio } from './ratio';\n\ndescribe(ratio, () => {\n  it.for([\n    [5, 10, 0.5],\n    [15, 10, 1.5],\n    [5, 0, 0],\n    [0, 0, 0],\n    [-5, 10, -0.5],\n  ] as const)('computes %s / %s as %s', ([value, total, expected]) => {\n    expect(ratio(value, total)).toBe(expected);\n  });\n});\n"],
  ["src/math/ratio.ts", "/**\n * Divides a value by a total, without `NaN` or `Infinity`. Not clamped.\n *\n * @param value - The part.\n * @param total - The whole.\n * @returns `value / total`; `0` when `total` is `0`.\n * @example\n * ratio(5, 10); // 0.5\n * ratio(5, 0); // 0\n */\nexport function ratio(value: number, total: number): number {\n  return total === 0 ? 0 : value / total;\n}\n"],
  ["src/math/remap.spec.ts", "import { remap } from './remap';\n\ndescribe(remap, () => {\n  it('maps between ranges', () => {\n    expect(remap(5, 0, 10, 0, 100, false)).toBe(50);\n    expect(remap(5, 0, 10, 100, 0, false)).toBe(50);\n    expect(remap(2, 0, 10, 100, 200, false)).toBe(120);\n  });\n\n  it('extrapolates unless the output is clamped', () => {\n    expect(remap(15, 0, 10, 0, 100, false)).toBe(150);\n    expect(remap(15, 0, 10, 0, 100, true)).toBe(100);\n    expect(remap(-5, 0, 10, 0, 100, true)).toBe(0);\n  });\n\n  it('returns outMin for an empty input range', () => {\n    expect(remap(3, 1, 1, 0, 100, false)).toBe(0);\n  });\n});\n"],
  ["src/math/remap.ts", "import { clamp } from './clamp';\nimport { inverseLerp } from './inverse-lerp';\nimport { lerp } from './lerp';\n\n/**\n * Maps a value from an input range to an output range, such as a sensor reading to a gauge angle. Inverted\n * ranges work.\n *\n * @param value - The value to map.\n * @param inMin - The input mapped to `outMin`.\n * @param inMax - The input mapped to `outMax`.\n * @param outMin - The output for `inMin`.\n * @param outMax - The output for `inMax`.\n * @param shouldClamp - Whether to keep the result within the output range. Defaults to `false`.\n * @returns The mapped value; `outMin` when the input range is empty.\n * @example\n * remap(5, 0, 10, 0, 100); // 50\n * remap(15, 0, 10, 0, 100, true); // 100\n */\nexport function remap(\n  value: number,\n  inMin: number,\n  inMax: number,\n  outMin: number,\n  outMax: number,\n  shouldClamp = false,\n): number {\n  const t = inverseLerp(inMin, inMax, value);\n  return lerp(outMin, outMax, shouldClamp ? clamp(t) : t);\n}\n"],
  ["src/math/round-to-fraction-digits.spec.ts", "import { formatDecimal } from '../format';\nimport { roundToFractionDigits } from './round-to-fraction-digits';\n\ndescribe(roundToFractionDigits, () => {\n  it.for([\n    [1.005, 2, 1.01],\n    [1.004, 2, 1],\n    [-1.005, 2, -1.01],\n    [2.5, 0, 3],\n    [-2.5, 0, -3],\n    [0.285, 2, 0.29],\n    [1.45, 1, 1.5],\n    [123.456, 1, 123.5],\n    [1e21, 2, 1e21],\n    [0.0000001, 8, 0.0000001],\n    [1.5, 150, 1.5],\n  ] as const)('rounds %s to %s digits as %s', ([value, digits, expected]) => {\n    expect(roundToFractionDigits(value, digits)).toBe(expected);\n  });\n\n  it('never returns -0', () => {\n    expect(Object.is(roundToFractionDigits(-0.001, 2), 0)).toBe(true);\n    expect(Object.is(roundToFractionDigits(-0, 2), 0)).toBe(true);\n  });\n\n  it('returns non-finite values unchanged', () => {\n    expect(roundToFractionDigits(NaN, 2)).toBeNaN();\n    expect(roundToFractionDigits(Infinity, 2)).toBe(Infinity);\n  });\n\n  it('matches formatDecimal on decimal inputs', () => {\n    const mismatches: string[] = [];\n    for (let digits = 0; digits <= 4; digits++) {\n      for (let thousandths = -20_000; thousandths <= 20_000; thousandths += 7) {\n        const value = thousandths / 1000;\n        const expected = Number(formatDecimal(value, digits));\n        if (roundToFractionDigits(value, digits) !== expected) {\n          mismatches.push(`${value} (${digits} digits)`);\n        }\n      }\n    }\n    expect(mismatches).toStrictEqual([]);\n  });\n\n  it('takes the defaults', () => {\n    expect(roundToFractionDigits(Math.PI)).toStrictEqual(roundToFractionDigits(Math.PI, 3));\n  });\n});\n"],
  ["src/math/round-to-fraction-digits.ts", "const DECIMAL_BASE = 10;\nconst TABLE_SIZE = 101;\nconst POWERS_OF_TEN: readonly number[] = /* @__PURE__ */ Array.from(\n  { length: TABLE_SIZE },\n  (_, exponent) => DECIMAL_BASE ** exponent,\n);\nconst MAX_EXACT_INTEGER = Number.MAX_SAFE_INTEGER + 1;\n\n/**\n * Rounds a number to a number of decimals, half away from zero, with plain arithmetic: the same result as\n * `Number(formatDecimal(value, maxFractionDigits))`, much faster. Never returns `-0`.\n *\n * @param value - The number to round; `NaN` and infinities come back unchanged.\n * @param maxFractionDigits - The number of decimals to keep. Defaults to `3`.\n * @returns The rounded number.\n * @example\n * roundToFractionDigits(1.005, 2); // 1.01 (`toFixed` gives 1.00)\n * roundToFractionDigits(-2.5, 0); // -3\n */\nexport function roundToFractionDigits(value: number, maxFractionDigits = 3): number {\n  const factor = POWERS_OF_TEN[maxFractionDigits] ?? DECIMAL_BASE ** maxFractionDigits;\n  const scaled = Math.abs(value) * factor;\n  if (!Number.isFinite(scaled) || scaled >= MAX_EXACT_INTEGER) {\n    return value;\n  }\n  // `1 + EPSILON` absorbs the binary error: 1.005 is stored as 1.00499999999999989…\n  const rounded = Math.round(scaled * (1 + Number.EPSILON)) / factor;\n  return rounded !== 0 && value < 0 ? -rounded : rounded;\n}\n"],
  ["src/math/round-to-significant-digits.spec.ts", "import { roundToSignificantDigits } from './round-to-significant-digits';\n\ndescribe(roundToSignificantDigits, () => {\n  it.for([\n    [123_456, 3, 123_000],\n    [0.0012345, 3, 0.00123],\n    [-9.876, 2, -9.9],\n    [0.1 + 0.2, 15, 0.3],\n    [0, 3, 0],\n    [Infinity, 3, Infinity],\n  ] as const)('rounds %s to %s digits: %s', ([value, digits, expected]) => {\n    expect(roundToSignificantDigits(value, digits)).toBe(expected);\n  });\n\n  it('keeps NaN', () => {\n    expect(roundToSignificantDigits(NaN, 2)).toBeNaN();\n  });\n\n  it('takes the defaults', () => {\n    expect(roundToSignificantDigits(123_456)).toStrictEqual(roundToSignificantDigits(123_456, 3));\n  });\n});\n"],
  ["src/math/round-to-significant-digits.ts", "/**\n * Rounds a number to a number of significant digits, whatever its magnitude.\n *\n * @param value - The number to round.\n * @param digits - The significant digits to keep, from 1 to 100. Defaults to `3`.\n * @returns The rounded number; `NaN` and infinities unchanged.\n * @example\n * roundToSignificantDigits(123_456); // 123000\n * roundToSignificantDigits(0.001_234_5); // 0.00123\n */\nexport function roundToSignificantDigits(value: number, digits = 3): number {\n  return Number.isFinite(value) ? Number(value.toPrecision(digits)) : value;\n}\n"],
  ["src/math/round-to-step.spec.ts", "import { roundToStep } from './round-to-step';\n\ndescribe(roundToStep, () => {\n  it.for([\n    [0.3, 0.1, 0.3],\n    [0.29, 0.1, 0.3],\n    [7, 5, 5],\n    [8, 5, 10],\n    [-7, 5, -5],\n    [1.23456, 0.25, 1.25],\n    [0.00000037, 1e-7, 0.0000004],\n    [0.7, 0.1, 0.7],\n    [0.44, 0.1 + 0.2, 0.3],\n    [1.23456, 1e-100, 1.23456],\n  ] as const)('rounds %s to step %s as %s', ([value, step, expected]) => {\n    expect(roundToStep(value, step)).toBe(expected);\n  });\n\n  it('takes the defaults', () => {\n    expect(roundToStep(2.5)).toStrictEqual(roundToStep(2.5, 1));\n  });\n});\n"],
  ["src/math/round-to-step.ts", "import { snapToStep } from './internal';\n\n/**\n * Rounds a number to the nearest multiple of a step, without float noise: `roundToStep(0.3, 0.1)` is `0.3`.\n *\n * @param value - The number to round.\n * @param step - The step, a positive number such as `0.1`, `0.25` or `5`. Defaults to `1`.\n * @returns The nearest multiple of `step`, with no more decimals than `step`.\n * @example\n * roundToStep(0.29, 0.1); // 0.3\n * roundToStep(8, 5); // 10\n */\nexport function roundToStep(value: number, step = 1): number {\n  return snapToStep(value, step, Math.round);\n}\n"],
  ["src/math/smooth-towards.spec.ts", "import { smoothTowards } from './smooth-towards';\n\ndescribe(smoothTowards, () => {\n  it('covers about 63 % of the distance per time constant', () => {\n    expect(smoothTowards(0, 100, 100, 100)).toBeCloseTo(63.212, 3);\n  });\n\n  it('gives the same result whatever the frame rate', () => {\n    let fast = 0;\n    for (let frame = 0; frame < 10; frame++) {\n      fast = smoothTowards(fast, 100, 10, 100);\n    }\n    expect(fast).toBeCloseTo(smoothTowards(0, 100, 100, 100), 10);\n  });\n\n  it('jumps to the target without a time constant', () => {\n    expect(smoothTowards(0, 100, 16, 0)).toBe(100);\n  });\n});\n"],
  ["src/math/smooth-towards.ts", "/**\n * Moves a value towards a target with exponential smoothing, whatever the frame rate: about 63 % of the\n * distance is covered every `timeConstantMs`. Smooths a needle fed by noisy values.\n *\n * @param current - The displayed value.\n * @param target - The latest value.\n * @param deltaMs - The time elapsed since the previous call, in milliseconds.\n * @param timeConstantMs - The time constant, in milliseconds; `0` returns `target`.\n * @returns The new displayed value.\n * @example\n * needle = smoothTowards(needle, speed, deltaMs, 150);\n */\nexport function smoothTowards(current: number, target: number, deltaMs: number, timeConstantMs: number): number {\n  if (timeConstantMs <= 0) {\n    return target;\n  }\n  return target + (current - target) * Math.exp(-deltaMs / timeConstantMs);\n}\n"],
  ["src/math/wrap.spec.ts", "import { wrap } from './wrap';\n\ndescribe(wrap, () => {\n  it.for([\n    [370, 0, 360, 10],\n    [-10, 0, 360, 350],\n    [360, 0, 360, 0],\n    [-360, 0, 360, 0],\n    [-720.5, 0, 360, 359.5],\n    [5, 10, 20, 15],\n    [25, 20, 10, 15],\n  ] as const)('wraps %s into [%s, %s[ as %s', ([value, min, max, expected]) => {\n    expect(wrap(value, min, max)).toBe(expected);\n  });\n\n  it('never returns -0', () => {\n    expect(Object.is(wrap(-360, 0, 360), 0)).toBe(true);\n  });\n});\n"],
  ["src/math/wrap.ts", "/**\n * Wraps a number into [min, max[ with an always-positive modulo, like a heading wrapping at 360°.\n *\n * @param value - The number to wrap.\n * @param min - The included bound.\n * @param max - The excluded bound.\n * @returns The equivalent value in [min, max[.\n * @example\n * wrap(370, 0, 360); // 10\n * wrap(-10, 0, 360); // 350\n */\nexport function wrap(value: number, min: number, max: number): number {\n  const span = max - min;\n  return ((((value - min) % span) + span) % span) + min;\n}\n"],
  ["src/object/deep-merge.spec.ts", "import { assert, isRecord } from '../guard';\nimport { deepMerge } from './deep-merge';\n\ndescribe(deepMerge, () => {\n  const defaults = { grid: { step: 10, isVisible: true }, series: ['a', 'b'], title: 'Speed' };\n\n  it('merges nested objects and replaces other values', () => {\n    expect(deepMerge(defaults, { grid: { isVisible: false }, series: ['c'] })).toStrictEqual({\n      grid: { step: 10, isVisible: false },\n      series: ['c'],\n      title: 'Speed',\n    });\n  });\n\n  it('keeps the values that the patch leaves undefined', () => {\n    const base: { title?: string | undefined; grid?: { step: number } | undefined } = { title: 'a', grid: { step: 1 } };\n    expect(deepMerge(base, { title: undefined, grid: undefined })).toStrictEqual(base);\n  });\n\n  it('shares unchanged branches and modifies no argument', () => {\n    const patch = { title: 'Heading' };\n    const result = deepMerge(defaults, patch);\n    expect(result.grid).toBe(defaults.grid);\n    expect(defaults.title).toBe('Speed');\n    expect(patch).toStrictEqual({ title: 'Heading' });\n  });\n\n  it('adds keys missing from the base', () => {\n    expect(deepMerge<{ a?: { b?: number } }>({}, { a: { b: 1 } })).toStrictEqual({ a: { b: 1 } });\n  });\n\n  it('keeps __proto__ from JSON as an ordinary property', () => {\n    const patch: unknown = JSON.parse('{ \"__proto__\": { \"isAdmin\": true } }');\n    assert(isRecord(patch), 'Assertion failed');\n    const result = deepMerge<Record<string, unknown>>({}, patch);\n    expect(Object.getPrototypeOf(result)).toBe(Object.prototype);\n    expect(Object.hasOwn(result, '__proto__')).toBe(true);\n    expect(Object.prototype).not.toHaveProperty('isAdmin');\n  });\n});\n"],
  ["src/object/deep-merge.ts", "import { isRecord } from '../guard';\nimport type { DeepPartial } from '../types';\n\nfunction mergeValues(base: unknown, patch: unknown): unknown {\n  if (patch === undefined) {\n    return base;\n  }\n  if (!isRecord(base) || !isRecord(patch)) {\n    return patch;\n  }\n  return Object.fromEntries([\n    ...Object.entries(base),\n    ...Object.entries(patch).map(([key, value]) => [\n      key,\n      mergeValues(Object.hasOwn(base, key) ? base[key] : undefined, value),\n    ]),\n  ]);\n}\n\n/**\n * Applies a partial patch to nested settings, such as saved preferences over the defaults: plain objects are\n * merged at every depth, other values replace, `undefined` keeps. A `__proto__` key stays a plain property.\n *\n * @template T - The type of the settings.\n * @param base - The complete object, such as the defaults.\n * @param patch - The values to change.\n * @returns A new object that shares the unchanged branches with `base`.\n * @example\n * deepMerge({ grid: { step: 10, isVisible: true } }, { grid: { isVisible: false } });\n * // { grid: { step: 10, isVisible: false } }\n */\nexport function deepMerge<T extends object>(base: T, patch: DeepPartial<NoInfer<T>>): T {\n  // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion -- A DeepPartial<T> merged into a T is a T.\n  return mergeValues(base, patch) as T;\n}\n"],
  ["src/object/index.ts", "// Objects: picking, omitting, mapping values, emptiness and equality.\n\nexport { isShallowEqual } from './is-shallow-equal';\nexport { pick } from './pick';\nexport { omit } from './omit';\nexport { mapValues } from './map-values';\nexport { isDeepEqual } from './is-deep-equal';\nexport { isEmpty } from './is-empty';\nexport { deepMerge } from './deep-merge';\n"],
  ["src/object/is-deep-equal.spec.ts", "import { isDeepEqual } from './is-deep-equal';\n\nclass Point {\n  public readonly x: number;\n  public readonly y: number;\n\n  public constructor(x: number, y: number) {\n    this.x = x;\n    this.y = y;\n  }\n}\n\ndescribe(isDeepEqual, () => {\n  it.for([\n    [1, 1],\n    [NaN, NaN],\n    [0, -0],\n    ['a', 'a'],\n    [null, null],\n    [{ a: { b: [1, 2] } }, { a: { b: [1, 2] } }],\n    [\n      [1, [2, [3]]],\n      [1, [2, [3]]],\n    ],\n    [new Date(5), new Date(5)],\n    [/a/giv, /a/giv],\n    [new Set([1, 2]), new Set([2, 1])],\n    [new Map([['k', { v: 1 }]]), new Map([['k', { v: 1 }]])],\n    [new Float64Array([1, 2]), new Float64Array([1, 2])],\n    [new Point(1, 2), new Point(1, 2)],\n  ])('finds %j and %j equal', ([a, b]) => {\n    expect(isDeepEqual(a, b)).toBe(true);\n  });\n\n  it.for([\n    [1, 2],\n    [1, '1'],\n    [null, undefined],\n    [{}, null],\n    [{ a: 1 }, { a: 2 }],\n    [{ a: 1 }, { a: 1, b: undefined }],\n    [\n      { a: 1, c: 2 },\n      { a: 1, b: 2 },\n    ],\n    [\n      [1, 2],\n      [2, 1],\n    ],\n    [[1], { 0: 1 }],\n    [new Date(5), new Date(6)],\n    [/a/v, /a/iv],\n    [/a/v, /b/v],\n    [new Set([1]), new Set([2])],\n    [new Set([1]), new Set([1, 2])],\n    [new Map([['k', 1]]), new Map([['k', 2]])],\n    [new Map([['k', 1]]), new Map([['j', 1]])],\n    [new Map([['k', 1]]), new Map()],\n    [new Uint8Array([1, 2]), new Uint8Array([1, 3])],\n    [new Uint8Array([1]), new Uint8Array([1, 2])],\n    [new Point(1, 2), { x: 1, y: 2 }],\n  ])('finds %j and %j different', ([a, b]) => {\n    expect(isDeepEqual(a, b)).toBe(false);\n  });\n\n  it('supports circular references', () => {\n    const a: { self?: unknown; value: number } = { value: 1 };\n    a.self = a;\n    const b: { self?: unknown; value: number } = { value: 1 };\n    b.self = b;\n    expect(isDeepEqual(a, b)).toBe(true);\n    expect(isDeepEqual([a, a], [b, b])).toBe(true);\n  });\n});\n"],
  ["src/object/is-deep-equal.ts", "import { isObject } from '../guard';\n\ntype Visited = WeakMap<object, WeakSet<object>>;\n\nfunction equalObjects(a: object, b: object, visited: Visited): boolean {\n  if (a instanceof Date && b instanceof Date) {\n    return Object.is(a.getTime(), b.getTime());\n  }\n  if (a instanceof RegExp && b instanceof RegExp) {\n    return a.source === b.source && a.flags === b.flags;\n  }\n  if (a instanceof Set && b instanceof Set) {\n    return a.size === b.size && [...a].every((item: unknown) => b.has(item));\n  }\n  if (a instanceof Map && b instanceof Map) {\n    return (\n      a.size === b.size &&\n      [...a].every(([key, value]: readonly [unknown, unknown]) => b.has(key) && equals(value, b.get(key), visited))\n    );\n  }\n  if (ArrayBuffer.isView(a) && ArrayBuffer.isView(b)) {\n    const first = new Uint8Array(a.buffer, a.byteOffset, a.byteLength);\n    const second = new Uint8Array(b.buffer, b.byteOffset, b.byteLength);\n    return first.length === second.length && first.every((byte, index) => byte === second[index]);\n  }\n  const keys = Object.keys(a);\n  return (\n    keys.length === Object.keys(b).length &&\n    keys.every((key) => Object.hasOwn(b, key) && equals(Reflect.get(a, key), Reflect.get(b, key), visited))\n  );\n}\n\nfunction equals(a: unknown, b: unknown, visited: Visited): boolean {\n  if (a === b || (Number.isNaN(a) && Number.isNaN(b))) {\n    return true;\n  }\n  if (!isObject(a) || !isObject(b) || Object.getPrototypeOf(a) !== Object.getPrototypeOf(b)) {\n    return false;\n  }\n  const seen = visited.get(a);\n  if (seen?.has(b) === true) {\n    return true;\n  }\n  visited.set(a, (seen ?? new WeakSet()).add(b));\n  return equalObjects(a, b, visited);\n}\n\n/**\n * Checks whether two values are equal at every depth: primitives (`NaN` equals `NaN`), arrays, objects with the same\n * prototype, `Date`, `RegExp`, `Map`, `Set` and typed arrays. Circular references work.\n *\n * @param a - The first value.\n * @param b - The second value.\n * @returns `true` when both values have the same structure and contents.\n * @example\n * isDeepEqual({ position: { x: 1 }, tags: ['a'] }, { position: { x: 1 }, tags: ['a'] }); // true\n */\nexport function isDeepEqual(a: unknown, b: unknown): boolean {\n  return equals(a, b, new WeakMap());\n}\n"],
  ["src/object/is-empty.spec.ts", "import { isEmpty } from './is-empty';\n\ndescribe(isEmpty, () => {\n  it.for([null, undefined, '', [], {}, new Map(), new Set(), new Float64Array(0)])('finds %j empty', (value) => {\n    expect(isEmpty(value)).toBe(true);\n  });\n\n  it.for([' ', [0], { a: undefined }, new Map([[1, 1]]), new Set([0]), new Uint8Array(1), 0, false, (): number => 0])(\n    'finds %j not empty',\n    (value) => {\n      expect(isEmpty(value)).toBe(false);\n    },\n  );\n});\n"],
  ["src/object/is-empty.ts", "/**\n * Checks whether a container holds nothing: an empty string, array, `Map`, `Set` or object. `null` and\n * `undefined` count as empty.\n *\n * @param value - The value to check.\n * @returns `true` for an empty container, `null` or `undefined`; `false` for a number or a boolean.\n * @example\n * isEmpty({}); // true\n * isEmpty([0]); // false\n * isEmpty(new Map()); // true\n */\nexport function isEmpty(value: unknown): boolean {\n  if (value === null || value === undefined) {\n    return true;\n  }\n  if (typeof value === 'string') {\n    return value.length === 0;\n  }\n  if (typeof value !== 'object') {\n    return false;\n  }\n  if (value instanceof Map || value instanceof Set) {\n    return value.size === 0;\n  }\n  return (\n    (Array.isArray(value) || ArrayBuffer.isView(value) ? Reflect.get(value, 'length') : Object.keys(value).length) === 0\n  );\n}\n"],
  ["src/object/is-shallow-equal.spec.ts", "import { isShallowEqual } from './is-shallow-equal';\n\ndescribe(isShallowEqual, () => {\n  it.for([\n    [1, 1, true],\n    [NaN, NaN, true],\n    [0, -0, false],\n    ['a', 'b', false],\n    [null, null, true],\n    [null, {}, false],\n    [{ x: 1, y: 2 }, { y: 2, x: 1 }, true],\n    [{ x: 1 }, { x: 1, y: 2 }, false],\n    [{ x: 1, y: undefined }, { x: 1, z: undefined }, false],\n    [{ x: 1 }, { x: 2 }, false],\n    [[1, 2], [1, 2], true],\n    [[1, 2], { 0: 1, 1: 2 }, false],\n    [{ p: { x: 1 } }, { p: { x: 1 } }, false],\n  ] as const)('compares %j and %j as %s', ([a, b, expected]) => {\n    expect(isShallowEqual(a, b)).toBe(expected);\n  });\n\n  it('accepts shared nested references', () => {\n    const point = { x: 1 };\n    expect(isShallowEqual({ point }, { point })).toBe(true);\n  });\n});\n"],
  ["src/object/is-shallow-equal.ts", "import { isObject } from '../guard';\n\n/**\n * Checks whether two values are equal at the first level, with `Object.is`: skips an update when a new object carries the\n * same values as the previous one.\n *\n * @param a - The first value.\n * @param b - The second value.\n * @returns `true` when both values are shallowly equal; nested objects are compared by reference.\n * @example\n * isShallowEqual({ x: 1, y: 2 }, { y: 2, x: 1 }); // true\n * isShallowEqual({ p: { x: 1 } }, { p: { x: 1 } }); // false\n */\nexport function isShallowEqual(a: unknown, b: unknown): boolean {\n  if (Object.is(a, b)) {\n    return true;\n  }\n  if (!isObject(a) || !isObject(b) || Array.isArray(a) !== Array.isArray(b)) {\n    return false;\n  }\n  const keys = Object.keys(a);\n  return (\n    keys.length === Object.keys(b).length &&\n    keys.every((key) => Object.hasOwn(b, key) && Object.is(Reflect.get(a, key), Reflect.get(b, key)))\n  );\n}\n"],
  ["src/object/map-values.spec.ts", "import { mapValues } from './map-values';\n\ndescribe(mapValues, () => {\n  it('maps every value, keeping the keys', () => {\n    expect(mapValues({ rpm: 800, temperature: 72 }, (value) => value * 2)).toStrictEqual({\n      rpm: 1600,\n      temperature: 144,\n    });\n  });\n\n  it('passes the key to the mapper', () => {\n    expect(mapValues({ a: 1, b: 2 }, (value, key) => `${key}=${value}`)).toStrictEqual({ a: 'a=1', b: 'b=2' });\n  });\n\n  it('returns an empty object for an empty one', () => {\n    expect(mapValues({}, () => 0)).toStrictEqual({});\n  });\n});\n"],
  ["src/object/map-values.ts", "/**\n * Transforms every value of an object, keeping its keys.\n *\n * @template T - The type of the object.\n * @template U - The type of the new values.\n * @param object - The source object.\n * @param mapper - Returns the new value of a property, from its value and its key.\n * @returns A new object with the same keys.\n * @example\n * mapValues({ rpm: 800.4, temperature: 72.25 }, (value) => formatDecimal(value, 1));\n * // { rpm: '800.4', temperature: '72.3' }\n */\nexport function mapValues<T extends object, U>(\n  object: T,\n  mapper: (value: T[keyof T], key: keyof T & string) => U,\n): Record<keyof T & string, U> {\n  const result: Record<string, U> = {};\n  for (const [key, value] of Object.entries(object)) {\n    // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion -- The own string keys of `T` and their values.\n    result[key] = mapper(value as T[keyof T], key as keyof T & string);\n  }\n  return result;\n}\n"],
  ["src/object/omit.spec.ts", "import { omit } from './omit';\n\ndescribe(omit, () => {\n  it('leaves the requested keys out', () => {\n    expect(omit({ id: 1, name: 'Pump', internalRef: 'x' }, ['internalRef'])).toStrictEqual({ id: 1, name: 'Pump' });\n  });\n\n  it('keeps symbol keys and does not modify the source', () => {\n    const tag = Symbol('tag');\n    const source = { id: 1, [tag]: 'kept' };\n    expect(omit(source, ['id'])).toStrictEqual({ [tag]: 'kept' });\n    expect(source).toStrictEqual({ id: 1, [tag]: 'kept' });\n  });\n\n  it('skips non-enumerable properties', () => {\n    const source = Object.defineProperty({ id: 1 }, 'hidden', { value: true, enumerable: false });\n    expect(omit(source, [])).toStrictEqual({ id: 1 });\n  });\n});\n"],
  ["src/object/omit.ts", "/**\n * Copies an object without some of its properties, without `delete`, which slows down V8.\n *\n * @template T - The type of the object.\n * @template K - The keys to leave out.\n * @param object - The source object.\n * @param keys - The keys to leave out.\n * @returns A new object with the other properties.\n * @example\n * omit({ id: 1, name: 'Pump', internalRef: 'x' }, ['internalRef']); // { id: 1, name: 'Pump' }\n */\nexport function omit<T extends object, K extends keyof T>(object: T, keys: readonly K[]): Omit<T, K> {\n  const excluded = new Set<PropertyKey>(keys);\n  const result: Record<PropertyKey, unknown> = {};\n  for (const key of Reflect.ownKeys(object)) {\n    if (!excluded.has(key) && Object.prototype.propertyIsEnumerable.call(object, key)) {\n      result[key] = Reflect.get(object, key);\n    }\n  }\n  // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion -- Every other own enumerable key is copied.\n  return result as Omit<T, K>;\n}\n"],
  ["src/object/pick.spec.ts", "import { pick } from './pick';\n\nclass WithInheritedGetter {\n  private readonly value = true;\n\n  public get inherited(): boolean {\n    return this.value;\n  }\n}\n\ndescribe(pick, () => {\n  it('keeps the requested keys', () => {\n    expect(pick({ id: 1, name: 'Pump', rpm: 800 }, ['id', 'name'])).toStrictEqual({ id: 1, name: 'Pump' });\n  });\n\n  it('leaves absent keys out and does not modify the source', () => {\n    const source: { id: number; label?: string } = { id: 1 };\n    expect(pick(source, ['id', 'label'])).toStrictEqual({ id: 1 });\n    expect(source).toStrictEqual({ id: 1 });\n  });\n\n  it('ignores inherited properties', () => {\n    expect(pick(new WithInheritedGetter(), ['inherited'])).toStrictEqual({});\n  });\n});\n"],
  ["src/object/pick.ts", "/**\n * Copies some properties of an object into a new one. Keys absent from the object are left out.\n *\n * @template T - The type of the object.\n * @template K - The keys to keep.\n * @param object - The source object.\n * @param keys - The keys to copy.\n * @returns A new object with only those keys.\n * @example\n * pick({ id: 1, name: 'Pump', rpm: 800 }, ['id', 'name']); // { id: 1, name: 'Pump' }\n */\nexport function pick<T extends object, K extends keyof T>(object: T, keys: readonly K[]): Pick<T, K> {\n  const result: Partial<Pick<T, K>> = {};\n  for (const key of keys) {\n    if (Object.hasOwn(object, key)) {\n      result[key] = object[key];\n    }\n  }\n  // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion -- Every requested own key is copied.\n  return result as Pick<T, K>;\n}\n"],
  ["src/path/index.ts", "// Paths: joining URL segments.\n\nexport { joinPath } from './join-path';\n"],
  ["src/path/join-path.spec.ts", "import { joinPath } from './join-path';\n\ndescribe(joinPath, () => {\n  it.for([\n    [['a', 'b', 'c'], 'a/b/c'],\n    [['/a/', '/b/', 'c'], '/a/b/c'],\n    [['/assets', '', 'img/'], '/assets/img/'],\n    [['https://api.example.com/', '/v1/', 'users'], 'https://api.example.com/v1/users'],\n    [['wss://host//', '//x'], 'wss://host/x'],\n    [['/', 'a'], '/a'],\n    [['a//b', 'c'], 'a/b/c'],\n    [['', ''], ''],\n    [[], ''],\n  ] as const)('joins %j as %j', ([segments, expected]) => {\n    expect(joinPath(...segments)).toBe(expected);\n  });\n});\n"],
  ["src/path/join-path.ts", "const REPEATED_SLASHES_PATTERN = /(?<!:)\\/{2,}/gv;\n\n/**\n * Joins URL path segments with `/`, ignoring empty segments and collapsing repeated slashes, except the\n * `//` of a protocol.\n *\n * @param segments - The segments to join, with or without their own slashes.\n * @returns The joined path.\n * @example\n * joinPath('https://api.example.com/', '/v1/', 'users'); // 'https://api.example.com/v1/users'\n * joinPath('/assets', '', 'img/'); // '/assets/img/'\n */\nexport function joinPath(...segments: readonly string[]): string {\n  return segments\n    .filter((segment) => segment !== '')\n    .join('/')\n    .replaceAll(REPEATED_SLASHES_PATTERN, '/');\n}\n"],
  ["src/string/camel-case.spec.ts", "import { camelCase } from './camel-case';\n\ndescribe(camelCase, () => {\n  it.for([\n    ['user-id', 'userId'],\n    ['user_id', 'userId'],\n    ['User Id', 'userId'],\n    ['USER_ID', 'userId'],\n    ['userId', 'userId'],\n    ['XMLHttpRequest', 'xmlHttpRequest'],\n    ['speed 2 knots', 'speed2Knots'],\n    ['', ''],\n  ] as const)('converts %j to %j', ([input, expected]) => {\n    expect(camelCase(input)).toBe(expected);\n  });\n});\n"],
  ["src/string/camel-case.ts", "import { capitalize } from './capitalize';\nimport { splitWords } from './split-words';\n\n/**\n * Converts a string to camelCase; acronyms are words (`XMLHttpRequest` → `xmlHttpRequest`).\n *\n * @param input - The identifier or sentence to convert, in any case style.\n * @returns The camelCase string; `''` when the input has no word.\n * @example\n * camelCase('user-id'); // 'userId'\n * camelCase('XML HTTP request'); // 'xmlHttpRequest'\n */\nexport function camelCase(input: string): string {\n  return splitWords(input)\n    .map((word, index) => (index === 0 ? word.toLowerCase() : capitalize(word.toLowerCase())))\n    .join('');\n}\n"],
  ["src/string/capitalize.spec.ts", "import { capitalize } from './capitalize';\n\ndescribe(capitalize, () => {\n  it.for([\n    ['hello world', 'Hello world'],\n    ['Hello', 'Hello'],\n    ['hELLO', 'HELLO'],\n    ['élan', 'Élan'],\n    ['1st', '1st'],\n    ['', ''],\n    ['\\u{10428}x', '\\u{10400}x'],\n  ] as const)('capitalizes %j as %j', ([input, expected]) => {\n    expect(capitalize(input)).toBe(expected);\n  });\n});\n"],
  ["src/string/capitalize.ts", "/**\n * Upper-cases the first character of a string, even outside the basic Unicode plane.\n *\n * @param input - The string.\n * @returns The string with its first character in upper case.\n * @example\n * capitalize('hello world'); // 'Hello world'\n * capitalize('élan'); // 'Élan'\n */\nexport function capitalize(input: string): string {\n  const first = input.codePointAt(0);\n  if (first === undefined) {\n    return input;\n  }\n  const firstCharacter = String.fromCodePoint(first);\n  return firstCharacter.toUpperCase() + input.slice(firstCharacter.length);\n}\n"],
  ["src/string/constant-case.spec.ts", "import { constantCase } from './constant-case';\n\ndescribe(constantCase, () => {\n  it.for([\n    ['maxChannel', 'MAX_CHANNEL'],\n    ['api-base-url', 'API_BASE_URL'],\n    ['Half turn', 'HALF_TURN'],\n    ['MAX_CHANNEL', 'MAX_CHANNEL'],\n    ['', ''],\n  ] as const)('converts %j to %j', ([input, expected]) => {\n    expect(constantCase(input)).toBe(expected);\n  });\n});\n"],
  ["src/string/constant-case.ts", "import { splitWords } from './split-words';\n\n/**\n * Converts a string to CONSTANT_CASE: uppercase words joined with `_`, as in constants and environment\n * variables.\n *\n * @param input - The identifier or sentence to convert, in any case style.\n * @returns The CONSTANT_CASE string; `''` when the input has no word.\n * @example\n * constantCase('maxChannel'); // 'MAX_CHANNEL'\n * constantCase('api-base-url'); // 'API_BASE_URL'\n */\nexport function constantCase(input: string): string {\n  return splitWords(input)\n    .map((word) => word.toUpperCase())\n    .join('_');\n}\n"],
  ["src/string/create-id-generator.spec.ts", "import { createIdGenerator } from './create-id-generator';\n\ndescribe(createIdGenerator, () => {\n  it('generates increasing ids with the prefix', () => {\n    const nextId = createIdGenerator('alarm');\n    expect([nextId(), nextId(), nextId()]).toStrictEqual(['alarm-1', 'alarm-2', 'alarm-3']);\n  });\n\n  it('counts separately for each generator', () => {\n    const first = createIdGenerator('a');\n    const second = createIdGenerator('b');\n    first();\n    expect(second()).toBe('b-1');\n  });\n});\n"],
  ["src/string/create-id-generator.ts", "/**\n * Creates a generator of readable unique ids: `gauge-1`, `gauge-2`… for SVG gradients, clip paths or markers.\n * Each generator counts on its own: use one prefix per generator.\n *\n * @param prefix - The start of every id, such as the component name.\n * @returns A function returning the next id at each call.\n * @example\n * const nextGradientId = createIdGenerator('gauge-gradient');\n * gradient.id = nextGradientId(); // 'gauge-gradient-1'\n * arc.setAttribute('stroke', `url(#${gradient.id})`);\n */\nexport function createIdGenerator(prefix: string): () => string {\n  let counter = 0;\n  return (): string => {\n    counter += 1;\n    return `${prefix}-${counter}`;\n  };\n}\n"],
  ["src/string/dot-case.spec.ts", "import { dotCase } from './dot-case';\n\ndescribe(dotCase, () => {\n  it.for([\n    ['engineRoomTemperature', 'engine.room.temperature'],\n    ['Alarm Panel', 'alarm.panel'],\n    ['', ''],\n  ] as const)('converts %j to %j', ([input, expected]) => {\n    expect(dotCase(input)).toBe(expected);\n  });\n});\n"],
  ["src/string/dot-case.ts", "import { splitWords } from './split-words';\n\n/**\n * Converts a string to dot.case: lower-case words joined with `.`, as in translation keys and property paths.\n *\n * @param input - The identifier or sentence to convert, in any case style.\n * @returns The dot.case string; `''` when there is no word.\n * @example\n * dotCase('engineRoomTemperature'); // 'engine.room.temperature'\n */\nexport function dotCase(input: string): string {\n  return splitWords(input)\n    .map((word) => word.toLowerCase())\n    .join('.');\n}\n"],
  ["src/string/escape-html.spec.ts", "import { escapeHtml } from './escape-html';\n\ndescribe(escapeHtml, () => {\n  it.for([\n    ['<b>\"Tom & Jerry\"</b>', '&lt;b&gt;&quot;Tom &amp; Jerry&quot;&lt;/b&gt;'],\n    [\"it's\", 'it&#39;s'],\n    ['plain text', 'plain text'],\n    ['&amp;', '&amp;amp;'],\n    ['', ''],\n  ] as const)('escapes %j', ([input, expected]) => {\n    expect(escapeHtml(input)).toBe(expected);\n  });\n});\n"],
  ["src/string/escape-html.ts", "/**\n * Escapes the characters that have a meaning in HTML (`& < > \" '`), to insert a text in markup.\n *\n * @param input - The text to escape.\n * @returns The escaped text.\n * @example\n * escapeHtml('<b>\"Tom & Jerry\"</b>'); // '&lt;b&gt;&quot;Tom &amp; Jerry&quot;&lt;/b&gt;'\n */\nexport function escapeHtml(input: string): string {\n  return input\n    .replaceAll('&', '&amp;')\n    .replaceAll('<', '&lt;')\n    .replaceAll('>', '&gt;')\n    .replaceAll('\"', '&quot;')\n    .replaceAll(\"'\", '&#39;');\n}\n"],
  ["src/string/escape-reg-exp.spec.ts", "import { escapeRegExp } from './escape-reg-exp';\n\ndescribe(escapeRegExp, () => {\n  it.for(['1+1=2?', '(a|b)[c]{d}', String.raw`C:\\path\\file.txt`, 'price: $5.00 ^_^', 'a-b & c', 'plain'])(\n    'matches %j literally with the v flag',\n    (input) => {\n      const pattern = new RegExp(`^${escapeRegExp(input)}$`, 'v');\n      expect(pattern.test(input)).toBe(true);\n    },\n  );\n\n  it('matches literally with the u flag and without flags', () => {\n    const input = '(a|b)*.c';\n    const unicodePattern = new RegExp(escapeRegExp(input), 'u');\n    const plainPattern = new RegExp(escapeRegExp(input));\n    expect(unicodePattern.test(`x${input}x`)).toBe(true);\n    expect(plainPattern.test('ab.c')).toBe(false);\n  });\n\n  it('escapes the syntax characters only', () => {\n    expect(escapeRegExp('a.b')).toBe(String.raw`a\\.b`);\n    expect(escapeRegExp('abc')).toBe('abc');\n  });\n});\n"],
  ["src/string/escape-reg-exp.ts", "const SYNTAX_CHARACTERS: ReadonlySet<string> = new Set([\n  '\\\\',\n  '^',\n  '$',\n  '.',\n  '*',\n  '+',\n  '?',\n  '(',\n  ')',\n  '[',\n  ']',\n  '{',\n  '}',\n  '|',\n  '/',\n]);\n\n/**\n * Escapes a text so that it matches literally in a regular expression, `v` flag included.\n *\n * @param input - The literal text to search for.\n * @returns The text with every regular expression syntax character escaped.\n * @example\n * new RegExp(`^${escapeRegExp('1+1=2?')}$`, 'v').test('1+1=2?'); // true\n */\nexport function escapeRegExp(input: string): string {\n  return Array.from(input, (character) => (SYNTAX_CHARACTERS.has(character) ? `\\\\${character}` : character)).join('');\n}\n"],
  ["src/string/extract-number.spec.ts", "import { extractNumber } from './extract-number';\n\ndescribe(extractNumber, () => {\n  it.for([\n    ['42', 42],\n    ['Speed: -12,5 kn', -12.5],\n    ['heading 270.5°', 270.5],\n    ['+3', 3],\n    ['value .5', 0.5],\n    ['1,234', 1.234],\n    ['a1b2', 1],\n  ] as const)('extracts %j as %s', ([input, expected]) => {\n    expect(extractNumber(input)).toBe(expected);\n  });\n\n  it.for(['', 'n/a', '-', '.', 'abc'])('returns undefined for %j', (input) => {\n    expect(extractNumber(input)).toBeUndefined();\n  });\n});\n"],
  ["src/string/extract-number.ts", "import { parseMatchedNumber } from './internal';\n\nconst NUMBER_SOURCE = String.raw`[+\\-]?(?:\\d+(?:[,.]\\d+)?|[,.]\\d+)`;\n\nconst NUMBER_PATTERN = new RegExp(NUMBER_SOURCE, 'v');\n\n/**\n * Extracts the first number of a text, with `.` or `,` before the decimals: `1,234` is `1.234`.\n *\n * @param input - A text, such as a label or a sensor message.\n * @returns The first number; `undefined` when there is none.\n * @example\n * extractNumber('Speed: -12,5 kn'); // -12.5\n * extractNumber('n/a'); // undefined\n */\nexport function extractNumber(input: string): number | undefined {\n  const match = NUMBER_PATTERN.exec(input);\n  return match ? parseMatchedNumber(match[0]) : undefined;\n}\n"],
  ["src/string/extract-numbers.spec.ts", "import { extractNumbers } from './extract-numbers';\n\ndescribe(extractNumbers, () => {\n  it('extracts every number', () => {\n    expect(extractNumbers('from 1.5 to -3, then +2,25')).toStrictEqual([1.5, -3, 2.25]);\n    expect(extractNumbers('none')).toStrictEqual([]);\n  });\n\n  it('can be called repeatedly (no shared regex state)', () => {\n    expect(extractNumbers('1 2')).toStrictEqual([1, 2]);\n    expect(extractNumbers('1 2')).toStrictEqual([1, 2]);\n  });\n});\n"],
  ["src/string/extract-numbers.ts", "import { parseMatchedNumber } from './internal';\n\nconst NUMBER_SOURCE = String.raw`[+\\-]?(?:\\d+(?:[,.]\\d+)?|[,.]\\d+)`;\n\nconst NUMBERS_PATTERN = new RegExp(NUMBER_SOURCE, 'gv');\n\n/**\n * Extracts every number of a text, with the rules of `extractNumber`.\n *\n * @param input - A text.\n * @returns The numbers found, in order; empty when there is none.\n * @example\n * extractNumbers('from 1.5 to -3'); // [1.5, -3]\n */\nexport function extractNumbers(input: string): number[] {\n  return Array.from(input.matchAll(NUMBERS_PATTERN), (match) => parseMatchedNumber(match[0]));\n}\n"],
  ["src/string/format-template.spec.ts", "import { formatTemplate } from './format-template';\n\ndescribe(formatTemplate, () => {\n  it('replaces the placeholders', () => {\n    expect(formatTemplate('Heading {heading}°, speed {speed} kn', { heading: 270, speed: 12.5 })).toBe(\n      'Heading 270°, speed 12.5 kn',\n    );\n    expect(formatTemplate('{a}{a}{b}', { a: 'x', b: true })).toBe('xxtrue');\n  });\n\n  it('keeps the placeholders without a value', () => {\n    expect(formatTemplate('Hello {name}', {})).toBe('Hello {name}');\n    expect(formatTemplate('Hello {name}', { name: undefined })).toBe('Hello {name}');\n    expect(formatTemplate('{toString}', {})).toBe('{toString}');\n  });\n\n  it('accepts dotted keys and ignores malformed placeholders', () => {\n    expect(formatTemplate('{user.name} { } {}', { 'user.name': 'Ada' })).toBe('Ada { } {}');\n  });\n});\n"],
  ["src/string/format-template.ts", "const PLACEHOLDER_PATTERN = /\\{(?<key>[\\w$.]+)\\}/gv;\n\n/**\n * Replaces the `{key}` placeholders of a template with values. A placeholder without value is kept, so that\n * it shows.\n *\n * @param template - A text with `{key}` placeholders.\n * @param values - The values by key.\n * @returns The text with every known placeholder replaced.\n * @example\n * formatTemplate('Heading {heading}°, speed {speed} kn', { heading: 270, speed: 12.5 });\n * // 'Heading 270°, speed 12.5 kn'\n * formatTemplate('Hello {name}', {}); // 'Hello {name}'\n */\nexport function formatTemplate(\n  template: string,\n  values: Readonly<Record<string, boolean | number | string | undefined>>,\n): string {\n  return template.replaceAll(PLACEHOLDER_PATTERN, (placeholder: string, key: string) => {\n    const value = Object.hasOwn(values, key) ? values[key] : undefined;\n    return value === undefined ? placeholder : String(value);\n  });\n}\n"],
  ["src/string/index.ts", "// Strings: case conversion, word splitting, truncation, escaping, templating, number extraction.\n\nexport { extractNumber } from './extract-number';\nexport { extractNumbers } from './extract-numbers';\nexport { splitWords } from './split-words';\nexport { capitalize } from './capitalize';\nexport { camelCase } from './camel-case';\nexport { pascalCase } from './pascal-case';\nexport { kebabCase } from './kebab-case';\nexport { snakeCase } from './snake-case';\nexport { constantCase } from './constant-case';\nexport { titleCase } from './title-case';\nexport { sentenceCase } from './sentence-case';\nexport { truncate } from './truncate';\nexport { slugify } from './slugify';\nexport { escapeHtml } from './escape-html';\nexport { escapeRegExp } from './escape-reg-exp';\nexport { formatTemplate } from './format-template';\nexport { lowerCase } from './lower-case';\nexport { upperCase } from './upper-case';\nexport { dotCase } from './dot-case';\nexport { trainCase } from './train-case';\nexport { uncapitalize } from './uncapitalize';\nexport { removeDiacritics } from './remove-diacritics';\nexport { isBlank } from './is-blank';\nexport { squish } from './squish';\nexport { pluralize } from './pluralize';\nexport { toCsv } from './to-csv';\nexport { createIdGenerator } from './create-id-generator';\n"],
  ["src/string/internal/index.ts", "// Helpers shared inside this theme, private to it: not re-exported by the theme index.\n\nexport { parseMatchedNumber } from './parse-matched-number';\n"],
  ["src/string/internal/parse-matched-number.ts", "export function parseMatchedNumber(text: string): number {\n  return Number(text.replace(',', '.'));\n}\n"],
  ["src/string/is-blank.spec.ts", "import { isBlank } from './is-blank';\n\ndescribe(isBlank, () => {\n  it.for([\n    [null, true],\n    [undefined, true],\n    ['', true],\n    [' \\n\\t', true],\n    [' a ', false],\n    ['0', false],\n  ] as const)('checks %j as %s', ([input, expected]) => {\n    expect(isBlank(input)).toBe(expected);\n  });\n});\n"],
  ["src/string/is-blank.ts", "/**\n * Checks whether a text is missing or holds only whitespace: a required field left empty.\n *\n * @param input - A string, `null` or `undefined`.\n * @returns `true` for `null`, `undefined`, `''` or whitespace only.\n * @example\n * isBlank('  \\n'); // true\n * isBlank(' a '); // false\n */\nexport function isBlank(input: string | null | undefined): boolean {\n  return input === null || input === undefined || input.trim() === '';\n}\n"],
  ["src/string/kebab-case.spec.ts", "import { kebabCase } from './kebab-case';\n\ndescribe(kebabCase, () => {\n  it.for([\n    ['roundToStep', 'round-to-step'],\n    ['RingBuffer', 'ring-buffer'],\n    ['XMLHttpRequest', 'xml-http-request'],\n    ['USER_ID', 'user-id'],\n    [' Hello  World ', 'hello-world'],\n    ['', ''],\n  ] as const)('converts %j to %j', ([input, expected]) => {\n    expect(kebabCase(input)).toBe(expected);\n  });\n});\n"],
  ["src/string/kebab-case.ts", "import { splitWords } from './split-words';\n\n/**\n * Converts a string to kebab-case: lowercase words joined with `-`, as in file names, CSS classes and URLs.\n *\n * @param input - The identifier or sentence to convert, in any case style.\n * @returns The kebab-case string; `''` when the input has no word.\n * @example\n * kebabCase('roundToStep'); // 'round-to-step'\n * kebabCase('XMLHttpRequest'); // 'xml-http-request'\n */\nexport function kebabCase(input: string): string {\n  return splitWords(input)\n    .map((word) => word.toLowerCase())\n    .join('-');\n}\n"],
  ["src/string/lower-case.spec.ts", "import { lowerCase } from './lower-case';\n\ndescribe(lowerCase, () => {\n  it.for([\n    ['engineRoomTemperature', 'engine room temperature'],\n    ['MAX_SPEED', 'max speed'],\n    ['  Hello---World ', 'hello world'],\n    ['', ''],\n  ] as const)('converts %j to %j', ([input, expected]) => {\n    expect(lowerCase(input)).toBe(expected);\n  });\n});\n"],
  ["src/string/lower-case.ts", "import { splitWords } from './split-words';\n\n/**\n * Converts a string to lower-case words separated by spaces, splitting identifiers such as `camelCase`.\n *\n * @param input - The identifier or sentence to convert, in any case style.\n * @returns The words in lower case, separated by single spaces; `''` when there is no word.\n * @example\n * lowerCase('engineRoomTemperature'); // 'engine room temperature'\n * lowerCase('MAX_SPEED'); // 'max speed'\n */\nexport function lowerCase(input: string): string {\n  return splitWords(input)\n    .map((word) => word.toLowerCase())\n    .join(' ');\n}\n"],
  ["src/string/pascal-case.spec.ts", "import { pascalCase } from './pascal-case';\n\ndescribe(pascalCase, () => {\n  it.for([\n    ['user-id', 'UserId'],\n    ['ring_buffer', 'RingBuffer'],\n    ['userId', 'UserId'],\n    ['HTTP status', 'HttpStatus'],\n    ['', ''],\n  ] as const)('converts %j to %j', ([input, expected]) => {\n    expect(pascalCase(input)).toBe(expected);\n  });\n});\n"],
  ["src/string/pascal-case.ts", "import { capitalize } from './capitalize';\nimport { splitWords } from './split-words';\n\n/**\n * Converts a string to PascalCase: words joined, each capitalized, the rest in lower case.\n *\n * @param input - The identifier or sentence to convert, in any case style.\n * @returns The PascalCase string; `''` when the input has no word.\n * @example\n * pascalCase('user-id'); // 'UserId'\n * pascalCase('ring_buffer'); // 'RingBuffer'\n */\nexport function pascalCase(input: string): string {\n  return splitWords(input)\n    .map((word) => capitalize(word.toLowerCase()))\n    .join('');\n}\n"],
  ["src/string/pluralize.spec.ts", "import { pluralize } from './pluralize';\n\ndescribe(pluralize, () => {\n  it.for([\n    [1, 'alarm'],\n    [-1, 'alarm'],\n    [0, 'alarms'],\n    [3, 'alarms'],\n    [1.5, 'alarms'],\n  ] as const)('picks the form for %s', ([count, expected]) => {\n    expect(pluralize(count, 'alarm', 'alarms', Math.abs(count) === 1)).toBe(expected);\n  });\n\n  it('uses the given plural and singular rule', () => {\n    expect(pluralize(2, 'box', 'boxes', Math.abs(2) === 1)).toBe('boxes');\n    expect(pluralize(0, 'alarme', 'alarmes', true)).toBe('alarme');\n  });\n\n  it('takes the defaults', () => {\n    expect(pluralize(3, 'alarm')).toStrictEqual(pluralize(3, 'alarm', 'alarms', false));\n  });\n});\n"],
  ["src/string/pluralize.ts", "/**\n * Picks the singular or plural form of a word for a count. French takes the singular for 0 too: pass\n * `Math.abs(count) < 2` as `isSingular`.\n *\n * @param count - The number of items.\n * @param singular - The singular form, such as `'alarm'`.\n * @param plural - The plural form. Defaults to `singular` followed by `s`.\n * @param isSingular - Whether the count takes the singular. Defaults to `Math.abs(count) === 1` (English).\n * @returns The form matching the count.\n * @example\n * pluralize(3, 'alarm'); // 'alarms'\n * pluralize(0, 'alarme', 'alarmes', Math.abs(0) < 2); // 'alarme'\n */\nexport function pluralize(\n  count: number,\n  singular: string,\n  plural = `${singular}s`,\n  isSingular = Math.abs(count) === 1,\n): string {\n  return isSingular ? singular : plural;\n}\n"],
  ["src/string/remove-diacritics.spec.ts", "import { removeDiacritics } from './remove-diacritics';\n\ndescribe(removeDiacritics, () => {\n  it.for([\n    ['Crème brûlée à Évian', 'Creme brulee a Evian'],\n    ['Ñandú', 'Nandu'],\n    ['søren straße', 'søren straße'],\n    ['', ''],\n  ] as const)('removes the diacritics of %j', ([input, expected]) => {\n    expect(removeDiacritics(input)).toBe(expected);\n  });\n});\n"],
  ["src/string/remove-diacritics.ts", "const DIACRITICS_PATTERN = /\\p{M}/gv;\n\n/**\n * Removes the accents of a text (`Été` → `Ete`), to search or sort without them. `ø`, `ß` or `æ` stay.\n *\n * @param input - The text.\n * @returns The text without combining marks.\n * @example\n * removeDiacritics('Crème brûlée à Évian'); // 'Creme brulee a Evian'\n */\nexport function removeDiacritics(input: string): string {\n  return input.normalize('NFD').replaceAll(DIACRITICS_PATTERN, '');\n}\n"],
  ["src/string/sentence-case.spec.ts", "import { sentenceCase } from './sentence-case';\n\ndescribe(sentenceCase, () => {\n  it.for([\n    ['engineRoomTemperature', 'Engine room temperature'],\n    ['max_speed_GPS', 'Max speed GPS'],\n    ['user-id', 'User id'],\n    ['SPEED', 'SPEED'],\n    ['depth2Meters', 'Depth 2 meters'],\n    ['', ''],\n  ] as const)('converts %j to %j', ([input, expected]) => {\n    expect(sentenceCase(input)).toBe(expected);\n  });\n});\n"],
  ["src/string/sentence-case.ts", "import { capitalize } from './capitalize';\nimport { splitWords } from './split-words';\n\n/**\n * Converts an identifier to a sentence, to turn a key into a label: the first word capitalized, the others in\n * lower case, acronyms kept.\n *\n * @param input - The identifier or sentence to convert, in any case style.\n * @returns The sentence; `''` when the input has no word.\n * @example\n * sentenceCase('engineRoomTemperature'); // 'Engine room temperature'\n * sentenceCase('max_speed_GPS'); // 'Max speed GPS'\n */\nexport function sentenceCase(input: string): string {\n  const sentence = splitWords(input)\n    .map((word) => (word === word.toUpperCase() ? word : word.toLowerCase()))\n    .join(' ');\n  return capitalize(sentence);\n}\n"],
  ["src/string/slugify.spec.ts", "import { slugify } from './slugify';\n\ndescribe(slugify, () => {\n  it.for([\n    ['Salle des machines — Été 2026', 'salle-des-machines-ete-2026'],\n    ['  Hello, World!  ', 'hello-world'],\n    ['Crème brûlée', 'creme-brulee'],\n    ['engineRoom', 'engine-room'],\n    ['!!!', ''],\n  ] as const)('slugifies %j as %j', ([input, expected]) => {\n    expect(slugify(input)).toBe(expected);\n  });\n});\n"],
  ["src/string/slugify.ts", "import { kebabCase } from './kebab-case';\nimport { removeDiacritics } from './remove-diacritics';\n\n/**\n * Turns a text into a URL- and id-friendly slug: accents removed, lower-case words joined with `-`.\n *\n * @param input - The text, such as a title or a label.\n * @returns The slug; `''` when the text has no letter or digit.\n * @example\n * slugify('Salle des machines — Été 2026'); // 'salle-des-machines-ete-2026'\n * slugify('  Hello, World!  '); // 'hello-world'\n */\nexport function slugify(input: string): string {\n  return kebabCase(removeDiacritics(input));\n}\n"],
  ["src/string/snake-case.spec.ts", "import { snakeCase } from './snake-case';\n\ndescribe(snakeCase, () => {\n  it.for([\n    ['userId', 'user_id'],\n    ['Speed in knots', 'speed_in_knots'],\n    ['ring-buffer', 'ring_buffer'],\n    ['HTTPStatus', 'http_status'],\n    ['', ''],\n  ] as const)('converts %j to %j', ([input, expected]) => {\n    expect(snakeCase(input)).toBe(expected);\n  });\n});\n"],
  ["src/string/snake-case.ts", "import { splitWords } from './split-words';\n\n/**\n * Converts a string to snake_case: lowercase words joined with `_`, as in database columns and JSON keys.\n *\n * @param input - The identifier or sentence to convert, in any case style.\n * @returns The snake_case string; `''` when the input has no word.\n * @example\n * snakeCase('userId'); // 'user_id'\n * snakeCase('Speed in knots'); // 'speed_in_knots'\n */\nexport function snakeCase(input: string): string {\n  return splitWords(input)\n    .map((word) => word.toLowerCase())\n    .join('_');\n}\n"],
  ["src/string/split-words.spec.ts", "import { splitWords } from './split-words';\n\ndescribe(splitWords, () => {\n  it.for([\n    ['helloWorld', ['hello', 'World']],\n    ['HelloWorld', ['Hello', 'World']],\n    ['hello-world', ['hello', 'world']],\n    ['hello_world', ['hello', 'world']],\n    ['HELLO_WORLD', ['HELLO', 'WORLD']],\n    ['  hello   world  ', ['hello', 'world']],\n    ['XMLHttpRequest', ['XML', 'Http', 'Request']],\n    ['getHTTPStatus', ['get', 'HTTP', 'Status']],\n    ['speed2Knots', ['speed', '2', 'Knots']],\n    ['élémentÉtat', ['élément', 'État']],\n    ['a.b/c', ['a', 'b', 'c']],\n  ] as const)('splits %j', ([input, expected]) => {\n    expect(splitWords(input)).toStrictEqual(expected);\n  });\n\n  it.for(['', ' '.repeat(3), '-_./'])('returns no word for %j', (input) => {\n    expect(splitWords(input)).toStrictEqual([]);\n  });\n});\n"],
  ["src/string/split-words.ts", "const DIGIT_PATTERN = /^\\p{N}$/v;\n\ntype CharacterKind = 'digit' | 'lower' | 'separator' | 'upper';\n\nfunction isBoundary(previous: CharacterKind, current: CharacterKind): boolean {\n  const isLetterToDigit = (previous === 'digit') !== (current === 'digit');\n  return previous !== 'separator' && ((previous === 'lower' && current === 'upper') || isLetterToDigit);\n}\n\nfunction kindOf(character: string): CharacterKind {\n  if (character !== character.toLowerCase()) {\n    return 'upper';\n  }\n  if (character !== character.toUpperCase()) {\n    return 'lower';\n  }\n  return DIGIT_PATTERN.test(character) ? 'digit' : 'separator';\n}\n\n/**\n * Splits a string into words, whatever its case style (camelCase, kebab-case, snake_case, spaces…), in one\n * pass. Acronyms and numbers are words of their own.\n *\n * @param input - The identifier or sentence to split, in any case style.\n * @returns The words, with their original case; empty when there is none.\n * @example\n * splitWords('XMLHttpRequest'); // ['XML', 'Http', 'Request']\n * splitWords('user_id-v2 Name'); // ['user', 'id', 'v', '2', 'Name']\n */\nexport function splitWords(input: string): string[] {\n  const result: string[] = [];\n  let word = '';\n  let previous: CharacterKind = 'separator';\n  for (const character of input) {\n    const kind = kindOf(character);\n    if (kind === 'separator') {\n      if (word !== '') {\n        result.push(word);\n      }\n      word = '';\n    } else if (isBoundary(previous, kind)) {\n      result.push(word);\n      word = character;\n    } else if (previous === 'upper' && kind === 'lower' && word.length > 1) {\n      const lastCapital = word.slice(-1);\n      result.push(word.slice(0, -1));\n      word = lastCapital + character;\n    } else {\n      word += character;\n    }\n    previous = kind;\n  }\n  if (word !== '') {\n    result.push(word);\n  }\n  return result;\n}\n"],
  ["src/string/squish.spec.ts", "import { squish } from './squish';\n\ndescribe(squish, () => {\n  it.for([\n    ['  Engine\\n  room   temperature \\t', 'Engine room temperature'],\n    ['already clean', 'already clean'],\n    [' '.repeat(3), ''],\n  ] as const)('squishes %j', ([input, expected]) => {\n    expect(squish(input)).toBe(expected);\n  });\n});\n"],
  ["src/string/squish.ts", "const WHITESPACE_RUN_PATTERN = /\\s+/gv;\n\n/**\n * Trims a text and collapses every run of whitespace, line breaks included, into a single space.\n *\n * @param input - The text.\n * @returns The text on one line, without leading, trailing or repeated whitespace.\n * @example\n * squish('  Engine\\n  room   temperature \\t'); // 'Engine room temperature'\n */\nexport function squish(input: string): string {\n  return input.trim().replaceAll(WHITESPACE_RUN_PATTERN, ' ');\n}\n"],
  ["src/string/title-case.spec.ts", "import { titleCase } from './title-case';\n\ndescribe(titleCase, () => {\n  it.for([\n    ['engine-room', 'Engine Room'],\n    ['maxSpeedGPS', 'Max Speed GPS'],\n    ['user_id', 'User Id'],\n    ['HTTP status code', 'HTTP Status Code'],\n    ['speed2', 'Speed 2'],\n    ['', ''],\n  ] as const)('converts %j to %j', ([input, expected]) => {\n    expect(titleCase(input)).toBe(expected);\n  });\n});\n"],
  ["src/string/title-case.ts", "import { capitalize } from './capitalize';\nimport { splitWords } from './split-words';\n\n/**\n * Converts a string to Title Case: words separated by spaces, each capitalized, acronyms kept.\n *\n * @param input - The identifier or sentence to convert, in any case style.\n * @returns The title; `''` when the input has no word.\n * @example\n * titleCase('engine-room'); // 'Engine Room'\n * titleCase('maxSpeedGPS'); // 'Max Speed GPS'\n */\nexport function titleCase(input: string): string {\n  return splitWords(input)\n    .map((word) => (word === word.toUpperCase() ? word : capitalize(word.toLowerCase())))\n    .join(' ');\n}\n"],
  ["src/string/to-csv.spec.ts", "import { toCsv } from './to-csv';\n\ndescribe(toCsv, () => {\n  it('joins fields and lines', () => {\n    expect(\n      toCsv(\n        [\n          ['time', 'speed'],\n          [new Date(Date.UTC(2026, 0, 15, 12)), 12.5],\n        ],\n        ',',\n        false,\n      ),\n    ).toBe('time,speed\\r\\n2026-01-15T12:00:00.000Z,12.5');\n  });\n\n  it.for([\n    ['a,b', '\"a,b\"'],\n    ['say \"hi\"', '\"say \"\"hi\"\"\"'],\n    ['two\\nlines', '\"two\\nlines\"'],\n    [' padded', '\" padded\"'],\n    [null, ''],\n    [Symbol('s'), ''],\n    [{ a: 1 }, '\"{\"\"a\"\":1}\"'],\n    [10n, '10'],\n    [undefined, ''],\n    [true, 'true'],\n  ] as const)('writes field %# as %s', ([value, expected]) => {\n    expect(toCsv([[value]], ',', false)).toBe(expected);\n  });\n\n  it('uses the separator', () => {\n    expect(toCsv([['1,5', 2]], ';', false)).toBe('1,5;2');\n    expect(toCsv([['a;b']], ';', false)).toBe('\"a;b\"');\n  });\n\n  it('neutralizes formulas on demand', () => {\n    expect(toCsv([['=SUM(A1)', '-3', -3, 'ok']], ',', true)).toBe(\"'=SUM(A1),'-3,-3,ok\");\n    expect(toCsv([['=SUM(A1)']], ',', false)).toBe('=SUM(A1)');\n  });\n\n  it('returns an empty string without row', () => {\n    expect(toCsv([], ',', false)).toBe('');\n  });\n});\n"],
  ["src/string/to-csv.ts", "const NEEDS_QUOTES = /[\\n\\r\"]|^\\s|\\s$/v;\nconst FORMULA_START = /^[\\t\\r+\\-=@]/v;\n\nfunction toText(value: unknown): string {\n  if (typeof value === 'string') {\n    return value;\n  }\n  if (typeof value === 'number' || typeof value === 'boolean' || typeof value === 'bigint') {\n    return String(value);\n  }\n  if (value instanceof Date) {\n    return value.toISOString();\n  }\n  return typeof value === 'object' && value !== null ? JSON.stringify(value) : '';\n}\n\nfunction formatField(value: unknown, separator: string, shouldEscapeFormulas: boolean): string {\n  let text = toText(value);\n  if (shouldEscapeFormulas && typeof value === 'string' && FORMULA_START.test(text)) {\n    text = `'${text}`;\n  }\n  return text.includes(separator) || NEEDS_QUOTES.test(text) ? `\"${text.replaceAll('\"', '\"\"')}\"` : text;\n}\n\n/**\n * Builds CSV text (RFC 4180): fields are quoted when needed, lines end with CRLF. Prepend `'\\uFEFF'` so that\n * Excel reads UTF-8.\n *\n * @param rows - The rows, header first; `null` and `undefined` give empty fields, dates their ISO text,\n * objects their JSON.\n * @param separator - The field separator, such as `';'` for a locale with a decimal comma. Defaults to `','`.\n * @param shouldEscapeFormulas - Whether to prefix a text starting with `=`, `+`, `-` or `@` with `'`, so that a\n * spreadsheet does not run it. Defaults to `true`.\n * @returns The CSV text, without a final line break.\n * @example\n * toCsv([['time', 'speed'], [new Date(0), 12.5]]); // 'time,speed\\r\\n1970-01-01T00:00:00.000Z,12.5'\n */\nexport function toCsv(rows: Iterable<readonly unknown[]>, separator = ',', shouldEscapeFormulas = true): string {\n  const lines: string[] = Array.from(rows, (row) =>\n    row.map((value) => formatField(value, separator, shouldEscapeFormulas)).join(separator),\n  );\n  return lines.join('\\r\\n');\n}\n"],
  ["src/string/train-case.spec.ts", "import { trainCase } from './train-case';\n\ndescribe(trainCase, () => {\n  it.for([\n    ['contentType', 'Content-Type'],\n    ['x_request_id', 'X-Request-Id'],\n    ['', ''],\n  ] as const)('converts %j to %j', ([input, expected]) => {\n    expect(trainCase(input)).toBe(expected);\n  });\n});\n"],
  ["src/string/train-case.ts", "import { capitalize } from './capitalize';\nimport { splitWords } from './split-words';\n\n/**\n * Converts a string to Train-Case: capitalized words joined with `-`, as in HTTP header names.\n *\n * @param input - The identifier or sentence to convert, in any case style.\n * @returns The Train-Case string; `''` when there is no word.\n * @example\n * trainCase('contentType'); // 'Content-Type'\n * trainCase('x_request_id'); // 'X-Request-Id'\n */\nexport function trainCase(input: string): string {\n  return splitWords(input)\n    .map((word) => capitalize(word.toLowerCase()))\n    .join('-');\n}\n"],
  ["src/string/truncate.spec.ts", "import { truncate } from './truncate';\n\ndescribe(truncate, () => {\n  it.for([\n    ['Engine room temperature', 12, 'Engine room…'],\n    ['Short', 12, 'Short'],\n    ['Exactly12chr', 12, 'Exactly12chr'],\n    ['🚢🚢🚢🚢', 3, '🚢🚢…'],\n    ['🇫🇷🇫🇷🇫🇷', 2, '🇫🇷…'],\n    ['abc', 0, ''],\n  ] as const)('truncates %j to %s characters', ([input, maxLength, expected]) => {\n    expect(truncate(input, maxLength, '…')).toBe(expected);\n  });\n\n  it('uses a custom ellipsis', () => {\n    expect(truncate('Engine room temperature', 12, '...')).toBe('Engine ro...');\n    expect(truncate('Engine room temperature', 2, '...')).toBe('..');\n  });\n});\n"],
  ["src/string/truncate.ts", "const graphemeSegmenter = new Intl.Segmenter();\n\nfunction graphemes(text: string): string[] {\n  return Array.from(graphemeSegmenter.segment(text), (part) => part.segment);\n}\n\n/**\n * Shortens a string to a maximum length, with an ellipsis when it is cut. An emoji or an accented letter\n * counts as one character and is never split.\n *\n * @param input - The string to shorten.\n * @param maxLength - The largest length of the result, ellipsis included.\n * @param ellipsis - The text appended when the string is cut. Defaults to `'…'`.\n * @returns The string itself when it fits, the cut string with its ellipsis otherwise.\n * @example\n * truncate('Engine room temperature', 12); // 'Engine room…'\n * truncate('Short', 12); // 'Short'\n * truncate('Engine room temperature', 12, '...'); // 'Engine ro...'\n */\nexport function truncate(input: string, maxLength: number, ellipsis = '…'): string {\n  const characters = graphemes(input);\n  if (characters.length <= maxLength) {\n    return input;\n  }\n  const ellipsisCharacters = graphemes(ellipsis);\n  return ellipsisCharacters.length >= maxLength\n    ? ellipsisCharacters.slice(0, maxLength).join('')\n    : characters.slice(0, maxLength - ellipsisCharacters.length).join('') + ellipsis;\n}\n"],
  ["src/string/uncapitalize.spec.ts", "import { uncapitalize } from './uncapitalize';\n\ndescribe(uncapitalize, () => {\n  it.for([\n    ['RingBuffer', 'ringBuffer'],\n    ['Élan', 'élan'],\n    ['already', 'already'],\n    ['HTTP', 'hTTP'],\n    ['', ''],\n  ] as const)('uncapitalizes %j as %j', ([input, expected]) => {\n    expect(uncapitalize(input)).toBe(expected);\n  });\n});\n"],
  ["src/string/uncapitalize.ts", "/**\n * Lower-cases the first character of a string and leaves the rest unchanged: the reverse of `capitalize`.\n *\n * @param input - The string.\n * @returns The string with its first character in lower case.\n * @example\n * uncapitalize('RingBuffer'); // 'ringBuffer'\n * uncapitalize('Élan'); // 'élan'\n */\nexport function uncapitalize(input: string): string {\n  const first = input.codePointAt(0);\n  if (first === undefined) {\n    return input;\n  }\n  const firstCharacter = String.fromCodePoint(first);\n  return firstCharacter.toLowerCase() + input.slice(firstCharacter.length);\n}\n"],
  ["src/string/upper-case.spec.ts", "import { upperCase } from './upper-case';\n\ndescribe(upperCase, () => {\n  it.for([\n    ['engineRoomTemperature', 'ENGINE ROOM TEMPERATURE'],\n    ['max-speed', 'MAX SPEED'],\n    ['élan vital', 'ÉLAN VITAL'],\n    ['', ''],\n  ] as const)('converts %j to %j', ([input, expected]) => {\n    expect(upperCase(input)).toBe(expected);\n  });\n});\n"],
  ["src/string/upper-case.ts", "import { splitWords } from './split-words';\n\n/**\n * Converts a string to upper-case words separated by spaces, splitting identifiers such as `camelCase`.\n *\n * @param input - The identifier or sentence to convert, in any case style.\n * @returns The words in upper case, separated by single spaces; `''` when there is no word.\n * @example\n * upperCase('engineRoomTemperature'); // 'ENGINE ROOM TEMPERATURE'\n * upperCase('max-speed'); // 'MAX SPEED'\n */\nexport function upperCase(input: string): string {\n  return splitWords(input)\n    .map((word) => word.toUpperCase())\n    .join(' ');\n}\n"],
  ["src/svg-shape/create-svg-arc-path.spec.ts", "import { createSvgArcPath } from './create-svg-arc-path';\nimport { renderSvg } from './testing';\n\ndescribe(createSvgArcPath, () => {\n  it.for([\n    [-90, 180, 'M 10 50 A 40 40 0 0 1 90 50'],\n    [0, -270, 'M 50 10 A 40 40 0 1 0 90 50'],\n    [0, 360, 'M 50 10 A 40 40 0 1 1 50 90 A 40 40 0 1 1 50 10'],\n  ] as const)('draws from %s° over %s°', ([startAngle, sweepAngle, expected]) => {\n    const byId = renderSvg('<circle id=\"hub\" cx=\"50\" cy=\"50\" r=\"5\" /><path id=\"track\" />');\n    expect(createSvgArcPath(byId('track'), { center: byId('hub'), radius: 40, startAngle, sweepAngle })).toBe(expected);\n  });\n\n  it('centers on an element of another group', () => {\n    const byId = renderSvg(\n      '<g transform=\"translate(100 100)\"><circle id=\"hub\" r=\"5\" /></g><g transform=\"scale(2)\"><path id=\"track\" /></g>',\n    );\n    expect(createSvgArcPath(byId('track'), { center: byId('hub'), radius: 10, startAngle: -90, sweepAngle: 180 })).toBe(\n      'M 40 50 A 10 10 0 0 1 60 50',\n    );\n  });\n\n  it('only reads the target, without writing it', () => {\n    const byId = renderSvg('<circle id=\"hub\" cx=\"50\" cy=\"50\" r=\"5\" /><path id=\"track\" />');\n    createSvgArcPath(byId('track'), { center: byId('hub'), radius: 40, startAngle: 0, sweepAngle: 90 });\n    expect(byId('track').hasAttribute('d')).toBe(false);\n  });\n});\n"],
  ["src/svg-shape/create-svg-arc-path.ts", "import { getSvgAnchorPointIn } from '../svg-transform';\nimport { createArcPath } from './internal';\nimport type { SvgArc } from './svg-arc';\n\n/**\n * Creates the `d` of an arc around the center of an element, in any group: the track of a gauge around its\n * hub.\n *\n * @param target - The element in whose coordinates the path is written, such as the `<path>` that receives it.\n * @param arc - The center element, the radius, the start angle and the opening.\n * @returns The path data.\n * @throws {TypeError} When an element is not rendered.\n * @example\n * track.setAttribute('d', createSvgArcPath(track, { center: hub, radius: 40, startAngle: -135, sweepAngle: 270 }));\n */\nexport function createSvgArcPath(target: SVGGraphicsElement, arc: SvgArc): string {\n  const center = getSvgAnchorPointIn(arc.center, 'center', target);\n  return createArcPath(center, arc.radius, arc.startAngle, arc.startAngle + arc.sweepAngle);\n}\n"],
  ["src/svg-shape/create-svg-arc-ticks-path.spec.ts", "import { createSvgArcTicksPath } from './create-svg-arc-ticks-path';\nimport { renderSvg } from './testing';\n\ndescribe(createSvgArcTicksPath, () => {\n  it('draws count + 1 ticks towards the center', () => {\n    const byId = renderSvg('<circle id=\"hub\" cx=\"50\" cy=\"50\" r=\"5\" /><path id=\"ticks\" />');\n    expect(\n      createSvgArcTicksPath(\n        byId('ticks'),\n        { center: byId('hub'), radius: 40, startAngle: -90, sweepAngle: 180 },\n        2,\n        10,\n      ),\n    ).toBe('M 10 50 L 20 50 M 50 10 L 50 20 M 90 50 L 80 50');\n  });\n});\n"],
  ["src/svg-shape/create-svg-arc-ticks-path.ts", "import { getSvgAnchorPointIn } from '../svg-transform';\nimport { formatPoint, polarToCartesian } from './internal';\nimport type { SvgArc } from './svg-arc';\n\n/**\n * Creates the `d` of evenly spaced graduations along an arc, around the center of an element in any group:\n * `count` intervals give `count + 1` ticks. Make one path for the major ticks, one for the minor ones.\n *\n * @param target - The element in whose coordinates the path is written, such as the `<path>` that receives it.\n * @param arc - The center element, the radius where the ticks start, the start angle and the opening.\n * @param count - The number of intervals.\n * @param length - The length of each tick, towards the center; negative to go outwards.\n * @returns The path data, one `M … L …` per tick.\n * @throws {TypeError} When an element is not rendered.\n * @example\n * const arc = { center: hub, radius: 40, startAngle: -135, sweepAngle: 270 };\n * majorTicks.setAttribute('d', createSvgArcTicksPath(majorTicks, arc, 6, 8)); // 7 long ticks\n * minorTicks.setAttribute('d', createSvgArcTicksPath(minorTicks, arc, 30, 4)); // 31 short ones\n */\nexport function createSvgArcTicksPath(target: SVGGraphicsElement, arc: SvgArc, count: number, length: number): string {\n  const center = getSvgAnchorPointIn(arc.center, 'center', target);\n  let d = '';\n  for (let index = 0; index <= count; index++) {\n    const angle = arc.startAngle + (arc.sweepAngle * index) / count;\n    const start = polarToCartesian(center, arc.radius, angle);\n    const end = polarToCartesian(center, arc.radius - length, angle);\n    d += `${index === 0 ? '' : ' '}M ${formatPoint(start)} L ${formatPoint(end)}`;\n  }\n  return d;\n}\n"],
  ["src/svg-shape/create-svg-bar-range-path.spec.ts", "import { createSvgBarRangePath } from './create-svg-bar-range-path';\nimport { renderSvg } from './testing';\n\ndescribe(createSvgBarRangePath, () => {\n  it.for([\n    ['up', 0, 0.25, 'M 0 100 L 20 100 L 20 75 L 0 75 Z'],\n    ['down', 0.8, 1.5, 'M 0 80 L 20 80 L 20 100 L 0 100 Z'],\n    ['right', -1, 0.5, 'M 0 0 L 0 100 L 10 100 L 10 0 Z'],\n    ['left', 0, 0.5, 'M 20 0 L 20 100 L 10 100 L 10 0 Z'],\n  ] as const)('draws a range of a %s bar', ([direction, from, to, expected]) => {\n    const byId = renderSvg('<rect id=\"track\" width=\"20\" height=\"100\" /><path id=\"level\" />');\n    expect(createSvgBarRangePath(byId('level'), { element: byId('track'), direction }, from, to)).toBe(expected);\n  });\n\n  it('throws a TypeError for a path that is not rendered', () => {\n    const byId = renderSvg('<rect id=\"track\" width=\"20\" height=\"100\" />');\n    const notRendered = { getScreenCTM: (): null => null } as unknown as SVGGraphicsElement;\n    expect(() => {\n      createSvgBarRangePath(notRendered, { element: byId('track'), direction: 'up' }, 0, 1);\n    }).toThrow(TypeError);\n  });\n});\n"],
  ["src/svg-shape/create-svg-bar-range-path.ts", "import { clamp } from '../math';\nimport { formatPoint, getBarEdges, lerpPoint } from './internal';\nimport type { SvgBar } from './svg-bar';\n\n/**\n * Creates the `d` of the part of a bar between two ratios, across its whole thickness, in any group: the fill\n * level of a bar graph (0 to the value) or a threshold zone. The ratios are clamped to [0, 1].\n *\n * @param target - The element in whose coordinates the path is written, such as the `<path>` that receives it.\n * @param bar - The element giving the area of the bar, and its direction.\n * @param fromRatio - The start of the range, from 0 (start of the bar) to 1 (end).\n * @param toRatio - The end of the range, in the same way.\n * @returns The closed path data.\n * @throws {TypeError} When an element is not rendered.\n * @example\n * const bar = { element: track, direction: 'up' } as const;\n * level.setAttribute('d', createSvgBarRangePath(level, bar, 0, ratio(value, max))); // the fill level\n * redZone.setAttribute('d', createSvgBarRangePath(redZone, bar, 0.8, 1)); // the top 20 %\n */\nexport function createSvgBarRangePath(\n  target: SVGGraphicsElement,\n  bar: SvgBar,\n  fromRatio: number,\n  toRatio: number,\n): string {\n  const [start0, start1, end0, end1] = getBarEdges(bar, target);\n  const from = clamp(fromRatio);\n  const to = clamp(toRatio);\n  return `M ${formatPoint(lerpPoint(start0, end0, from))} L ${formatPoint(lerpPoint(start1, end1, from))} L ${formatPoint(lerpPoint(start1, end1, to))} L ${formatPoint(lerpPoint(start0, end0, to))} Z`;\n}\n"],
  ["src/svg-shape/create-svg-bar-ticks-path.spec.ts", "import { createSvgBarTicksPath } from './create-svg-bar-ticks-path';\nimport { renderSvg } from './testing';\n\ndescribe(createSvgBarTicksPath, () => {\n  it.for([\n    ['start', 'M 0 100 L 5 100 M 0 50 L 5 50 M 0 0 L 5 0'],\n    ['end', 'M 20 100 L 15 100 M 20 50 L 15 50 M 20 0 L 15 0'],\n  ] as const)('draws ticks from the %s side', ([side, expected]) => {\n    const byId = renderSvg('<rect id=\"track\" width=\"20\" height=\"100\" /><path id=\"ticks\" />');\n    expect(createSvgBarTicksPath(byId('ticks'), { element: byId('track'), direction: 'up' }, 2, 5, side)).toBe(\n      expected,\n    );\n  });\n\n  it('starts from the start side by default', () => {\n    const byId = renderSvg('<rect id=\"track\" width=\"100\" height=\"20\" /><path id=\"ticks\" />');\n    expect(createSvgBarTicksPath(byId('ticks'), { element: byId('track'), direction: 'right' }, 1, 5)).toBe(\n      'M 0 0 L 0 5 M 100 0 L 100 5',\n    );\n  });\n});\n"],
  ["src/svg-shape/create-svg-bar-ticks-path.ts", "import { formatPoint, getBarEdges, lerpPoint } from './internal';\nimport type { SvgBar } from './svg-bar';\n\n/**\n * Creates the `d` of evenly spaced graduations along a bar, in any group: `count` intervals give `count + 1`\n * ticks, across the bar from one of its sides.\n *\n * @param target - The element in whose coordinates the path is written, such as the `<path>` that receives it.\n * @param bar - The element giving the area of the bar, and its direction.\n * @param count - The number of intervals.\n * @param length - The length of each tick, across the bar, in the coordinates of `target`.\n * @param side - The side the ticks start from: `'start'` is the left side of an `'up'` bar, the top side of a\n * `'right'` bar. Defaults to `'start'`.\n * @returns The path data, one `M … L …` per tick.\n * @throws {TypeError} When an element is not rendered.\n * @example\n * majorTicks.setAttribute('d', createSvgBarTicksPath(majorTicks, { element: track, direction: 'up' }, 5, 12));\n */\nexport function createSvgBarTicksPath(\n  target: SVGGraphicsElement,\n  bar: SvgBar,\n  count: number,\n  length: number,\n  side: 'end' | 'start' = 'start',\n): string {\n  const [start0, start1, end0, end1] = getBarEdges(bar, target);\n  let d = '';\n  for (let index = 0; index <= count; index++) {\n    const t = index / count;\n    const first = lerpPoint(start0, end0, t);\n    const second = lerpPoint(start1, end1, t);\n    const from = side === 'start' ? first : second;\n    const across = side === 'start' ? second : first;\n    const ratio = length / Math.hypot(across.x - from.x, across.y - from.y);\n    d += `${index === 0 ? '' : ' '}M ${formatPoint(from)} L ${formatPoint(lerpPoint(from, across, ratio))}`;\n  }\n  return d;\n}\n"],
  ["src/svg-shape/create-svg-pie-path.spec.ts", "import { createSvgPiePath } from './create-svg-pie-path';\nimport { renderSvg } from './testing';\n\ndescribe(createSvgPiePath, () => {\n  it.for([\n    [0, 90, 'M 50 50 L 50 10 A 40 40 0 0 1 90 50 Z'],\n    [0, 360, 'M 50 10 A 40 40 0 1 1 50 90 A 40 40 0 1 1 50 10 Z'],\n  ] as const)('draws a slice from %s° over %s°', ([startAngle, sweepAngle, expected]) => {\n    const byId = renderSvg('<circle id=\"face\" cx=\"50\" cy=\"50\" r=\"5\" /><path id=\"pie\" />');\n    expect(createSvgPiePath(byId('pie'), { center: byId('face'), radius: 40, startAngle, sweepAngle })).toBe(expected);\n  });\n});\n"],
  ["src/svg-shape/create-svg-pie-path.ts", "import { getSvgAnchorPointIn } from '../svg-transform';\nimport { createArcPath, formatPoint } from './internal';\nimport type { SvgArc } from './svg-arc';\n\nconst FULL_TURN = 360;\n\n/**\n * Creates the `d` of a pie slice joined to the center of an element, in any group: a radar sector, a\n * remaining-time disk, to fill. A sweep of 360° gives the full disk.\n *\n * @param target - The element in whose coordinates the path is written, such as the `<path>` that receives it.\n * @param arc - The center element, the radius, the start angle and the opening.\n * @returns The closed path data.\n * @throws {TypeError} When an element is not rendered.\n * @example\n * remaining.setAttribute('d', createSvgPiePath(remaining, { center: face, radius: 30, startAngle: 0, sweepAngle: 360 * ratio }));\n */\nexport function createSvgPiePath(target: SVGGraphicsElement, arc: SvgArc): string {\n  const center = getSvgAnchorPointIn(arc.center, 'center', target);\n  const arcPath = createArcPath(center, arc.radius, arc.startAngle, arc.startAngle + arc.sweepAngle);\n  return Math.abs(arc.sweepAngle) >= FULL_TURN ? `${arcPath} Z` : `M ${formatPoint(center)} L${arcPath.slice(1)} Z`;\n}\n"],
  ["src/svg-shape/get-svg-arc-point.spec.ts", "import { getSvgArcPoint } from './get-svg-arc-point';\nimport { renderSvg } from './testing';\n\ndescribe(getSvgArcPoint, () => {\n  it('finds a point along the arc', () => {\n    const byId = renderSvg('<circle id=\"hub\" cx=\"50\" cy=\"50\" r=\"5\" /><g id=\"labels\"><rect width=\"1\" height=\"1\" /></g>');\n    const point = getSvgArcPoint(\n      byId('labels'),\n      { center: byId('hub'), radius: 40, startAngle: -90, sweepAngle: 180 },\n      0.5,\n    );\n    expect(point.x).toBeCloseTo(50, 6);\n    expect(point.y).toBeCloseTo(10, 6);\n  });\n});\n"],
  ["src/svg-shape/get-svg-arc-point.ts", "import { getSvgAnchorPointIn } from '../svg-transform';\nimport { polarToCartesian } from './internal';\nimport type { SvgArc } from './svg-arc';\n\n/**\n * Finds a point along an arc, in the coordinates of an element of any group: where to put the label of a\n * graduation or a marker.\n *\n * @param target - The element whose coordinates are wanted, such as the `<g>` of the labels.\n * @param arc - The center element, the radius, the start angle and the opening.\n * @param ratio - The position along the arc: 0 at the start, 1 at the end.\n * @returns The point, in the coordinates of `target`.\n * @throws {TypeError} When an element is not rendered.\n * @example\n * const { x, y } = getSvgArcPoint(labels, { ...arc, radius: 28 }, index / 6);\n */\nexport function getSvgArcPoint(target: SVGGraphicsElement, arc: SvgArc, ratio: number): DOMPoint {\n  const center = getSvgAnchorPointIn(arc.center, 'center', target);\n  return polarToCartesian(center, arc.radius, arc.startAngle + arc.sweepAngle * ratio);\n}\n"],
  ["src/svg-shape/index.ts", "// SVG shapes: the `d` of arcs, ticks and pies around an element, and of ranges and ticks along a bar, in any group.\n\nexport type { SvgArc } from './svg-arc';\nexport type { SvgBar } from './svg-bar';\nexport { createSvgArcPath } from './create-svg-arc-path';\nexport { createSvgArcTicksPath } from './create-svg-arc-ticks-path';\nexport { createSvgPiePath } from './create-svg-pie-path';\nexport { getSvgArcPoint } from './get-svg-arc-point';\nexport { createSvgBarRangePath } from './create-svg-bar-range-path';\nexport { createSvgBarTicksPath } from './create-svg-bar-ticks-path';\n"],
  ["src/svg-shape/internal/create-arc-path.ts", "import { formatCoordinate } from './format-coordinate';\nimport { formatPoint } from './format-point';\nimport { polarToCartesian } from './polar-to-cartesian';\n\nconst FULL_TURN = 360;\nconst HALF_TURN = 180;\n\nexport function createArcPath(center: DOMPointReadOnly, radius: number, startAngle: number, endAngle: number): string {\n  const sweep = endAngle - startAngle;\n  const r = formatCoordinate(radius);\n  const direction = sweep > 0 ? 1 : 0;\n  const start = formatPoint(polarToCartesian(center, radius, startAngle));\n  if (Math.abs(sweep) >= FULL_TURN) {\n    const opposite = formatPoint(polarToCartesian(center, radius, startAngle + HALF_TURN));\n    return `M ${start} A ${r} ${r} 0 1 ${direction} ${opposite} A ${r} ${r} 0 1 ${direction} ${start}`;\n  }\n  const largeArc = Math.abs(sweep) > HALF_TURN ? 1 : 0;\n  return `M ${start} A ${r} ${r} 0 ${largeArc} ${direction} ${formatPoint(polarToCartesian(center, radius, endAngle))}`;\n}\n"],
  ["src/svg-shape/internal/format-coordinate.ts", "import { roundToFractionDigits } from '../../math';\n\nconst FRACTION_DIGITS = 3;\n\nexport function formatCoordinate(value: number): string {\n  return String(roundToFractionDigits(value, FRACTION_DIGITS));\n}\n"],
  ["src/svg-shape/internal/format-point.ts", "import { formatCoordinate } from './format-coordinate';\n\nexport function formatPoint(point: DOMPointReadOnly): string {\n  return `${formatCoordinate(point.x)} ${formatCoordinate(point.y)}`;\n}\n"],
  ["src/svg-shape/internal/get-bar-edges.ts", "import type { SvgBar } from '../svg-bar';\nimport { getScreenMatrix } from './get-screen-matrix';\n\n// The start edge of the bar (`start0 → start1`) and its end edge, in the coordinates of `target`.\nexport function getBarEdges(\n  bar: SvgBar,\n  target: SVGGraphicsElement,\n): readonly [DOMPoint, DOMPoint, DOMPoint, DOMPoint] {\n  const matrix = getScreenMatrix(target).inverse().multiply(getScreenMatrix(bar.element));\n  const { x, y, width, height } = bar.element.getBBox();\n  const topLeft = new DOMPoint(x, y).matrixTransform(matrix);\n  const topRight = new DOMPoint(x + width, y).matrixTransform(matrix);\n  const bottomLeft = new DOMPoint(x, y + height).matrixTransform(matrix);\n  const bottomRight = new DOMPoint(x + width, y + height).matrixTransform(matrix);\n  switch (bar.direction) {\n    case 'up': {\n      return [bottomLeft, bottomRight, topLeft, topRight];\n    }\n    case 'down': {\n      return [topLeft, topRight, bottomLeft, bottomRight];\n    }\n    case 'right': {\n      return [topLeft, bottomLeft, topRight, bottomRight];\n    }\n    case 'left': {\n      return [topRight, bottomRight, topLeft, bottomLeft];\n    }\n  }\n}\n"],
  ["src/svg-shape/internal/get-screen-matrix.ts", "export function getScreenMatrix(element: SVGGraphicsElement): DOMMatrix {\n  const matrix = element.getScreenCTM();\n  if (matrix === null) {\n    throw new TypeError('The SVG element is not rendered: it has no screen matrix');\n  }\n  return matrix;\n}\n"],
  ["src/svg-shape/internal/index.ts", "// Helpers shared inside this theme, private to it: not re-exported by the theme index.\n\nexport { createArcPath } from './create-arc-path';\nexport { formatPoint } from './format-point';\nexport { getBarEdges } from './get-bar-edges';\nexport { lerpPoint } from './lerp-point';\nexport { polarToCartesian } from './polar-to-cartesian';\n"],
  ["src/svg-shape/internal/lerp-point.ts", "export function lerpPoint(from: DOMPointReadOnly, to: DOMPointReadOnly, t: number): DOMPoint {\n  return new DOMPoint(from.x + (to.x - from.x) * t, from.y + (to.y - from.y) * t);\n}\n"],
  ["src/svg-shape/internal/polar-to-cartesian.ts", "const HALF_TURN = 180;\nconst RADIANS_PER_DEGREE = Math.PI / HALF_TURN;\n\nexport function polarToCartesian(center: DOMPointReadOnly, radius: number, angleDegrees: number): DOMPoint {\n  const radians = angleDegrees * RADIANS_PER_DEGREE;\n  return new DOMPoint(center.x + radius * Math.sin(radians), center.y - radius * Math.cos(radians));\n}\n"],
  ["src/svg-shape/svg-arc.ts", "/** An arc around the center of an element, for `createSvgArcPath` and its siblings (0° up, clockwise). */\nexport interface SvgArc {\n  /** The element whose visible center is the center of the arc, such as the hub of a gauge. */\n  readonly center: SVGGraphicsElement;\n  /** In the coordinates of the drawn path. */\n  readonly radius: number;\n  /** In degrees. */\n  readonly startAngle: number;\n  /** The opening in degrees: positive clockwise, 360 for a full circle. */\n  readonly sweepAngle: number;\n}\n"],
  ["src/svg-shape/svg-bar.ts", "/**\n * A bar gauge laid on the box of an element, for `createSvgBarRangePath` and `createSvgBarTicksPath`. The bar follows the element in\n * any group, rotated or not.\n */\nexport interface SvgBar {\n  /** The element giving the area of the bar, such as its track `<rect>`. */\n  readonly element: SVGGraphicsElement;\n  /** Where the values grow, in the element's own axes: `'up'` fills from the bottom. */\n  readonly direction: 'down' | 'left' | 'right' | 'up';\n}\n"],
  ["src/svg-shape/testing/index.ts", "// Test helpers of this theme, for its specs.\n\nexport { renderSvg } from './render-svg';\n"],
  ["src/svg-shape/testing/render-svg.ts", "/**\n * Renders SVG markup at the top-left corner of the page, so that screen pixels are SVG user units.\n *\n * @param markup - The content of the `<svg>`.\n * @returns A function returning an element of the scene by its id.\n */\nexport function renderSvg(markup: string): (id: string) => SVGGraphicsElement {\n  document.body.style.margin = '0';\n  document.body.innerHTML = `<svg width=\"400\" height=\"400\" style=\"display: block\">${markup}</svg>`;\n  return (id: string): SVGGraphicsElement => {\n    const element = document.getElementById(id);\n    if (!(element instanceof SVGGraphicsElement)) {\n      throw new TypeError(`No SVG element #${id}`);\n    }\n    return element;\n  };\n}\n"],
  ["src/svg-transform/anchor.ts", "/** One of the 9 points of a box: its corners, the middles of its sides, its center. */\nexport type Anchor =\n  'bottom' | 'bottom-left' | 'bottom-right' | 'center' | 'left' | 'right' | 'top' | 'top-left' | 'top-right';\n"],
  ["src/svg-transform/apply-svg-transforms.spec.ts", "import { applySvgTransforms } from './apply-svg-transforms';\nimport { svgFlipTo } from './svg-flip-to';\nimport { svgPlaceOn } from './svg-place-on';\nimport { svgRotateBy } from './svg-rotate-by';\nimport { svgRotateTo } from './svg-rotate-to';\nimport type { SvgTransformOrder } from './svg-transform-order';\nimport { svgTranslateBy } from './svg-translate-by';\nimport { describeOnScreen, renderSvg } from './testing';\n\nconst SCENE = `\n  <g transform=\"translate(60 60) rotate(30)\"><rect id=\"symbol\" transform=\"scale(-1 1)\" width=\"20\" height=\"10\" /></g>\n  <g transform=\"scale(2)\"><circle id=\"target\" cx=\"100\" cy=\"100\" r=\"5\" /></g>\n`;\n\ndescribe(applySvgTransforms, () => {\n  it('applies each order on what the previous ones give', () => {\n    const byId = renderSvg(SCENE);\n    applySvgTransforms(byId('symbol'), [\n      svgFlipTo(false),\n      svgRotateTo(0),\n      svgPlaceOn(byId('target')),\n      svgTranslateBy(0, -10),\n    ]);\n    expect(describeOnScreen(byId('symbol'))).toMatchObject({\n      x: 190,\n      y: 185,\n      width: 20,\n      height: 10,\n      rotation: 0,\n      isFlipped: false,\n    });\n  });\n\n  it('keeps the transforms already in the list', () => {\n    const byId = renderSvg(SCENE);\n    applySvgTransforms(byId('symbol'), [svgRotateTo(0)]);\n    expect(byId('symbol').transform.baseVal.numberOfItems).toBe(2);\n  });\n\n  it('updates only the changed order', () => {\n    const byId = renderSvg(SCENE);\n    const rotation = svgRotateBy(0);\n    applySvgTransforms(byId('symbol'), [svgFlipTo(false), svgRotateTo(0), svgPlaceOn(byId('target')), rotation]);\n    rotation.set(90);\n    expect(describeOnScreen(byId('symbol'))).toMatchObject({ x: 195, y: 190, width: 10, height: 20, rotation: 90 });\n  });\n\n  it('updates an order followed by others, in the axes the element shows', () => {\n    const byId = renderSvg('<rect id=\"train\" x=\"100\" y=\"100\" width=\"10\" height=\"10\" />');\n    const position = svgTranslateBy(0, 0);\n    applySvgTransforms(byId('train'), [position, svgRotateBy(90)]);\n    position.set(10, 0);\n    expect(describeOnScreen(byId('train'))).toMatchObject({ x: 100, y: 110, rotation: 90 });\n  });\n\n  it('keeps the values of an order changed before it is applied', () => {\n    const byId = renderSvg(SCENE);\n    const rotation = svgRotateTo(0);\n    rotation.set(90);\n    applySvgTransforms(byId('symbol'), [rotation]);\n    expect(describeOnScreen(byId('symbol'))).toMatchObject({ rotation: 90 });\n  });\n\n  it('throws a TypeError for an object that is not an order', () => {\n    const byId = renderSvg(SCENE);\n    const fake: SvgTransformOrder<[]> = { set: (): void => undefined };\n    expect(() => {\n      applySvgTransforms(byId('symbol'), [fake]);\n    }).toThrow(TypeError);\n  });\n\n  it('throws a TypeError for an element outside an svg', () => {\n    const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');\n    expect(() => {\n      applySvgTransforms(rect, [svgTranslateBy(1, 1)]);\n    }).toThrow(TypeError);\n  });\n});\n"],
  ["src/svg-transform/apply-svg-transforms.ts", "import { createMatrix, getOrderState, getOwnerSvg, getScreenMatrix } from './internal';\nimport type { SvgTransformOrder } from './svg-transform-order';\n\n/**\n * Applies orders to an SVG element, in order, each on what the previous ones give: one transform per order\n * is added at the end of its `transform` list. Changing an order later with `set` updates its own transform\n * only, from what the element shows without it.\n *\n * @param element - A rendered SVG element.\n * @param orders - The orders, such as `svgRotateTo(0)`, `svgPlaceOn(target)`, `svgRotateBy(0)`.\n * @throws {TypeError} When the element is not rendered or not inside an `<svg>`, or an order was not created\n * by an order function.\n * @example\n * const rotation = svgRotateBy(0);\n * applySvgTransforms(needle, [svgPlaceOn(hub, 'center', 'bottom'), rotation]);\n * rotation.set(45); // at each frame: 45° more than its first position\n */\nexport function applySvgTransforms(element: SVGGraphicsElement, orders: readonly SvgTransformOrder<never>[]): void {\n  const svg = getOwnerSvg(element);\n  const steps = orders\n    .map((order) => getOrderState(order))\n    .map((state) => ({ state, transform: element.transform.baseVal.appendItem(svg.createSVGTransform()) }));\n\n  for (const [index, { state, transform }] of steps.entries()) {\n    const later = steps.slice(index + 1);\n    state.update = (): void => {\n      transform.setMatrix(createMatrix(element));\n      let after = createMatrix(element);\n      for (const next of later) {\n        after = after.multiply(next.transform.matrix);\n      }\n      const screen = getScreenMatrix(element);\n      const change = state.toChange(element, screen);\n      transform.setMatrix(after.multiply(screen.inverse()).multiply(change).multiply(screen).multiply(after.inverse()));\n    };\n    state.update();\n  }\n}\n"],
  ["src/svg-transform/clear-svg-transforms.spec.ts", "import { clearSvgTransforms } from './clear-svg-transforms';\nimport { renderSvg } from './testing';\n\ndescribe(clearSvgTransforms, () => {\n  it('empties the transform list', () => {\n    const byId = renderSvg('<rect id=\"symbol\" transform=\"translate(5 5) rotate(30)\" width=\"10\" height=\"10\" />');\n    clearSvgTransforms(byId('symbol'));\n    expect(byId('symbol').transform.baseVal.numberOfItems).toBe(0);\n  });\n});\n"],
  ["src/svg-transform/clear-svg-transforms.ts", "/**\n * Empties the `transform` list of an SVG element: it is drawn without any transform.\n *\n * @param element - The SVG element.\n * @example\n * clearSvgTransforms(symbol);\n */\nexport function clearSvgTransforms(element: SVGGraphicsElement): void {\n  element.transform.baseVal.clear();\n}\n"],
  ["src/svg-transform/get-svg-anchor-point-in.spec.ts", "import { getSvgAnchorPointIn } from './get-svg-anchor-point-in';\nimport { renderSvg } from './testing';\n\ndescribe(getSvgAnchorPointIn, () => {\n  it('gives the point in the coordinates of an element of another group', () => {\n    const byId = renderSvg(`\n      <g transform=\"translate(100 100)\"><circle id=\"hub\" r=\"5\" /></g>\n      <g transform=\"scale(2)\"><path id=\"path\" /></g>\n    `);\n    expect(getSvgAnchorPointIn(byId('hub'), 'center', byId('path'))).toMatchObject({ x: 50, y: 50 });\n  });\n\n  it('throws a TypeError for an element that is not rendered', () => {\n    const byId = renderSvg('<circle id=\"hub\" r=\"5\" />');\n    const notRendered = { getScreenCTM: (): null => null } as unknown as SVGGraphicsElement;\n    expect(() => getSvgAnchorPointIn(byId('hub'), 'center', notRendered)).toThrow(TypeError);\n  });\n});\n"],
  ["src/svg-transform/get-svg-anchor-point-in.ts", "import type { Anchor } from './anchor';\nimport { getSvgAnchorPoint } from './get-svg-anchor-point';\nimport { getScreenMatrix } from './internal';\n\n/**\n * Finds an anchor of an element as seen on screen, in the coordinates of another element, whatever groups\n * lie between: the center of a hub for the `setRotate` of a needle drawn in another group.\n *\n * @param element - The element giving the point.\n * @param anchor - The point of its visible box, such as `'center'`.\n * @param target - The element whose coordinates are wanted.\n * @returns The point, in the coordinates of `target`, after its whole `transform` list.\n * @throws {TypeError} When an element is not rendered.\n * @example\n * const hub = getSvgAnchorPointIn(hubElement, 'center', needle);\n */\nexport function getSvgAnchorPointIn(element: SVGGraphicsElement, anchor: Anchor, target: SVGGraphicsElement): DOMPoint {\n  return getSvgAnchorPoint(element, anchor).matrixTransform(getScreenMatrix(target).inverse());\n}\n"],
  ["src/svg-transform/get-svg-anchor-point.spec.ts", "import { getSvgAnchorPoint } from './get-svg-anchor-point';\nimport { renderSvg } from './testing';\n\ndescribe(getSvgAnchorPoint, () => {\n  it.for([\n    ['top-left', 10, 20],\n    ['top-right', 110, 20],\n    ['bottom', 60, 70],\n    ['center', 60, 45],\n  ] as const)('finds the %s anchor', ([anchor, x, y]) => {\n    const byId = renderSvg('<rect id=\"box\" x=\"10\" y=\"20\" width=\"100\" height=\"50\" />');\n    expect(getSvgAnchorPoint(byId('box'), anchor)).toMatchObject({ x, y });\n  });\n\n  it('takes the center by default', () => {\n    const byId = renderSvg('<rect id=\"box\" x=\"10\" y=\"20\" width=\"100\" height=\"50\" />');\n    expect(getSvgAnchorPoint(byId('box'))).toMatchObject({ x: 60, y: 45 });\n  });\n});\n"],
  ["src/svg-transform/get-svg-anchor-point.ts", "import type { Anchor } from './anchor';\nimport { getAnchorPoint } from './internal';\n\n/**\n * Finds an anchor of the box an SVG element takes on screen: a corner, the middle of a side or the center.\n *\n * @param element - A rendered SVG element.\n * @param anchor - The point, such as `'top-right'`. Defaults to `'center'`.\n * @returns The point, in screen pixels.\n * @example\n * getSvgAnchorPoint(symbol, 'top-right'); // DOMPoint { x: 220, y: 92 }\n */\nexport function getSvgAnchorPoint(element: SVGGraphicsElement, anchor: Anchor = 'center'): DOMPoint {\n  return getAnchorPoint(element.getBoundingClientRect(), anchor);\n}\n"],
  ["src/svg-transform/index.ts", "// SVG transforms: orders applied one after the other and changed later, and anchors across groups.\n\nexport type { Anchor } from './anchor';\nexport type { SvgTransformOrder } from './svg-transform-order';\nexport { applySvgTransforms } from './apply-svg-transforms';\nexport { clearSvgTransforms } from './clear-svg-transforms';\nexport { svgRotateBy } from './svg-rotate-by';\nexport { svgRotateTo } from './svg-rotate-to';\nexport { svgFlipTo } from './svg-flip-to';\nexport { svgScaleBy } from './svg-scale-by';\nexport { svgTranslateBy } from './svg-translate-by';\nexport { svgPlaceOn } from './svg-place-on';\nexport { getSvgAnchorPoint } from './get-svg-anchor-point';\nexport { getSvgAnchorPointIn } from './get-svg-anchor-point-in';\n"],
  ["src/svg-transform/internal/create-matrix.ts", "import { getOwnerSvg } from './get-owner-svg';\n\ntype MatrixValues = readonly [a: number, b: number, c: number, d: number, e: number, f: number];\n\nexport function createMatrix(element: SVGGraphicsElement, values: MatrixValues = [1, 0, 0, 1, 0, 0]): DOMMatrix {\n  const matrix = getOwnerSvg(element).createSVGMatrix();\n  [matrix.a, matrix.b, matrix.c, matrix.d, matrix.e, matrix.f] = values;\n  return matrix;\n}\n"],
  ["src/svg-transform/internal/create-order.ts", "import type { SvgTransformOrder } from '../svg-transform-order';\nimport type { OrderState } from './order-states';\nimport { orderStates } from './order-states';\n\n// An order whose effect is the screen change `toChange(element, screen, ...args)`, `screen` being the screen\n// matrix of the element without this order.\nexport function createOrder<TArguments extends unknown[]>(\n  initialArguments: TArguments,\n  toChange: (element: SVGGraphicsElement, screen: DOMMatrix, ...args: TArguments) => DOMMatrix,\n): SvgTransformOrder<TArguments> {\n  let currentArguments = initialArguments;\n  const state: OrderState = {\n    toChange: (element, screen) => toChange(element, screen, ...currentArguments),\n    update: undefined,\n  };\n  const order: SvgTransformOrder<TArguments> = {\n    set(...args: TArguments): void {\n      currentArguments = args;\n      state.update?.();\n    },\n  };\n  orderStates.set(order, state);\n  return order;\n}\n"],
  ["src/svg-transform/internal/get-anchor-point.ts", "import type { Anchor } from '../anchor';\n\nconst MIDDLE = 0.5;\n\nconst FACTORS: Readonly<Record<Anchor, readonly [x: number, y: number]>> = {\n  'top-left': [0, 0],\n  top: [MIDDLE, 0],\n  'top-right': [1, 0],\n  left: [0, MIDDLE],\n  center: [MIDDLE, MIDDLE],\n  right: [1, MIDDLE],\n  'bottom-left': [0, 1],\n  bottom: [MIDDLE, 1],\n  'bottom-right': [1, 1],\n};\n\nexport function getAnchorPoint(box: DOMRectReadOnly, anchor: Anchor): DOMPoint {\n  const [factorX, factorY] = FACTORS[anchor];\n  return new DOMPoint(box.x + box.width * factorX, box.y + box.height * factorY);\n}\n"],
  ["src/svg-transform/internal/get-order-state.ts", "import type { SvgTransformOrder } from '../svg-transform-order';\nimport type { OrderState } from './order-states';\nimport { orderStates } from './order-states';\n\nexport function getOrderState(order: SvgTransformOrder<never>): OrderState {\n  const state = orderStates.get(order);\n  if (state === undefined) {\n    throw new TypeError(\n      'Not an order: create it with svgRotateBy, svgFlipTo, svgScaleBy, svgTranslateBy, svgMove or svgPlaceOn',\n    );\n  }\n  return state;\n}\n"],
  ["src/svg-transform/internal/get-owner-svg.ts", "export function getOwnerSvg(element: SVGGraphicsElement): SVGSVGElement {\n  if (element.ownerSVGElement === null) {\n    throw new TypeError('The element is not inside an <svg>');\n  }\n  return element.ownerSVGElement;\n}\n"],
  ["src/svg-transform/internal/get-screen-matrix.ts", "export function getScreenMatrix(element: SVGGraphicsElement): DOMMatrix {\n  const matrix = element.getScreenCTM();\n  if (matrix === null) {\n    throw new TypeError('The SVG element is not rendered: it has no screen matrix');\n  }\n  return matrix;\n}\n"],
  ["src/svg-transform/internal/in-own-axes.ts", "// The screen change of a transform `local` expressed in the axes of the element as it is displayed.\nexport function inOwnAxes(screen: DOMMatrix, local: DOMMatrix): DOMMatrix {\n  return screen.multiply(local).multiply(screen.inverse());\n}\n"],
  ["src/svg-transform/internal/index.ts", "// Helpers shared inside this theme, private to it: not re-exported by the theme index.\n\nexport { createMatrix } from './create-matrix';\nexport { createOrder } from './create-order';\nexport { getAnchorPoint } from './get-anchor-point';\nexport { getOrderState } from './get-order-state';\nexport { getOwnerSvg } from './get-owner-svg';\nexport { getScreenMatrix } from './get-screen-matrix';\nexport { inOwnAxes } from './in-own-axes';\nexport { isMirrored } from './is-mirrored';\n"],
  ["src/svg-transform/internal/is-mirrored.ts", "export function isMirrored(matrix: DOMMatrix): boolean {\n  return matrix.a * matrix.d < matrix.b * matrix.c;\n}\n"],
  ["src/svg-transform/internal/order-states.ts", "import type { SvgTransformOrder } from '../svg-transform-order';\n\nexport interface OrderState {\n  update: (() => void) | undefined;\n  toChange(element: SVGGraphicsElement, screen: DOMMatrix): DOMMatrix;\n}\n\nexport const orderStates = new WeakMap<SvgTransformOrder<never>, OrderState>();\n"],
  ["src/svg-transform/svg-flip-to.spec.ts", "import { applySvgTransforms } from './apply-svg-transforms';\nimport { svgFlipTo } from './svg-flip-to';\nimport { describeOnScreen, renderSvg } from './testing';\n\ndescribe(svgFlipTo, () => {\n  it('mirrors horizontally around the center by default', () => {\n    const byId = renderSvg(\n      '<g transform=\"rotate(30 50 50)\"><rect id=\"valve\" x=\"40\" y=\"45\" width=\"20\" height=\"10\" /></g>',\n    );\n    const before = describeOnScreen(byId('valve'));\n    applySvgTransforms(byId('valve'), [svgFlipTo()]);\n    expect(describeOnScreen(byId('valve'))).toMatchObject({ x: before.x, y: before.y, isFlipped: true });\n  });\n\n  it('mirrors vertically around an anchor', () => {\n    const byId = renderSvg('<rect id=\"valve\" x=\"10\" y=\"10\" width=\"20\" height=\"10\" />');\n    applySvgTransforms(byId('valve'), [svgFlipTo(true, 'vertical', 'top')]);\n    expect(describeOnScreen(byId('valve'))).toMatchObject({ x: 10, y: 0, isFlipped: true });\n  });\n\n  it.for([\n    [true, 'scale(-1 1) translate(-40 0)', true],\n    [false, 'translate(0 0)', false],\n    [false, 'scale(-1 1) translate(-40 0)', false],\n  ] as const)('makes the element mirrored: %s, from %s', ([isFlipped, transform, expected]) => {\n    const byId = renderSvg(`<rect id=\"label\" transform=\"${transform}\" x=\"10\" y=\"10\" width=\"20\" height=\"10\" />`);\n    applySvgTransforms(byId('label'), [svgFlipTo(isFlipped)]);\n    expect(describeOnScreen(byId('label'))).toMatchObject({ x: 10, y: 10, isFlipped: expected });\n  });\n});\n"],
  ["src/svg-transform/svg-flip-to.ts", "import type { Anchor } from './anchor';\nimport { getSvgAnchorPoint } from './get-svg-anchor-point';\nimport { createMatrix, createOrder, isMirrored } from './internal';\nimport type { SvgTransformOrder } from './svg-transform-order';\n\n/**\n * An order of `applySvgTransforms` that makes the element mirrored or not, as seen on screen, around one of\n * its anchors: `svgFlipTo(false)` makes a mirrored text readable again.\n *\n * @param isFlipped - Whether the element must look mirrored. Defaults to `true`.\n * @param axis - The mirror used when the state changes: `'horizontal'` swaps left and right, `'vertical'` top\n * and bottom. Defaults to `'horizontal'`.\n * @param anchor - The point of the element that stays in place. Defaults to `'center'`.\n * @returns The order, to change with `set(isFlipped, axis, anchor)`.\n * @example\n * const flip = svgFlipTo(false);\n * applySvgTransforms(valve, [flip]);\n * flip.set(true); // facing the other way, same place\n */\nexport function svgFlipTo(\n  isFlipped = true,\n  axis: 'horizontal' | 'vertical' = 'horizontal',\n  anchor: Anchor = 'center',\n): SvgTransformOrder<[isFlipped?: boolean, axis?: 'horizontal' | 'vertical', anchor?: Anchor]> {\n  return createOrder(\n    [isFlipped, axis, anchor],\n    (element, screen, flipped = true, mirror = 'horizontal', point = 'center') => {\n      if (isMirrored(screen) === flipped) {\n        return createMatrix(element);\n      }\n      const { x, y } = getSvgAnchorPoint(element, point);\n      return createMatrix(element, mirror === 'horizontal' ? [-1, 0, 0, 1, 2 * x, 0] : [1, 0, 0, -1, 0, 2 * y]);\n    },\n  );\n}\n"],
  ["src/svg-transform/svg-place-on.spec.ts", "import { applySvgTransforms } from './apply-svg-transforms';\nimport { getSvgAnchorPoint } from './get-svg-anchor-point';\nimport { svgPlaceOn } from './svg-place-on';\nimport { renderSvg } from './testing';\n\ndescribe(svgPlaceOn, () => {\n  it('puts an anchor on an anchor of an element of another group', () => {\n    const byId = renderSvg(`\n      <g transform=\"translate(200 100) rotate(30) scale(1.5)\"><rect id=\"badge\" width=\"10\" height=\"6\" /></g>\n      <g transform=\"translate(50 60)\"><rect id=\"symbol\" width=\"40\" height=\"20\" /></g>\n    `);\n    applySvgTransforms(byId('badge'), [svgPlaceOn(byId('symbol'), 'bottom-left', 'top-right')]);\n    const badge = getSvgAnchorPoint(byId('badge'), 'top-right');\n    expect(badge.x).toBeCloseTo(50, 3);\n    expect(badge.y).toBeCloseTo(80, 3);\n  });\n\n  it('centers on the center by default', () => {\n    const byId = renderSvg(\n      '<rect id=\"label\" width=\"10\" height=\"10\" /><rect id=\"zone\" x=\"100\" y=\"100\" width=\"50\" height=\"50\" />',\n    );\n    applySvgTransforms(byId('label'), [svgPlaceOn(byId('zone'))]);\n    expect(getSvgAnchorPoint(byId('label'))).toMatchObject({ x: 125, y: 125 });\n  });\n});\n"],
  ["src/svg-transform/svg-place-on.ts", "import type { Anchor } from './anchor';\nimport { getSvgAnchorPoint } from './get-svg-anchor-point';\nimport { createMatrix, createOrder } from './internal';\nimport type { SvgTransformOrder } from './svg-transform-order';\n\n/**\n * An order of `applySvgTransforms` that moves the element so that one of its anchors lands on an anchor of\n * another element, as seen on screen, whatever groups each one is in.\n *\n * @param reference - The element to go to.\n * @param referenceAnchor - The point of `reference` to reach. Defaults to `'center'`.\n * @param anchor - The point of the element that lands on it. Defaults to `'center'`.\n * @returns The order, to change with `set(reference, referenceAnchor, anchor)`.\n * @example\n * applySvgTransforms(badge, [svgPlaceOn(symbol, 'bottom-left', 'top-right')]); // the badge corner on the symbol corner\n */\nexport function svgPlaceOn(\n  reference: SVGGraphicsElement,\n  referenceAnchor: Anchor = 'center',\n  anchor: Anchor = 'center',\n): SvgTransformOrder<[reference: SVGGraphicsElement, referenceAnchor?: Anchor, anchor?: Anchor]> {\n  return createOrder(\n    [reference, referenceAnchor, anchor],\n    (element, _screen, other, otherPoint = 'center', point = 'center') => {\n      const to = getSvgAnchorPoint(other, otherPoint);\n      const from = getSvgAnchorPoint(element, point);\n      return createMatrix(element).translate(to.x - from.x, to.y - from.y);\n    },\n  );\n}\n"],
  ["src/svg-transform/svg-rotate-by.spec.ts", "import { applySvgTransforms } from './apply-svg-transforms';\nimport { svgRotateBy } from './svg-rotate-by';\nimport { describeOnScreen, renderSvg } from './testing';\n\ndescribe(svgRotateBy, () => {\n  it('turns from its position before the order, not from the previous value', () => {\n    const byId = renderSvg('<rect id=\"flag\" transform=\"rotate(30 50 50)\" x=\"40\" y=\"45\" width=\"20\" height=\"10\" />');\n    const rotation = svgRotateBy(3);\n    applySvgTransforms(byId('flag'), [rotation]);\n    rotation.set(90);\n    expect(describeOnScreen(byId('flag'))).toMatchObject({ rotation: 120 });\n  });\n\n  it('turns from the default position given by its groups', () => {\n    const byId = renderSvg(\n      '<g transform=\"rotate(90 50 50)\"><rect id=\"bar\" x=\"40\" y=\"45\" width=\"20\" height=\"10\" /></g>',\n    );\n    applySvgTransforms(byId('bar'), [svgRotateBy(90)]);\n    expect(describeOnScreen(byId('bar'))).toMatchObject({ x: 40, y: 45, width: 20, height: 10, rotation: 180 });\n  });\n\n  it('turns around an anchor of another element', () => {\n    const byId = renderSvg(\n      '<rect id=\"needle\" x=\"98\" y=\"60\" width=\"4\" height=\"40\" /><circle id=\"hub\" cx=\"100\" cy=\"100\" r=\"5\" />',\n    );\n    applySvgTransforms(byId('needle'), [svgRotateBy(90, 'center', byId('hub'))]);\n    expect(describeOnScreen(byId('needle'))).toMatchObject({ x: 100, y: 98, width: 40, height: 4, rotation: 90 });\n  });\n});\n"],
  ["src/svg-transform/svg-rotate-by.ts", "import type { Anchor } from './anchor';\nimport { getSvgAnchorPoint } from './get-svg-anchor-point';\nimport { createMatrix, createOrder } from './internal';\nimport type { SvgTransformOrder } from './svg-transform-order';\n\n/**\n * An order of `applySvgTransforms` that turns the element by an angle from its position before this order,\n * clockwise on screen, around an anchor of itself or of another element: `set(90)` after `set(3)` gives 90°\n * from the start, not 93°.\n *\n * @param angleDegrees - The rotation, in degrees.\n * @param anchor - The point that stays in place. Defaults to `'center'`.\n * @param reference - The element giving the anchor, in any group. Defaults to the element itself.\n * @returns The order, to change with `set(angleDegrees, anchor, reference)`.\n * @example\n * const rotation = svgRotateBy(0, 'center', hub);\n * applySvgTransforms(needle, [rotation]);\n * rotation.set(30, 'center', hub); // 30° around the hub, from where it was drawn\n */\nexport function svgRotateBy(\n  angleDegrees: number,\n  anchor: Anchor = 'center',\n  reference?: SVGGraphicsElement,\n): SvgTransformOrder<[angleDegrees: number, anchor?: Anchor, reference?: SVGGraphicsElement]> {\n  return createOrder([angleDegrees, anchor, reference], (element, _screen, angle, point, other) => {\n    const { x, y } = getSvgAnchorPoint(other ?? element, point);\n    return createMatrix(element).translate(x, y).rotate(angle).translate(-x, -y);\n  });\n}\n"],
  ["src/svg-transform/svg-rotate-to.spec.ts", "import { applySvgTransforms } from './apply-svg-transforms';\nimport { svgRotateTo } from './svg-rotate-to';\nimport { describeOnScreen, renderSvg } from './testing';\n\ndescribe(svgRotateTo, () => {\n  it.for([\n    ['rotate(30 50 50)', false],\n    ['rotate(30 50 50) scale(-1 1) translate(-100 0)', true],\n  ] as const)('straightens %s in place with 0', ([transform, isFlipped]) => {\n    const byId = renderSvg(\n      `<g transform=\"rotate(20 50 50)\"><rect id=\"symbol\" transform=\"${transform}\" x=\"40\" y=\"45\" width=\"20\" height=\"10\" /></g>`,\n    );\n    applySvgTransforms(byId('symbol'), [svgRotateTo(0)]);\n    expect(describeOnScreen(byId('symbol'))).toMatchObject({\n      x: 40,\n      y: 45,\n      width: 20,\n      height: 10,\n      rotation: 0,\n      isFlipped,\n    });\n  });\n\n  it('turns to an absolute angle around an anchor', () => {\n    const byId = renderSvg('<rect id=\"flag\" transform=\"rotate(45 40 40)\" x=\"40\" y=\"40\" width=\"20\" height=\"10\" />');\n    applySvgTransforms(byId('flag'), [svgRotateTo(90, 'top-left')]);\n    expect(describeOnScreen(byId('flag'))).toMatchObject({ rotation: 90 });\n  });\n\n  it('turns around an anchor of another element', () => {\n    const byId = renderSvg(\n      '<rect id=\"needle\" x=\"98\" y=\"60\" width=\"4\" height=\"40\" /><circle id=\"hub\" cx=\"100\" cy=\"100\" r=\"5\" />',\n    );\n    applySvgTransforms(byId('needle'), [svgRotateTo(90, 'center', byId('hub'))]);\n    expect(describeOnScreen(byId('needle'))).toMatchObject({ x: 100, y: 98, width: 40, height: 4, rotation: 90 });\n  });\n});\n"],
  ["src/svg-transform/svg-rotate-to.ts", "import type { Anchor } from './anchor';\nimport { getSvgAnchorPoint } from './get-svg-anchor-point';\nimport { createMatrix, createOrder, isMirrored } from './internal';\nimport type { SvgTransformOrder } from './svg-transform-order';\n\nconst HALF_TURN = 180;\nconst DEGREES_PER_RADIAN = HALF_TURN / Math.PI;\n\n/**\n * An order of `applySvgTransforms` that turns the element to an absolute angle on screen, clockwise from\n * upright, around an anchor of itself or of another element: `svgRotateTo(0)` straightens it.\n *\n * @param angleDegrees - The angle on screen, in degrees.\n * @param anchor - The point that stays in place. Defaults to `'center'`.\n * @param reference - The element giving the anchor, in any group. Defaults to the element itself.\n * @returns The order, to change with `set(angleDegrees, anchor, reference)`.\n * @example\n * applySvgTransforms(label, [svgRotateTo(0)]); // upright, whatever its groups\n */\nexport function svgRotateTo(\n  angleDegrees: number,\n  anchor: Anchor = 'center',\n  reference?: SVGGraphicsElement,\n): SvgTransformOrder<[angleDegrees: number, anchor?: Anchor, reference?: SVGGraphicsElement]> {\n  return createOrder([angleDegrees, anchor, reference], (element, screen, angle, point, other) => {\n    const sign = isMirrored(screen) ? -1 : 1;\n    const current = Math.atan2(sign * screen.b, sign * screen.a) * DEGREES_PER_RADIAN;\n    const { x, y } = getSvgAnchorPoint(other ?? element, point);\n    return createMatrix(element)\n      .translate(x, y)\n      .rotate(angle - current)\n      .translate(-x, -y);\n  });\n}\n"],
  ["src/svg-transform/svg-scale-by.spec.ts", "import { applySvgTransforms } from './apply-svg-transforms';\nimport { svgScaleBy } from './svg-scale-by';\nimport { describeOnScreen, renderSvg } from './testing';\n\ndescribe(svgScaleBy, () => {\n  it.for([\n    ['bottom', 1, 1.5, { x: 10, y: 30, width: 20, height: 60 }],\n    ['left', 2, 1, { x: 10, y: 50, width: 40, height: 40 }],\n    ['right', 2, 1, { x: -10, y: 50, width: 40, height: 40 }],\n  ] as const)('grows from the %s anchor', ([anchor, scaleX, scaleY, expected]) => {\n    const byId = renderSvg('<rect id=\"tank\" x=\"10\" y=\"50\" width=\"20\" height=\"40\" />');\n    applySvgTransforms(byId('tank'), [svgScaleBy(scaleX, scaleY, anchor)]);\n    expect(describeOnScreen(byId('tank'))).toMatchObject(expected);\n  });\n\n  it('scales both axes around the center by default', () => {\n    const byId = renderSvg('<rect id=\"tank\" x=\"10\" y=\"10\" width=\"20\" height=\"20\" />');\n    applySvgTransforms(byId('tank'), [svgScaleBy(2)]);\n    expect(describeOnScreen(byId('tank'))).toMatchObject({ x: 0, y: 0, width: 40, height: 40 });\n  });\n});\n"],
  ["src/svg-transform/svg-scale-by.ts", "import type { Anchor } from './anchor';\nimport { createMatrix, createOrder, getAnchorPoint, inOwnAxes } from './internal';\nimport type { SvgTransformOrder } from './svg-transform-order';\n\n/**\n * An order of `applySvgTransforms` that enlarges or shrinks the element in its own axes, around an anchor of\n * its drawing, which gives the direction: with `'left'`, it grows to the right; with `'bottom'`, upwards.\n *\n * @param scaleX - The factor along its width: `2` doubles it.\n * @param scaleY - The factor along its height. Defaults to `scaleX`.\n * @param anchor - The point of its drawing that stays in place. Defaults to `'center'`.\n * @returns The order, to change with `set(scaleX, scaleY, anchor)`.\n * @example\n * const level = svgScaleBy(1, 0, 'bottom');\n * applySvgTransforms(tankLevel, [level]);\n * level.set(1, 0.75, 'bottom'); // filled to 75 %, from the bottom\n */\nexport function svgScaleBy(\n  scaleX: number,\n  scaleY = scaleX,\n  anchor: Anchor = 'center',\n): SvgTransformOrder<[scaleX: number, scaleY?: number, anchor?: Anchor]> {\n  return createOrder([scaleX, scaleY, anchor], (element, screen, sx, sy = sx, point = 'center') => {\n    const { x, y } = getAnchorPoint(element.getBBox(), point);\n    return inOwnAxes(screen, createMatrix(element, [sx, 0, 0, sy, x * (1 - sx), y * (1 - sy)]));\n  });\n}\n"],
  ["src/svg-transform/svg-transform-order.ts", "/**\n * An order of `applySvgTransforms`, created by `svgRotateBy`, `svgRotateTo`, `svgFlipTo`, `svgScaleBy`,\n * `svgTranslateBy` or `svgPlaceOn`: keep it to change its values later with `set`.\n *\n * @template TArguments - The values of the order, the same as the arguments of its function.\n */\nexport interface SvgTransformOrder<TArguments extends unknown[]> {\n  /** Changes the values of the order; once applied, its own transform is updated. */\n  set(...args: TArguments): void;\n}\n"],
  ["src/svg-transform/svg-translate-by.spec.ts", "import { applySvgTransforms } from './apply-svg-transforms';\nimport { svgTranslateBy } from './svg-translate-by';\nimport { describeOnScreen, renderSvg } from './testing';\n\ndescribe(svgTranslateBy, () => {\n  it('moves along the axes of the element', () => {\n    const byId = renderSvg('<rect id=\"train\" transform=\"translate(100 100) rotate(90)\" width=\"10\" height=\"10\" />');\n    applySvgTransforms(byId('train'), [svgTranslateBy(10, 0)]);\n    expect(describeOnScreen(byId('train'))).toMatchObject({ x: 90, y: 110 });\n  });\n});\n"],
  ["src/svg-transform/svg-translate-by.ts", "import { createMatrix, createOrder, inOwnAxes } from './internal';\nimport type { SvgTransformOrder } from './svg-transform-order';\n\n/**\n * An order of `applySvgTransforms` that moves the element along its own axes, in its own units: turned by\n * 90°, \"to the right\" goes down on screen. After `svgRotateTo(0)` and `svgFlipTo(false)`, its axes are those of\n * the screen.\n *\n * @param dx - The distance along its width.\n * @param dy - The distance along its height.\n * @returns The order, to change with `set(dx, dy)`.\n * @example\n * const position = svgTranslateBy(0, 0);\n * applySvgTransforms(train, [position]);\n * position.set(10, 0); // 10 units forward, where the train points\n */\nexport function svgTranslateBy(dx: number, dy: number): SvgTransformOrder<[dx: number, dy: number]> {\n  return createOrder([dx, dy], (element, screen, x, y) => inOwnAxes(screen, createMatrix(element).translate(x, y)));\n}\n"],
  ["src/svg-transform/testing/describe-on-screen.ts", "/**\n * Describes how an element looks on screen, rounded to hide float noise.\n *\n * @param element - A rendered SVG element.\n * @returns Its screen box, its screen rotation in degrees and whether it is mirrored.\n */\nexport function describeOnScreen(element: SVGGraphicsElement): {\n  x: number;\n  y: number;\n  width: number;\n  height: number;\n  rotation: number;\n  isFlipped: boolean;\n} {\n  const box = element.getBoundingClientRect();\n  const matrix = element.getScreenCTM() ?? new DOMMatrix();\n  const isFlipped = matrix.a * matrix.d < matrix.b * matrix.c;\n  const sign = isFlipped ? -1 : 1;\n  const rotation = (Math.atan2(sign * matrix.b, sign * matrix.a) * 180) / Math.PI;\n  return {\n    x: round(box.x),\n    y: round(box.y),\n    width: round(box.width),\n    height: round(box.height),\n    rotation: (round(rotation) + 360) % 360,\n    isFlipped,\n  };\n}\n\nfunction round(value: number): number {\n  return Math.round(value * 100) / 100 + 0;\n}\n"],
  ["src/svg-transform/testing/index.ts", "// Test helpers of this theme, for its specs.\n\nexport { describeOnScreen } from './describe-on-screen';\nexport { renderSvg } from './render-svg';\n"],
  ["src/svg-transform/testing/render-svg.ts", "/**\n * Renders SVG markup at the top-left corner of the page, so that screen pixels are SVG user units.\n *\n * @param markup - The content of the `<svg>`.\n * @returns A function returning an element of the scene by its id.\n */\nexport function renderSvg(markup: string): (id: string) => SVGGraphicsElement {\n  document.body.style.margin = '0';\n  document.body.innerHTML = `<svg width=\"400\" height=\"400\" style=\"display: block\">${markup}</svg>`;\n  return (id: string): SVGGraphicsElement => {\n    const element = document.getElementById(id);\n    if (!(element instanceof SVGGraphicsElement)) {\n      throw new TypeError(`No SVG element #${id}`);\n    }\n    return element;\n  };\n}\n"],
  ["src/types/any-function.spec.ts", "import type { AnyFunction } from './any-function';\n\ndescribe('AnyFunction', () => {\n  it('accepts functions only', () => {\n    expectTypeOf<(a: string) => number>().toExtend<AnyFunction>();\n    expectTypeOf<string>().not.toExtend<AnyFunction>();\n  });\n});\n"],
  ["src/types/any-function.ts", "/**\n * A type for any function, for generic constraints such as `F extends AnyFunction` (safer than `Function`, which also\n * accepts classes and has an untyped call).\n *\n * @example\n * function once<F extends AnyFunction>(fn: F): F;\n */\nexport type AnyFunction = (...arguments_: readonly never[]) => unknown;\n"],
  ["src/types/awaitable.spec.ts", "import type { Awaitable } from './awaitable';\n\ndescribe('Awaitable', () => {\n  it('accepts a value or a promise', () => {\n    expectTypeOf<number>().toExtend<Awaitable<number>>();\n    expectTypeOf<Promise<number>>().toExtend<Awaitable<number>>();\n    expectTypeOf<Promise<string>>().not.toExtend<Awaitable<number>>();\n  });\n});\n"],
  ["src/types/awaitable.ts", "/**\n * A value that is returned directly or through a promise: the result of a callback that may be sync or\n * async.\n *\n * @template T - The value type.\n * @example\n * type Loader = (page: number) => Awaitable<readonly Row[]>;\n */\nexport type Awaitable<T> = PromiseLike<T> | T;\n"],
  ["src/types/brand.ts", "declare const brand: unique symbol;\n\n/**\n * A nominal type: a `T` that cannot be mixed up with another `T` of a different brand.\n *\n * @template T - The underlying type.\n * @template TBrand - The brand name.\n * @example\n * type UserId = Brand<string, 'UserId'>;\n * function toUserId(value: string): UserId {\n *   return value as UserId;\n * }\n */\nexport type Brand<T, TBrand extends string> = T & { readonly [brand]: TBrand };\n"],
  ["src/types/constructor.ts", "/**\n * A type for any class producing a `T`: mixins, dependency injection tokens, `instanceof` helpers.\n *\n * @template T - Type of the instances.\n * @template TArguments - Parameters of the constructor.\n */\nexport type Constructor<T = object, TArguments extends unknown[] = any[]> = new (...parameters: TArguments) => T;\n"],
  ["src/types/deep-partial.spec.ts", "import type { DeepPartial } from './deep-partial';\n\ninterface Settings {\n  readonly chart: { readonly grid: { readonly step: number }; readonly series: { readonly id: string }[] };\n  format(value: number): string;\n}\n\ndescribe('DeepPartial', () => {\n  it('makes every depth optional', () => {\n    expectTypeOf<Omit<DeepPartial<Settings>, 'format'>>().toEqualTypeOf<{\n      readonly chart?: {\n        readonly grid?: { readonly step?: number };\n        readonly series?: readonly { readonly id?: string }[];\n      };\n    }>();\n  });\n\n  it('keeps functions whole', () => {\n    expectTypeOf<DeepPartial<Settings>['format']>().toEqualTypeOf<((value: number) => string) | undefined>();\n  });\n});\n"],
  ["src/types/deep-partial.ts", "/**\n * Makes every property optional, at every depth: a patch of a nested settings object, read-only since a\n * patch is only read. Functions are kept whole; array items are deeply partial.\n *\n * @template T - The type to loosen.\n * @example\n * type SettingsPatch = DeepPartial<Settings>;\n * const patch: SettingsPatch = { chart: { grid: { isVisible: false } } };\n */\nexport type DeepPartial<T> = T extends (...arguments_: readonly never[]) => unknown\n  ? T\n  : T extends readonly (infer Item)[]\n    ? readonly DeepPartial<Item>[]\n    : T extends object\n      ? { readonly [K in keyof T]?: DeepPartial<T[K]> }\n      : T;\n"],
  ["src/types/deep-readonly.spec.ts", "import type { DeepReadonly } from './deep-readonly';\n\ndescribe('DeepReadonly', () => {\n  it('makes every depth read-only', () => {\n    expectTypeOf<DeepReadonly<{ a: { b: number[] } }>>().toEqualTypeOf<{\n      readonly a: { readonly b: readonly number[] };\n    }>();\n  });\n\n  it('keeps functions whole', () => {\n    expectTypeOf<DeepReadonly<{ f(value: number): string }>['f']>().toEqualTypeOf<(value: number) => string>();\n  });\n});\n"],
  ["src/types/deep-readonly.ts", "/**\n * Makes every property and array read-only, at every depth: a frozen configuration, a state snapshot that\n * must not be changed in place.\n *\n * @template T - The type to protect.\n * @example\n * const DEFAULTS: DeepReadonly<Settings> = { chart: { series: [] } };\n */\nexport type DeepReadonly<T> = T extends (...arguments_: readonly never[]) => unknown\n  ? T\n  : T extends readonly (infer Item)[]\n    ? readonly DeepReadonly<Item>[]\n    : T extends object\n      ? { readonly [K in keyof T]: DeepReadonly<T[K]> }\n      : T;\n"],
  ["src/types/element-of.spec.ts", "import type { ElementOf } from './element-of';\n\ndescribe('ElementOf', () => {\n  it('reads the item type', () => {\n    expectTypeOf<ElementOf<readonly ['kn', 'm/s']>>().toEqualTypeOf<'kn' | 'm/s'>();\n    expectTypeOf<ElementOf<number[]>>().toEqualTypeOf<number>();\n  });\n});\n"],
  ["src/types/element-of.ts", "/**\n * Reads the item type of an array or tuple, such as the type of a `const` list of options.\n *\n * @template T - The array type.\n * @example\n * const UNITS = ['kn', 'km/h', 'm/s'] as const;\n * type Unit = ElementOf<typeof UNITS>; // 'kn' | 'km/h' | 'm/s'\n */\nexport type ElementOf<T extends readonly unknown[]> = T[number];\n"],
  ["src/types/entries.spec.ts", "import type { Entries } from './entries';\n\ndescribe('Entries', () => {\n  it('pairs each key with its value type', () => {\n    expectTypeOf<Entries<{ a: number; b: string }>>().toEqualTypeOf<(['a', number] | ['b', string])[]>();\n  });\n});\n"],
  ["src/types/entries.ts", "/**\n * The `[key, value]` pairs of an object type, each key with its own value type: the precise type of\n * `Object.entries`, which widens keys to `string`.\n *\n * @template T - The object type.\n * @example\n * const pairs = Object.entries(limits) as Entries<Limits>;\n */\nexport type Entries<T> = { [K in keyof T]-?: [K, T[K]] }[keyof T][];\n"],
  ["src/types/first-parameter.spec.ts", "import type { FirstParameter } from './first-parameter';\n\ndescribe('FirstParameter', () => {\n  it('reads the first parameter', () => {\n    expectTypeOf<FirstParameter<(event: MouseEvent, index: number) => void>>().toEqualTypeOf<MouseEvent>();\n    expectTypeOf<FirstParameter<() => void>>().toEqualTypeOf<undefined>();\n  });\n});\n"],
  ["src/types/first-parameter.ts", "/**\n * Reads the type of the first parameter of a function, such as the event of a handler.\n *\n * @template F - The function type.\n * @example\n * type Event = FirstParameter<typeof onResize>; // ResizeObserverEntry\n */\nexport type FirstParameter<F extends (...arguments_: readonly never[]) => unknown> = Parameters<F>[0];\n"],
  ["src/types/index.ts", "// Types: TypeScript utility types.\n\nexport type { Brand } from './brand';\nexport type { Constructor } from './constructor';\nexport type { Nullable } from './nullable';\nexport type { Nullish } from './nullish';\nexport type { Optional } from './optional';\nexport type { ValueOf } from './value-of';\nexport type { AnyFunction } from './any-function';\nexport type { Awaitable } from './awaitable';\nexport type { DeepPartial } from './deep-partial';\nexport type { DeepReadonly } from './deep-readonly';\nexport type { ElementOf } from './element-of';\nexport type { Entries } from './entries';\nexport type { FirstParameter } from './first-parameter';\nexport type { KeysOfType } from './pick-by-type';\nexport type { LiteralUnion } from './literal-union';\nexport type { Merge } from './merge';\nexport type { Mutable } from './mutable';\nexport type { NonEmptyArray } from './non-empty-array';\nexport type { PartialKeys } from './partial-keys';\nexport type { PickByType } from './pick-by-type';\nexport type { RequireKeys } from './require-keys';\nexport type { Simplify } from './simplify';\nexport type { UnionToIntersection } from './union-to-intersection';\n"],
  ["src/types/literal-union.spec.ts", "import type { LiteralUnion } from './literal-union';\n\ndescribe('LiteralUnion', () => {\n  it('accepts the literals and the base type', () => {\n    expectTypeOf<'mono'>().toExtend<LiteralUnion<'mono', string>>();\n    expectTypeOf<'serif'>().toExtend<LiteralUnion<'mono', string>>();\n    expectTypeOf<number>().not.toExtend<LiteralUnion<'mono', string>>();\n  });\n});\n"],
  ["src/types/literal-union.ts", "/**\n * A union of known literals that still accepts any value of the base type, without losing autocompletion\n * of the literals (a plain `'a' | 'b' | string` collapses to `string`).\n *\n * @template L - The suggested literals.\n * @template B - The accepted base type.\n * @example\n * type FontFamily = LiteralUnion<'monospace' | 'sans-serif', string>;\n */\nexport type LiteralUnion<L extends B, B extends number | string> = L | (B & Record<never, never>);\n"],
  ["src/types/merge.spec.ts", "import type { Merge } from './merge';\n\ndescribe('Merge', () => {\n  it('lets the second type win', () => {\n    expectTypeOf<Merge<{ a: number; b: number }, { b: string }>>().toEqualTypeOf<{ a: number; b: string }>();\n  });\n});\n"],
  ["src/types/merge.ts", "import type { Simplify } from './simplify';\n\n/**\n * Combines two object types, the properties of the second replacing those of the first (like an object\n * spread `{ ...a, ...b }`), where an intersection would give `never` for conflicting properties.\n *\n * @template A - The base type.\n * @template B - The overriding type.\n * @example\n * type Row = Merge<Sample, { timestamp: Date }>; // `timestamp` becomes a Date\n */\nexport type Merge<A, B> = Simplify<Omit<A, keyof B> & B>;\n"],
  ["src/types/mutable.spec.ts", "import type { Mutable } from './mutable';\n\ndescribe('Mutable', () => {\n  it('removes readonly', () => {\n    expectTypeOf<Mutable<{ readonly x: number }>>().toEqualTypeOf<{ x: number }>();\n  });\n});\n"],
  ["src/types/mutable.ts", "/**\n * Removes `readonly` from the properties of a type, one level deep: a builder filling an object before\n * handing it out as read-only.\n *\n * @template T - The read-only type.\n * @example\n * const draft: Mutable<Point> = { x: 0, y: 0 };\n * draft.x = 10;\n */\nexport type Mutable<T> = { -readonly [K in keyof T]: T[K] };\n"],
  ["src/types/non-empty-array.spec.ts", "import type { NonEmptyArray } from './non-empty-array';\n\ndescribe('NonEmptyArray', () => {\n  it('requires a first item', () => {\n    expectTypeOf<[1]>().toExtend<NonEmptyArray<number>>();\n    expectTypeOf<[]>().not.toExtend<NonEmptyArray<number>>();\n    expectTypeOf<NonEmptyArray<number>[0]>().toEqualTypeOf<number>();\n  });\n});\n"],
  ["src/types/non-empty-array.ts", "/**\n * An array with at least one item, so that its first item is never `undefined`.\n *\n * @template T - The item type.\n * @example\n * function average(values: NonEmptyArray<number>): number;\n */\nexport type NonEmptyArray<T> = readonly [T, ...T[]];\n"],
  ["src/types/nullable.ts", "/**\n * A `T` that may be `null`.\n *\n * @template T - The underlying type.\n */\nexport type Nullable<T> = T | null;\n"],
  ["src/types/nullish.ts", "/**\n * A `T` that may be `null` or `undefined`.\n *\n * @template T - The underlying type.\n */\nexport type Nullish<T> = T | null | undefined;\n"],
  ["src/types/optional.ts", "/**\n * A `T` that may be `undefined`.\n *\n * @template T - The underlying type.\n */\nexport type Optional<T> = T | undefined;\n"],
  ["src/types/partial-keys.spec.ts", "import type { PartialKeys } from './partial-keys';\n\ndescribe('PartialKeys', () => {\n  it('makes the given keys optional only', () => {\n    expectTypeOf<PartialKeys<{ a: number; b: string }, 'a'>>().toEqualTypeOf<{ a?: number; b: string }>();\n  });\n});\n"],
  ["src/types/partial-keys.ts", "import type { Simplify } from './simplify';\n\n/**\n * Makes some properties optional: the input of a factory that fills them with defaults.\n *\n * @template T - The object type.\n * @template K - The keys to make optional.\n * @example\n * function createUser(input: PartialKeys<User, 'id' | 'createdAt'>): User;\n */\nexport type PartialKeys<T, K extends keyof T> = Simplify<Omit<T, K> & Partial<Pick<T, K>>>;\n"],
  ["src/types/pick-by-type.spec.ts", "import type { KeysOfType, PickByType } from './pick-by-type';\n\ndescribe('PickByType', () => {\n  it('keeps the matching properties', () => {\n    expectTypeOf<PickByType<{ a: string; b: number; c: string }, string>>().toEqualTypeOf<{ a: string; c: string }>();\n  });\n});\n\ndescribe('KeysOfType', () => {\n  it('lists the keys of matching properties', () => {\n    interface Sample {\n      name: string;\n      speed: number;\n      heading: number;\n      isValid?: boolean;\n    }\n    expectTypeOf<KeysOfType<Sample, number>>().toEqualTypeOf<'heading' | 'speed'>();\n    expectTypeOf<KeysOfType<Sample, boolean | undefined>>().toEqualTypeOf<'isValid'>();\n  });\n});\n"],
  ["src/types/pick-by-type.ts", "/**\n * Lists the keys of the properties whose type matches: the numeric fields of a record to chart, the\n * boolean flags of a settings object.\n *\n * @template T - The object type.\n * @template V - The property type to look for.\n * @example\n * type NumericField = KeysOfType<Sample, number>; // 'speed' | 'heading'\n */\nexport type KeysOfType<T, V> = { [K in keyof T]-?: T[K] extends V ? K : never }[keyof T];\n\n/**\n * Keeps the properties whose type matches.\n *\n * @template T - The object type.\n * @template V - The property type to keep.\n * @example\n * type Flags = PickByType<Settings, boolean>;\n */\nexport type PickByType<T, V> = Pick<T, KeysOfType<T, V>>;\n"],
  ["src/types/require-keys.spec.ts", "import type { RequireKeys } from './require-keys';\n\ndescribe('RequireKeys', () => {\n  it('requires the given keys only', () => {\n    expectTypeOf<RequireKeys<{ a?: number; b?: string }, 'a'>>().toEqualTypeOf<{ a: number; b?: string }>();\n  });\n});\n"],
  ["src/types/require-keys.ts", "import type { Simplify } from './simplify';\n\n/**\n * Makes some optional properties required: the result of filling in defaults.\n *\n * @template T - The object type.\n * @template K - The keys to require.\n * @example\n * type ResolvedOptions = RequireKeys<Options, 'duration' | 'easing'>;\n */\nexport type RequireKeys<T, K extends keyof T> = Simplify<Omit<T, K> & Required<Pick<T, K>>>;\n"],
  ["src/types/simplify.spec.ts", "import type { Simplify } from './simplify';\n\ndescribe('Simplify', () => {\n  it('flattens an intersection', () => {\n    expectTypeOf<Simplify<{ a: 1 } & { b: 2 }>>().toEqualTypeOf<{ a: 1; b: 2 }>();\n  });\n});\n"],
  ["src/types/simplify.ts", "/**\n * Flattens intersections and mapped types into a plain object type, so that editor tooltips show the\n * properties instead of `A & Omit<B, 'c'>`. The type itself is unchanged.\n *\n * @template T - The type to display flat.\n * @example\n * type Options = Simplify<BaseOptions & { isAnimated: boolean }>;\n */\nexport type Simplify<T> = { [K in keyof T]: T[K] } & {};\n"],
  ["src/types/union-to-intersection.spec.ts", "import type { UnionToIntersection } from './union-to-intersection';\n\ndescribe('UnionToIntersection', () => {\n  it('intersects the members', () => {\n    expectTypeOf<UnionToIntersection<{ a: 1 } | { b: 2 }>>().toEqualTypeOf<{ a: 1 } & { b: 2 }>();\n  });\n});\n"],
  ["src/types/union-to-intersection.ts", "/**\n * Turns a union into the intersection of its members: `A | B` gives `A & B`, to merge the types of a list\n * of mixins or handlers.\n *\n * @template U - The members to intersect, as a union.\n * @example\n * type All = UnionToIntersection<{ a: 1 } | { b: 2 }>; // { a: 1 } & { b: 2 }\n */\nexport type UnionToIntersection<U> = (U extends unknown ? (value: U) => void : never) extends (value: infer I) => void\n  ? I\n  : never;\n"],
  ["src/types/value-of.ts", "/**\n * The union of the value types of an object type, such as a `const` object used as an enum.\n *\n * @template T - The object type.\n * @example\n * const STATUS = { idle: 'idle', running: 'running' } as const;\n * type Status = ValueOf<typeof STATUS>; // 'idle' | 'running'\n */\nexport type ValueOf<T> = T[keyof T];\n"],
];

const destination = path.resolve(process.argv.slice(2).find((argument) => !argument.startsWith('--')) ?? '.');
const isForced = process.argv.includes('--force');
let written = 0;
for (const [file, content] of FILES) {
  const target = path.join(destination, file);
  if (fs.existsSync(target) && !isForced) {
    console.warn('kept (exists): ' + file);
    continue;
  }
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, content);
  written += 1;
}
console.info(written + ' files written in ' + destination + '.');
